SELECT 'moj-all-verified-judgments-review-002-chunk-180' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"842c6dba-8818-5910-9e4e-a46c53cca036","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار لعدم سداد األجرة -وجوب الوفاء بالعقود - دفع املدعى عليه بإقراض املدعي ولم يثبت ذلك -حلف اليمن على نفي الدفع -احلكم بإخاء العقار -إقرار املدعي باستالم العقار خالي ا من الشواغل .","document_number":"34285050","case_number":"33550457","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/1","year":"1434","subject":"إجارة -إخاء عقار لعدم سداد األجرة -وجوب الوفاء بالعقود - دفع املدعى عليه بإقراض املدعي ولم يثبت ذلك -حلف اليمن على نفي الدفع -احلكم بإخاء العقار -إقرار املدعي باستالم العقار خالي ا من الشواغل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/1 :‬هـ‬\n                      ‫ُ‬                 ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34285050 :‬‬\n                         ‫َر ْق ُم الدعوى‪33550457 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34336864‬تاريخه‪1434/10/21 :‬هـ‬\n\n\n      ‫إجــارة ‪ -‬إخــاء عقــار لعــدم ســداد األجــرة ‪ -‬وجــوب الوفــاء بالعقــود ‪-‬‬\n      ‫دفــع املدعــى عليــه بإقــراض املدعــي ولــم يثبــت ذلــك ‪ -‬حلــف اليمــن‬\n      ‫علــى نفــي الدفــع ‪ -‬احلكــم بإخــاء العقــار ‪ -‬إقــرار املدعــي باســتالم‬\n                                                  ‫العقــار خالي ـ ًا مــن الشــواغل ‪.‬‬\n\n\n\n\n                          ‫‪ -1‬قوله تعالى «يا أيها الذين آمنوا أوفوا بالعقود»‬\n                     ‫‪ -2‬قوله صلى اهلل علية وسلم «املسلمون على شروطهم»‬\n      ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم «البينــة علــى املدعــى واليمــن علــى مــن‬\n                                                                                ‫أنكر»‬\n\n\n\n\n      ‫دعــوى املدعــى وكالــة ضــد املدعــى عليــه ومضمــون الدعــوى أن املدعــى‬\n      ‫عليــه قــد اســتأجر مــن املدعــى أصالــة عقــار ًا ملدة تبدأ مــن ‪1427/8/1‬هـ‬\n      ‫إلــى ‪1434/8/1‬ه ـ بأجــرة ســنوية قدرهــا عشــرة اآلف ريــال وان املدعــى‬\n      ‫عليــه قــد خالــف العقــد بتخلفــه عــن ســداد اإليجــار مــن ‪1431/8/28‬ه ـ‬\n      ‫وطلــب املدعــى وكالــة إلــزام املدعــى عليــه بإخــاء العقــار‪ ،‬أجــاب‬\n      ‫املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر أن املدعــى أصالــة قــد أخــذ‬\n      ‫منــه قرضــا قــدرة خمســون ألــف ريــال بعــد اســتالم األجــرة عــام ‪1430‬ه ـ‬\n\n‫‪313‬‬\n\f‫وعندمــا طالبــه بالقــرض ســلمه عشــرة اآلف ريــال والباقــي ذكــر انــه‬\n‫ســوف يحســمها مــن األجــرة ولــذا فقــد طلــب املدعــى عليــه صــرف النظــر‬\n‫عــن الدعــوى‪ ،‬أجــاب املدعــى وكالــة عــن دعــوى القــرض باإلنــكار‪،‬‬\n‫قــرر املدعــى عليــه عــدم وجــود بينــة علــى دعــوى القــرض وطلــب ميــن‬\n‫املدعــى أصالــة‪ ،‬حضــر املدعــى أصالــة وحلــف اليمــن علــى عــدم‬\n‫اســتالم األجــرة األعــوام ‪ 1432‬و ‪ 1433‬و ‪ 1434‬ه ـ وان دعــوى القــرض‬\n‫غيــر صحيحــة‪ ،‬جــرى االطــاع علــى العقــد بــن الطرفــن ‪ -‬ولألســباب‬\n‫املرصــودة يف نــص القضيــة ولقولــه تعالــى ((يــا أيهــا الذيــن امنــوا أوفــوا‬\n‫بالعقــود)) صــدر احلكــم علــى املدعــى عليــه بإخــاء العقــار وتســليمه‬\n‫للمدعــى خاليــا مــن الشــواغل‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪،‬‬\n‫صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة باملصادقــة علــى‬\n             ‫احلكم‪،‬قــرر املدعــى اســتالمه للعقــار خاليــا مــن الشــواغل ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33550457‬وتاريــخ‬\n‫‪1433/08/27‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331614840‬وتاريــخ‬\n‫‪1433/08/27‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/01/20‬ه ـ افتتحت‬\n‫اجللســة الســاعة الثامنــة والنصــف لســماع دعــوى ضــد ســجل مدنــي رقــم‬\n‫بخصــوص دعــوى إخــاء عقــار مــن مســتأجر حاضــر ‪ ،‬وفيهــا حضــر‬\n‫املدعــى عليــه ولــم يحضــر املدعــي وال مــن ينــوب عنــه ولــم يتقــدم بعــذر‬\n‫تقبلــه احملكمــة وقــد انتهــى الوقــت احملــدد لنظــر الدعــوى واملقــرر‬\n                                                                                     ‫‪314‬‬\n\f      ‫الســاعة الثامنــة وعليــه مت شــطب الدعــوى للمــرة األولــى حســب‬\n      ‫التعليمــات وللبيــان جــرى حتريــره‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/20‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة مبكــة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 33550457‬وتاريــخ ‪1433/08/27‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331614840‬وتاريــخ ‪1433/08/27‬ه ـ‬\n      ‫حضــر ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪.........‬‬\n      ‫بصفتــه وكيــا عــن مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة مبكــة رقــم ‪ 33347178‬واملخولــة لــه حــق املرافعــة واملدافعــة‪..‬‬\n      ‫الــخ وحضــر حلضــوره ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫وبســؤال املدعــي وكالــة عــن دعــواه قــال إن املدعــى عليــه اســتأجر مــن‬\n      ‫موكلــي العقــار الواقــع يف وادي‪ ......‬ملــدة تبــدأ مــن ‪1427/8/1‬ه ـ إلــى‬\n      ‫‪1434/8/1‬ه ـ بأجــرة ســنوية مقدارهــا (‪ )10000‬عشــرة أالف ريــال‬\n      ‫مبوجــب العقــد الصــادر مــن مكتــب ‪ ...‬برقــم وتاريــخ ‪1427/4/15‬ه ـ‬\n      ‫وقــد تخلــف املدعــى عليــه عــن ســداد األجــرة مــن تاريــخ ‪1431/8/28‬ه ـ‬\n      ‫حتــى اآلن وملخالفتــه للعقــد أطلــب احلكــم علــى املدعــى عليــه بإخــاء‬\n      ‫العقــار هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكــره‬\n      ‫املدعــي وكالــة مــن أننــي اســتأجرت العقــار املذكــور املــدة املذكــورة‬\n      ‫باألجــرة كذلــك املذكــورة فصحيــح وقــد أقتــرض منــي مبلغــا ومقــداره‬\n      ‫(‪ )50000‬خمســون ألــف ريــال بعــد اســتالمه ألجــرة عــام ‪1430‬ه ـ‬\n      ‫وعندمــا طالبتــه بــه أعطانــي (‪)10000‬عشــرة أالف ريــال والباقــي‬\n      ‫ذكــر أنــه ســوف يحســمها مــن األجــرة أطلــب صــرف النظــر عــن دعــواه‬\n\n\n‫‪315‬‬\n\f‫وبعــرض ذلــك علــى املدعــي وكالــة قــال الصحيــح مــا ذكــرت وبســؤال‬\n‫املدعــى عليــه البينــة علــى مــا ذكــر قــال أطلــب مهلــة إلحضارهــا عليــه‬\n‫رفعــت اجللســة ويف جلســة أخــرى حضــر الطرفــان وبســؤال املدعــى عليــه‬\n‫عــن بينتــه التــي طلــب مهلــة إلحضارهــا قــال إن املدعــي هــو مــن الشــهود‬\n‫كمــا أنــه منــع بقيــة الشــهود مــن احلضــور ولكــن لــدي شــاهد يدعــى ‪...‬‬\n‫وهــو ال يســتطيع احلضــور اليــوم واطلــب مهلــة إلحضــاره هكــذا أجــاب‬\n‫فقــال املدعــي إننــي تضــررت كثيــرا مــن بقائــه يف ملكــي واطلــب‬\n‫احلكــم عليــه بإخــاء العقــار وعنــد وصــول القضيــة لهــذا احلــد رفعــت‬\n‫اجللســة مــع إعالمهمــا احلضــور يــوم غــد الســاعة الواحــد ظهــرا إجابــة‬\n‫لطلــب املدعــى عليــه إلحضــار بينتــه التــي ذكــر مــع إفهامــه بــأن هــذه‬\n                                      ‫هــي املهلــة األخيــرة ويف املوعــد احملــدد‬\n‫احلمــد هلل وحــده وبعــد فبعــد طباعــة الضبــط رفــض املدعــى عليــه‬\n‫التوقيــع عليــه فقــد جــرى إعــداد هــذه احملضــر بشــهادة كاتبــه وللبيــان‬\n‫جــرى حتريــره وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم حــرر يف ‪1434/5/21‬ه ـ‬\n‫حضــر الطرفــان فســألت املدعــى عليــه عــن بينتــه فقــال بعــد أن خرجــت‬\n‫مــن اجللســة اتصلــت بالشــاهد فــإذا بــه قــد انقلــب علــي فبينتــي قــد حــال‬\n‫خصمــي بينــي وبينهــا فأفهمتــه بــأن لــه ميــن املدعــي علــى نفــي دعــواه‬\n‫فقــال اطلــب ميينــه فجــرى عــرض ذلــك علــى املدعــي وكالــة فقــال أطلــب‬\n‫مهلــة لعــرض ذلــك علــى موكلــي وإحضــاره ألداء اليمــن ففهــم فأجبتــه‬\n‫لطلبــه وعليــه رفعــت اجللســة ويف جلســة أخــرى حضــر ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم وحضــر حلضــوره املدعــى عليــه وقــال‬\n‫املدعــي أصالــة ال مانــع لــدي مــن أداء اليمــن علــى نفــي دعــوى املدعــى‬\n\n\n                                                                                      ‫‪316‬‬\n\f      ‫عليــه فجــرى بيــان عاقبــة اليمــن الكاذبــة فحلــف بعــد إذنــي لــه قائــا‬\n      ‫واهلل العظيــم إننــي لــم أســتلم مــن املدعــى عليــه أجــرة عــام ‪1432‬ه ـ وعــام‬\n      ‫‪1433‬ه ـ وعــام ‪1434‬ه ـ ولــم أقتــرض منــه شــيئا واهلل العظيــم هكــذا‬\n      ‫حلــف فبذلــك جــرى اإلطــاع علــى العقــد الصــادر مــن مكتــب ‪ ...‬برقــم‬\n      ‫‪ 59‬وتاريــخ ‪1427/4/15‬ه ـ واملتضمــن املســتأجر املؤجــر العقــار الواقــع‬\n      ‫يف حــي ‪ ...‬شــارع ‪ ...‬الشــقة الواقعــة بالــدور األرضــي األجــرة عشــرة‬\n      ‫أالف كمــا تضمــن البنــد اخلامــس منــه « علــى املســتأجر دفــع األجــرة‬\n      ‫واســتهالك املــاء والكهربــاء يف أول كل شــهر أو يف أول كل ســنة إذا‬\n      ‫كان اإليجــار ســنويا « وبعرضــه علــى الطرفــن صادقــا عليــه فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وميــن املدعــي ومــا جــرى اإلطــاع عليــه‬\n      ‫ولقولــه تعالــي «يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود» ولقولــه صلــى اهلل‬\n      ‫عليــه وســلم « املســلمون علــى شــروطهم « ولقولــه صلــى اهلل عليــه وســلم‬\n      ‫«البينــة علــى املدعــي واليمــن علــى مــن أنكــر» وجلميــع مــا ذكــر بعاليــة‬\n      ‫فقــد حكمــت علــى املدعــى عليــه بإخــاء العقــار املوصــوف يف الدعــوى‬\n      ‫وتســليمه للمدعــي خاليــا مــن الشــواغل وبعرضــه علــى الطرفــن قــرر‬\n      ‫املدعــى عليــه عــدم القناعــة واســتعد بتقــدمي الئحــة إعتراضيــة فأفهمتــه‬\n      ‫بتعليمــات االســتئناف وأن عليــه تقــدمي الالئحــة االعتراضيــة خــال مــدة‬\n      ‫أقصاهــا ثالثــون يومــا مــن تاريــخ صــدور احلكــم فــإذا انتهــت املــدة ولــم‬\n      ‫يتقــدم بالئحتــه االعتراضيــة يســقط حقــه يف االســتئناف و يكــون‬\n      ‫احلكــم قــد اكتســب الصفــة القطعيــة ففهــم ذلــك وبــاهلل التوفيــق‬\n                                      ‫وصلــى اهلل عليــه وســلم حــرر يف‪1434/8/1‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد جــرى تســليم املدعــى عليــه نســخة احلكــم‬\n      ‫وأفهمتــه بــأن املــدة االعتراضيــة تبــدأ من ‪1434/8/1‬ه ـ وإذا انتهت املدة‬\n\n\n‫‪317‬‬\n\f‫االعتراضيــة مبــرور ثالثــن يومــا فيســط حقــه يف االعتــراض ويكتســب‬\n‫احلكــم الصفــة القطعيــة ففهــم ذلــك وللبيــان جــرى حتريــره وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                        ‫حــرر يف ‪ 1434/8/1‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1435/1/10‬ه ـ حضــر‬\n‫املدعــي ‪...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪...........‬‬\n‫وقــرر وهــو بكامــل أهليتــه املعتبــرة شــرعا اســتالمه للعقــار محــل النــزاع‬\n‫خاليــا مــن الشــواغل عليــه فقــد ثبــت لــدي هــذا اإلقــرار وبــه تكــون‬\n‫القضيــة منتهيــة وللبيــان جــرى حتريــره وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى الــه وصحبــه وســلم حــرر يف ‪1435/1/10‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‬\n‫‪ 331614840‬وتاريــخ ‪1434/9/15‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة الشــيخ القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل‬\n‫بعــدد ‪ 34285050‬وتاريــخ ‪1434/8/1‬هـ ـ واملتضمــن دعــوى‪ .....‬ضــد‪......‬‬\n                                          ‫واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                            ‫وصحبــه وســلم ‪،،،‬‬\n\n\n\n\n                                                                                    ‫‪318‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":313,"source_page_end":318,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a225adf97bc72d28e7d6448c7a6134de1f64cd3b5752850a2e0e66ee22797751","normalized_text_hash":"47a0a84a5284682240c8af9683a6e6d4ab211c5396dbe561c1cf8f52d1b32dbf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p313-34285050"},{"id":"723c338a-aeca-5d32-bbcd-0f22863f44c1","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -امتناع املدعى عليه عن دفع األجرة وجتديد العقد -طلب إخاء العقار -شهادة شاهدين عدل -وجوب الوفاء بالعقود -تغيب املدعى عليه واستتاره عن األنظار يضعف جانبه -حكم بإخاء العقار -الغائب على حجته متى حضر .","document_number":"34301207","case_number":"34224794","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/21","year":"1434","subject":"إجارة -امتناع املدعى عليه عن دفع األجرة وجتديد العقد -طلب إخاء العقار -شهادة شاهدين عدل -وجوب الوفاء بالعقود -تغيب املدعى عليه واستتاره عن األنظار يضعف جانبه -حكم بإخاء العقار -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/21 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34301207 :‬‬\n                         ‫َر ْق ُم الدعوى‪34224794 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34351258‬تاريخه‪1434/11/5 :‬هـ‬\n\n\n      ‫إجــارة‪ -‬امتنــاع املدعــى عليــه عــن دفــع األجــرة وجتديــد العقــد‪ -‬طلــب‬\n      ‫إخــاء العقــار‪ -‬شــهادة شــاهدين عــدل‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬تغيــب‬\n      ‫املدعــى عليــه واســتتاره عــن األنظــار يضعــف جانبــه ‪ -‬حكــم بإخــاء‬\n                                   ‫العقــار ‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n                            ‫آم ُنوا َأوْفُ وا ِبا ْل ُع ُقودِ}‬ ‫‪ .1‬قوله تعالى { َيا َأ ُّي َها ا َّلذِ َ‬\n                                                            ‫ين َ‬\n                          ‫‪ .2‬قوله صلى اهلل عليه وسلم (( ال ضرر وال ضرار ))‬\n      ‫‪ .3‬مــا قــرره جمــع مــن أهــل العلــم مــن جــواز احلكــم علــى الغائب املســتتر‬\n                                                                                            ‫عــن األنظار‬\n\n\n\n\n      ‫ادعــى املدعــي بالوكالــة ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم‬\n      ‫والــذي تعــذر إبالغــه بالطــرق الرســمية ولــذا تقــرر ســماع الدعــوى غيابي ًا‬\n      ‫ـاء‬\n        ‫ومضمــون الدعــوى أن املدعــى عليــه اســتأجر كامــل الــدار أرضـ ًا وبنـ ً‬\n      ‫املوصوفــة يف ضبــط القضيــة مــن موكلــه املدعــي مــن قرابــة العشــرين‬\n      ‫عامـ ًا و لكنــه يف اخلمــس الســنوات األخيــرة لــم يســلم شــيئ ًا مــن األجــرة‬\n      ‫ويرفــض جتديــد العقــد وطلــب املدعــي وكالــة احلكــم علــى املدعــى‬\n      ‫عليــه بإخــاء العقــار‪ ،‬احضــر املدعــي وكالــة بينــة موصلــة وهمــا‬\n\n‫‪319‬‬\n\f‫شــاهدان مت تعديلهمــا شــرع ًا شــهدا بصحــة الدعــوى‪ ،‬مت االطــاع علــى‬\n‫صــك ملكيــة العقــار فوجــده ناظــر القضيــة يتضمــن مــا ذكــره املدعــي‬\n‫آم ُنــوا َأ ْو ُفــوا‬\n                    ‫{يــا َأ ُّي َهــا ا َلّذِ يـ َـن َ‬\n                                                     ‫ـاء علــى مــا تقــدم ولقولــه تعالــى َ‬\n                                                                                          ‫يف دعــواه‪ ،‬بنـ ً‬\n‫ِبا ْل ُع ُقــو ِد } و قولــه صلــى اهلل عليــه وســلم (( ال ضــرر وال ضــرار)) ولقــول‬\n‫جمــع مــن أهــل العلــم مــن جــواز احلكــم علــى الغائب املســتتر عــن األنظار‬\n‫ولكــون تغيــب املدعــى عليــه واســتتاره عــن األنظــار يضعــف جانبــه فقــد‬\n‫صــدر احلكــم علــى املدعــى عليــه بإخــاء العقــار محــل الدعــوى والغائــب‬\n‫علــى حجتــه إذا حضــر‪ ،‬مت إرســال نســخة مــن الصــك للمدعــى عليــه‪،‬‬\n‫صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة باملوافقــة علــى‬\n                                                           ‫احلكــم والغائــب علــى حجتــه إذا حضــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 34224794‬وتاريــخ‬\n‫‪1434/05/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341192381‬وتاريــخ‬\n‫‪1434/05/15‬ه ـ ففــي يــوم األحــد املوافق‪1434/08/07‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 09 : 30‬وفيها حضر ‪ ...........‬ســعودي اجلنســية مبوجب‬\n‫الســجل املدنــي رقــم‪ ...........‬بصفتــه وكيــا عــن ‪...........‬ســعودية اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم‪ ...........‬مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة العــدل الثانيــة مبكــة برقــم ‪ .........‬يف ‪1432/04/08‬ه ـ املخولــة‬\n‫لــه فيهــا حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار ولــم يحضــر‬\n‫املدعــى عليــه وقــد وردتنــا إفــادة محضــر اخلصــوم رقــم ‪331676976‬‬\n                                                                                                              ‫‪320‬‬\n\f      ‫يف ‪1433/09/10‬ه ـ للجلســة املؤرخــة يف ‪1433/10/25‬ه ـ املتضمنــة (‬\n      ‫مت الوصــول إلــى العنــوان ولــم جنــد مــن يــرد علينــا ألكثــر مــن مــرة )‬\n      ‫كمــا ســبق وأن جــرت الكتابــة لســعادة مديــر شــعبة أمــن احملاكــم‬\n      ‫الشــرعية برقــم ‪ 34542207‬يف ‪1434/03/02‬ه ـ للبحــث عــن املدعــى‬\n      ‫عليــه وإحضــاره بالقــوة اجلبريــة مخفــورا يف أقــرب وقــت فوردنــا خطابهــم‬\n      ‫رقــم ‪.........‬يف ‪1434/05/13‬ه ـ املتضمــن مانصــه ( مت البحــث والتحــري‬\n      ‫عــن املذكــور مــن قبــل أفــراد وحــدة البحــث واتضــح أنــه غيــر متواجــد‬\n      ‫مبنزلــه ومت وضــع اخلفــارة الســرية علــى منزلــه طيلــة الفتــرة املاضيــة‬\n      ‫ولــم يشــاهد املذكــور ) عليــه فقــد قــررت الســير يف نظــر الدعــوى‬\n      ‫غيابيــا وبســؤال املدعــي وكالــة عــن دعــواه ادعــى قائــا إن املدعــى‬\n      ‫عليــه اســتأجر كامــل الــدار أرضــا وبنــاء الكائنــة ب‪ .........‬بحــارة‬\n      ‫‪.........‬املشــتملة علــى ثالثــة أدوار كل دور غرفتــن اململــوك ملوكلتــي‬\n      ‫مبوجــب الصــك الصــادر مــن كتابــة العــدل األولــى مبكــة رقــم ‪.........‬‬\n      ‫يف ‪1394/02/03‬ه ـ حيــث إن املدعــى عليــه مســتأجر لهــذا العقــار مــن‬\n      ‫قرابــة عشــرين عامــا إال أنــه يف اخلمــس ســنوات األخيــرة لــم يدفــع شــيئا‬\n      ‫مــن األجــرة ويرفــض جتديــد العقــد أطلــب احلكــم عليــه بإخــاء العقــار‬\n      ‫املذكــور وبســؤاله عــن بينتــه أحضــر للشــهادة كل مــن ‪...........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...........‬و‪ ...........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم‪ ...........‬وبطلــب الشــهادة منهمــا شــهد كل‬\n      ‫واحــد مبفــرده قائــا أشــهد بــاهلل العظيــم أن املدعــى عليــه الغائــب‬\n      ‫مســتأجر للعقــار اململــوك للمدعيــة أصالــة املذكــور يف الدعــوى وذلــك‬\n      ‫طيلــة عشــرين عامــا ولــم يدفــع أجــرة اخلمــس الســنوات األخيــرة ويرفــض‬\n      ‫املواجهــة أو جتديــد عقــد اإليجــار هكــذا شــهدا ثــم جــرى تزكيــة‬\n\n\n‫‪321‬‬\n\f‫الشــاهدين املذكوريــن مــن قبــل كل مــن ‪...........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم‪ ...........‬و‪ ...........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم‪ ...........‬وبســؤال املدعــي هــل لديــه مزيــد بينــة قــال ال‬\n‫وبطلــب صــك امللكيــة منــه أبــرز الصــك رقــم ‪.........‬يف ‪1394/02/03‬ه ـ‬\n‫الصــادر مــن كتابــة العــدل األولــى مبكــة وباالطــاع عليــه وجدتــه‬\n‫يتضمــن مــا ذكــره املدعــي وكالــة يف دعــواه فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة والبينــة ولقولــه تعالــى ( يــا أيهــا الذيــن آمنــوا أوفــوا‬\n‫بالعقــود ) وقولــه صلــى اهلل عليــه وســلم ( ال ضــرر وال ضــرار) وملــا‬\n‫ذكــره جمــع مــن احملققــن مــن جــواز احلكــم علــى الغائــب املســتتر عــن‬\n‫األنظــار ولكــون تغيــب املدعــى عليــه واســتتاره عــن األنظــار يضعــف‬\n‫جانبــه جلميــع مــا ســبق حكمــت علــى املدعــى عليــه بإخــاء العقــار‬\n‫محــل الدعــوى والغائــب علــى حجتــه متــى مــا حضــر وبعــرض احلكــم‬\n‫علــى املدعــي وكالــة قنــع بــه فأمــرت بإخــراج صــك باحلكــم وإرســال‬\n‫نســخة منــه للمدعــى عليــه لتبليغــه بــه وإفهامــه بــأن عليــه تقــدمي الئحتــه‬\n‫االعتراضيــة خــال ثالثــن يومــا تبــدأ مــن تاريــخ االســتالم وإال فــإن‬\n‫حقــه يف طلــب االســتئناف يســقط ويكتســب احلكــم القطعيــة وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                      ‫حــرر يف ‪1434/08/07‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/11/23‬ه ـ‬\n‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف برقــم‬\n‫‪ 341192381‬يف ‪1434/11/18‬ه ـ مرفقــا بهــا القــرار رقــم ‪34351258‬‬\n‫يف ‪1434/11/5‬ه ـ ونــص احلاجــة منــه (وبدراســة احلكــم وصورة ضبطه‬\n‫تقــرر املوافقــة علــى احلكــم والغائــب علــى حجتــه متــى حضــر واهلل‬\n\n\n                                                                                         ‫‪322‬‬\n\f      ‫املوفــق قاضــي اســتئناف توقيعــه وختمــه قاضــي اســتئناف توقيعه وختمه‬\n      ‫رئيــس الدائــرة توقيعــه وختمــه ) لــذا جــرى حتريــره حتــى ال يخفــى وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                ‫يف ‪1434/11/23‬ه ـ‬\n      ‫احلمد هلل وحده ‪ ،‬والصالة والســام على رســول اهلل وبعد ‪ :‬ـ فقد جرى‬\n      ‫م ّنــا نحــن قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــا ُع علــى هــذا احلكــم‬\n      ‫الصــادر مــن فضيلــة الشــيخ‪ ...........‬القاضــي يف احملكمــة العامــة مبكة‬\n      ‫املكرمــة املســجل بعــدد ‪ 34301207‬وتاريــخ ‪1434/8/21‬ه ـ املتضمــن‬\n      ‫دعــوى‪ ...........‬ضــد احملكــوم في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة‬\n      ‫احلكــم وص ــورة ضبط ــه تقــرر املوافقــة علــى احلكــم و الغائــب علــى‬\n      ‫حجتــه متــى حضــر ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصل ــى اهلل عل ــى نبينــا محمــد‬\n                                                          ‫وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪323‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":319,"source_page_end":323,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ab7e0bc8cd315e9cba9c8ad43275cb42295198fa18b9b7a35d46b1ff3a5fae74","normalized_text_hash":"c49ba1ad92e5ddd390312c4816f85292ded3b09f4a3cb8fc5ef9855f9bd941ae","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p319-34301207"},{"id":"a2207105-7583-5828-b18b-ad070f4f9f33","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار لتغير املالك -أسبقية شراء عقار -قرر املدعى عليه عدم وجود بينه -طلب إدخال من يصح اختصامه «بائع العقار» -عدم قبول مين املتداخل -احلكم بإخاء العقار قوله صلى اهلل عليه وسلم « البينة على املدعى واليمن على من","document_number":"34304769","case_number":"33599008","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/24","year":"1434","subject":"إجارة -إخاء عقار لتغير املالك -أسبقية شراء عقار -قرر املدعى عليه عدم وجود بينه -طلب إدخال من يصح اختصامه «بائع العقار» -عدم قبول مين املتداخل -احلكم بإخاء العقار قوله صلى اهلل عليه وسلم « البينة على املدعى واليمن على من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/24 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34304769 :‬‬\n                    ‫َر ْق ُم الدعوى‪33599008 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34373352‬تاريخه‪1434/11/27 :‬هـ‬\n\n\n‫إجــارة ‪ -‬إخــاء عقــار لتغيــر املالــك ‪ -‬أســبقية شــراء عقــار ‪ -‬قــرر املدعى‬\n‫عليــه عــدم وجــود بينــه ‪ -‬طلــب إدخــال مــن يصــح اختصامــه «بائــع‬\n         ‫العقــار» ‪ -‬عــدم قبــول ميــن املتداخــل ‪ -‬احلكــم بإخــاء العقــار‬\n\n\n\n\n‫قولــه صلــى اهلل عليــه وســلم « البينــة علــى املدعــى واليمــن علــى مــن‬\n                                                                      ‫انكــر»‬\n\n\n\n\n‫دعــوى املدعــى ضــد املدعــى عليــه ومضمــون الدعــوى انــه اشــتري بيتــا‬\n‫شــعبي ًا مت وصفــه مــن مالكــه الســابق واملدعــى عليــة مســتأجر لهــذا‬\n‫البيــت مــن مالكــه الســابق وانــه طلــب مــن املدعــى عليــة إخــاء العقــار‬\n‫فرفــض وطلــب املدعــى إلــزام املدعــى عليــه بإخــاء العقــار فــور ًا ‪ ،‬أجــاب‬\n‫املدعــى عليــه باملصادقــة علــى الدعــوى ودفــع بأنــه اشــتري املنــزل محــل‬\n‫النــزاع مــن مالكــه الســابق قبــل شــراء املدعــى لــه‪ ،‬طلــب املدعــى عليــة‬\n‫إدخــال املالــك الســابق ‪ ،‬طلــب ناظــر القضيــة مــن املدعــى عليــه البينــة‬\n‫علــى أســبقية الشــراء ‪ ،‬حضــر املالــك الســابق وجــري إفهــام املدعى عليه‬\n‫بــأن لــه ميــن املالــك الســابق فرفــض‪ ،‬اســتعد املتداخــل بــأداء اليمــن‪،‬‬\n‫ثبــت لــدى ناظــر القضيــة صحــة الدعــوى وحكــم علــى املدعــى عليــه‬\n                                                                                    ‫‪324‬‬\n\f      ‫إخــاء العقــار ‪ ،‬وافهمــه بــأن لــه ميــن املتداخــل متــى أراد ‪ ،‬قــرر املدعــى‬\n      ‫عليــه عــدم القناعــة ‪ ،‬صــدر قــرار محكمــة االســتئناف مبنطقــة تبــوك‬\n                                                           ‫باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بتبــوك‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بتبــوك برقــم ‪ 33599008‬وتاريــخ ‪ 1433/10/14‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 331797051‬وتاريــخ ‪ 1433/10/14‬ه ـ ففــي يــوم الســبت‬\n      ‫املوافق‪1433/12/25‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا‬\n      ‫حضــر ‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪،..........‬‬\n      ‫وادعــى علــى احلاضــر معــه ‪........... ،‬ســوري اجلنســية مبوجــب رخصــة‬\n      ‫ـتأجر‬\n      ‫إن هــذا احلاضــر معــي مسـ ٌ‬      ‫ا يف دعــواه ‪َّ :‬‬ ‫اإلقامــة رقــم‪ ، ...........‬قائـ ً‬\n      ‫للبيــت الشــعبي الواقــع يف حــي الفيصليــة بتبــوك مــن مالكــه الســابق ‪،‬‬\n      ‫وسـ ِّـجلَ صكــه رقــم‬  ‫ـتريت أنــا هــذا العقــار يف شــهر ربيــع األول ‪ُ ،‬‬\n                                                                                ‫ثــم اشـ ُ‬\n      ‫‪ 3/72‬يف ‪1433/7/21‬ه ـ الصــادر مــن كتابــة العــدل األولــى بتبــوك‬\n      ‫باســمي بتاريــخ ‪1433/9/9‬ه ـ وطلبـ ُـت مــن املدعــى عليــه أن ُيخلــي العقار‬\n      ‫فرفــض ؛ لــذا أطلــب إلزامــه باإلخــاء فــور ًا ‪ ،‬هــذه دعــواي ‪ .‬وبعرضهــا‬\n      ‫ـتأجر‬\n       ‫ا ‪ :‬مــا ذكــره املدعــي مــن أ َّننــي مسـ ٌ‬  ‫علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫لهــذا البيــت مــن مالكــه الســابق فهــذا صحيــح ‪ ،‬واحلاصــل أ ِّنــي طلبـ ُـت‬\n      ‫مــن املالــك الســابق أن يبيعنــي هــذا البيــت محــل النــزاع فوعدنــي بذلــك‪،‬‬\n      ‫ـرت ‪ ،‬وعندمــا علمـ ُـت أ ّنــه عــرض‬ ‫ا فانتظـ ُ‬  ‫ولكــن قــال لــي انتظــر قلي ـ ً‬\n      ‫ـرت عنــده فطلبـ ُـت منــه أن يبيعنــي إيــاه فوعدنــي بذلــك‬ ‫البيــت للبيــع حضـ ُ‬\n‫‪325‬‬\n\f‫وقــال اصبــر‪ ،‬ثــم بعدهــا بفتــرة علمـ ُـت أ ّنــه باعــه فكلمـ ُـت وطلبـ ُـت منــه‬\n‫ـأن‬\n  ‫أن يبيعنــي هــذا البيــت فاســتعد بذلــك ‪ ،‬ثــم بعدهــا بفتــرة تفاجــأت بـ َّ‬\n‫املدعــي قــد اشــتراه وســجل صكــه باســمه وأنــا أولــى مــن املدعــي بهــذا‬\n‫البيــت ألنــي مســتأجر قــدمي وقمـ ُـت بإصالحــات كثيــرة يف هــذا البيــت‬\n‫ـلمت للمكتــب‬        ‫وأفهمـ ُـت املالكــن الســابقني باالســتعداد للشــراء وسـ ُ‬\n‫قيمــة البيــت وطلبــوا م ِّنــي أن أحضــر عندهــم مــن الغــد مــن أجــل كتابــة‬\n‫العقــد ؛ علمــا أنــي أريــد شــراء البيــت وتســجيله باســم ابنتــي التــي حتمــل‬\n‫اجلنســية الســعودية لــذا لــن ُأخلــي هــذا البيــت ‪ .‬هكــذا قــرر‪ .‬وبعــرض‬\n‫ـرت ‪ ،‬واملدعــى عليــه َي ِعـ ُـد‬  ‫ذلــك علــى املدعــي قــال ‪ :‬الصحيــح مــا ذكـ ُ‬\n‫ـألت‬‫املالــك بالشــراء لكــن لــم يحصــل بينهمــا بيــع ‪ ،‬هــذه إجابتــي ‪ .‬فسـ ُ‬\n‫املدعــى عليــه هــل حصــل بينــك وبــن املالــك بيــع ؟ فقــال ‪ :‬نعــم حصــل‬\n‫بينــي وبينــه بيــع واتفقنــا شــفوي ًا مببلــغ قــدره مائتــان وثالثــون ألــف ريــال‬\n‫البينــة علــى ذلــك فوعــد بهــا ‪ .‬ويف جلسـ ٍة أخــرى‬     ‫‪ .‬هكــذا قــرر‪ .‬فســأل ُته َّ‬\n‫البينــة التــي وعــد بهــا ؟ قــال‬  ‫حضــر الطرفــان ‪ ،‬وبســؤال املدعــى عليــه ِّ‬\n‫ـدي ِّبينــة ‪ ،‬وأنــا طلبـ ُـت املالــك الســابق للحضــور هــذه اجللســة‬    ‫‪ :‬ليــس لـ َّ‬\n‫أن وعدنــي‬      ‫فرفــض ‪ ،‬وأطلـ ُـب حضــوره وإن أنكــر فأطلـ ُـب ميينــه ‪ ،‬علمـ ًا َّ‬\n‫ببيــع هــذا البيــت لــي لكــن باعــه‪ .‬هكــذا قــرر ‪ .‬ويف جلســة أخــرى حضر‬\n‫البينــة التــي وعــد بهــا قــال ‪ :‬إن‬     ‫الطرفــان ‪ ،‬وبســؤال املدعــى عليــه عــن ِّ‬\n‫بينتــي هــو إن حضــر صاحــب البيــت وأنكــر فيحلــف وإن حلــف ‪ ،‬فلــن‬\n‫أخــرج ‪ ،‬ألنــي صــادق يف كالمــي ‪ ،‬وأنــا لــم أبحــث عــن ألنــي اكتفيــت‬\n‫بطلــب احملكمــة لــه وليــس بينــي وبينــه أي تواصل و ُأقــدم لكم مذكر ًة‬\n‫ـدت‬  ‫فيهــا إضافــة إلجابتــي الســابقة ‪ .‬هكــذا قــرر‪ .‬وباإلطــاع عليهــا وجـ ُ‬\n‫أن بعضهــا قــد ذكــره يف إجابتــه ســابق ًا والبعــض اآلخــر ليــس لــه عالقــة‬       ‫َّ‬\n\n                                                                                            ‫‪326‬‬\n\f      ‫ـاء علــى املــادة‬\n                      ‫بهــذا القضيــة ؛ وعليــه ُرفعــت اجللســة إلدخــال البائــع بنـ ً‬\n      ‫(‪ )76‬مــن نظــام املرافعــات ‪ .‬ويف جلســة أخــرى حضــر الطرفــان ‪ ،‬وللعلــم‬\n      ‫فإننــا لــم نتمكــن مــن فتــح اجللســة يف موعدهــا احملــدد ســلف ًا لكونــي‬\n      ‫يف إجــازة اضطراريــة ‪ .‬وحضــر يف هــذه اجللســة مــن بــاع علــى املدعــي‬\n      ‫وأشــار املدعــى عليــه أنــه حصــل تفــاوض بينهمــا علــى البيــع وهــو ســعودي‬\n      ‫ـدت هــذا‬‫بالهويــة الوطنيــة رقــم ‪ ،...‬وبســؤاله عمــا لديــه ؟ قــال‪ :‬إنــي وجـ ُ‬\n      ‫البيــت محــل النــزاع معروضـ ًا للبيــع يف أحــد املكاتب العقارية فاشــتري ُته‬\n      ‫مــن مالكــه وأخبرنــي أن الــذي يســكن يف هــذا البيــت لــه رغبــة بــه‬\n      ‫ـتريت هــذا البيــت منــه‬\n                             ‫وهــو املدعــى عليــه فقلـ ُـت خيــر إن شــاء اهلل فاشـ ُ‬\n      ‫بأربعمائــة ألــف ريــال ثــم بعدهــا ذهبـ ُـت بنفســي للمدعــى عليــه يف هــذا‬\n      ‫البيــت وعرضـ ُـت عليــه البيــت وكان هــذا البيــت مقــام علــى أرض قــد‬\n      ‫قســمت إلــى جزئــن جــزء أقيــم عليــه هــذا البيــت محــل النــزاع واجلــزء‬\n      ‫اآلخــر أقيــم عليــه بيــت آخــر ‪ ،‬واحلاصــل أنــي عرضـ ُـت علــى املدعــى عليــه‬\n      ‫هــذا البيــت محــل النــزاع وقلــت لــه إن رأس مالــي فيــه مائتــي ألــف ريــال‬\n      ‫فبكــم تريــد أن تشــتريه فقــال إنــه ال يســاوي هــذه القيمــة ووضــح لــي أنه‬\n      ‫ليــس لــه رغبــة يف شــرائه ثــم عرض ُتــه يف مكتــب العقــاري وبعدها حضر‬\n      ‫فذهبت‬\n       ‫ُ‬         ‫املدعــي ورغــب يف شــراء البيــت مببلــغ مائتــن وأربعــن ألف ريــال‬\n      ‫ـتر مبائتــن وأربعــن ألــف‬   ‫للمدعــى عليــه وأخبرتــه بأنــه تقــدم للبيــت مشـ ٍ‬\n      ‫ريــال فقــال إن هــذا البيــت ال يســاوي هــذه القيمــة وأعــرض عنــه فطلبـ ُـت‬\n      ‫ـرت أنــا‬\n             ‫منــه أن يســمح للمشــتري مبعاينــة البيــت فوافــق علــى ذلــك وحضـ ُ‬\n      ‫واملدعــي ودخلنــا عنــده يف هــذا البيــت وقــام املدعــى عليــه بإطالعنــا علــى‬\n      ‫بعــض أجــزاء البيــت وتفاصيلــه ثــم بعدهــا كتبـ ُـت عقــد ًا مــع املدعــي يف‬\n      ‫مكتــب ‪ ...‬وشــهدنا علــى ذلــك وكان ذلــك بعــد املغــرب وال أذكــر أي‬\n\n\n‫‪327‬‬\n\f‫ـتلمت مــن املدعــي العربــون وقــدره‬ ‫يــوم وال التاريــخ ثــم بعــد العشــاء اسـ ُ‬\n‫ثمانــون ألــف ريــال تقريب ـ ًا ثــم بعدهــا بيــوم أو يومــن اتصــل بــي موظــف‬\n‫يف مكتــب وكنـ ُـت قــد عرضــت البيــت قبــل البيــع عنــد عــدة مكاتــب‬\n‫وقــال لــي املوظــف بــأن املدعــى عليــه يرغــب يف شــراء البيــت فقلــت إنــي‬\n‫وقعــت عقــد ًا مــع املدعــي وإذا اســتجد أمــر اتصلــت بكــم ثــم أكمــل‬\n‫لــي املدعــي بقيــة املبلــغ وأنهيــت إجــراءات فــرز الصــك باجلزأيــن اللذيــن‬\n‫ذكرتهمــا لــدى كتابــة العــدل ثــم أفرغـ ُـت للمدعــي يف ‪1433/9/9‬ه ـ‬\n‫علم ـ ًا أنــي عندمــا كنـ ُـت أشــاهد البيــت ومعــي املدعــي واملدعــى عليــه‬\n‫كان املدعــى عليــه يبــارك للمدعــي البيــع هــذا مــا لــدي مــن إفــادة ‪.‬‬\n‫ا ‪ :‬مــا ذكــره يف إفادتــه بعضــه‬   ‫وبعرضهــا علــى املدعــى عليــه أجــاب قائـ ً‬\n‫صحيــح وبعضــه غيــر صحيــح والصــواب أن عندمــا أخبرنــي أنــه اشــترى‬\n‫هــذا البيــت والــذي بجــواره مــن مالكــه بأربعمائــة ألــف ريــال تفاوضـ ُـت‬\n‫معــه علــى أن أشــتري هــذا البيــت محــل النــزاع مبائتــن وســبعة وعشــرين‬\n‫ألــف ريــال فوافــق علــى ذلــك ثــم يف صبــاح الغد وكان ذلك يف شــهر ربيع‬\n‫ـرت معــي كامــل املبلــغ ثــم حضــر عنــدي‬    ‫األول مــن عــام ‪1433‬ه ـ أحضـ ُ‬\n‫واملدعــي وملــا ســألته عــن ســبب مجــيء املدعــي معــه قــال إن هــذا يريــد‬\n‫شــراء البيــت فقلــت لــه ألــم نتفــق باألمــس علــى مائتــن وســبعة وعشــرين‬\n‫ألــف ريــال وأنــا مســتعد بتســليمها لــك اآلن فقــال لــي انظــر يف املوضــوع‬\n‫وطلــب مهلــة للتفكيــر فذهبــا ولــم يحصــل أنــي أطلعتهــم علــى املنــزل أو‬\n‫أدخلتهــم فيــه ثــم علمــت فيمــا بعــد أنهمــا تبايعــا علــى هــذا املبلــغ الــذي‬\n‫اشــترى بــه املدعــي ‪ ،‬هــذه إجابتــي‪ .‬وبعرضهــا علــى قــال ‪ :‬الصحيــح مــا‬\n‫ـرت ولــم يحصــل أن اتفقــت مــع املدعــى عليــه علــى أي شــيء يتعلــق‬      ‫ذكـ ُ‬\n‫بالبيــع أو الشــراء بــل إنــي ملــا أخبرتــه بأنــه ِســيم منــي مبائتــن وأربعــن‬\n\n\n                                                                                        ‫‪328‬‬\n\f      ‫ألــف ريــال زهدنــي يف البيــت وقــال إنــه ال يســاوي أي شــيء وأوضــح لــي‬\n      ‫رغبتــه بعــدم الشــراء هــذه إجابتــي ‪ .‬فســألت املدعــى عليــه البينــة علــى‬\n      ‫مــا ذكــر فقــال ‪ :‬ليــس لــدي بينــة ولــم يكــن معنــا أحــد‪ .‬هكــذا قــرر‪.‬‬\n      ‫ـتعد بــأداء اليمــن علــى نفــي مــا ذكــره املدعــى‬    ‫فســألت املتداخــل أمسـ ٌ‬\n      ‫عليــه ؟ فقــال‪ :‬نعــم ‪ ،‬فعرضتهــا علــى املدعــى عليــه فقــال ‪ :‬ال أقبــل‬\n      ‫ـرت عــن ســريان مفعــول‬    ‫بيمينــه ‪ .‬هكــذا قــرر‪ .‬وقــد ســبق ألن استفسـ ُ‬\n      ‫صــك العقــار محــل النــزاع والــذي يحمل الرقــم ‪ 3/72‬يف ‪1433/7/21‬هـ‬\n      ‫بالنمــوذج املعــد لذلــك برقــم ‪ 34790713‬يف ‪1434/4/1‬ه ـ فوردنــي مــن‬\n      ‫فضيلــة رئيــس كتابــة العــدل اجلــواب بــذات الرقــم يف ‪1433/4/17‬ه ـ‬\n      ‫واملتضمــن أن الصــك ســاري املفعــول وليــس علــى ســجله أي شــروحات‬\n      ‫تخــل بصالحيتــه ومســجل باســم ؛ فســألت املدعــي عــن العقــد فقــال‬\n      ‫ليــس معــي اآلن وبنــاء علــى التعاقــد الــذي بينــي وبــن املدعــى عليــه نقــل‬\n      ‫ـاء علــى‬\n              ‫العقــار باســمي هكــذا قــرر ‪ ،‬ومســتعد بإرفاقــه باملعاملــة‪ .‬فبنـ ً‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وملــا جــاء يف إفــادة املتداخــل وألن املدعــى‬\n      ‫عليــه قــرر يف إجابتــه ادعائــه بأنــه اشــترى هــذا البيــت محــل النــزاع مــن‬\n      ‫مالكــه قبــل أن يبيعــه علــى املدعــي مببلــغ مائتــن وســبعة وعشــرين ألــف‬\n      ‫ريــال وأنكــر ذلــك املتداخــل (‪ ).....‬وقــرر املدعــى عليــه عــدم البينــة التــي‬\n      ‫تثبــت صحــة مــا ادعــاه ورفــض ميــن املتداخــل بعــد أن اســتعد بهــا ولقولــه‬\n      ‫عليــه الصــاة والســام ‪ (:‬البينــة علــى املدعــي واليمــن علــى مــن أنكــر)‬\n      ‫حســنه البيهقــي فقــد ثبــت لــدي صحــة دعــوى املدعــي وحكمـ ُـت علــى‬\n      ‫املدعــى عليــه بــأن يخلــي العقــار محــل النــزاع حــا ًال وأفهمتــه بــأن لــه ميــن‬\n      ‫املتداخــل متــى طلبهــا وبعرضــه عليــه لــم يقنــع بــه وطلــب بعــث احلكــم‬\n      ‫إلــى محكمــة االســتئناف لتدقيقــه ووعــد بتقــدمي الئحــة اعتراضيــة‬\n\n\n‫‪329‬‬\n\f‫و ُأفهــم باملراجعــة يف يــوم األربعــاء ‪1434/8/24‬ه ـ ال ســتالم صــورة مــن‬\n‫صــك احلكــم و ُأفهــم بــأن لــه ثالثــن يوم ـ ًا لــه أن يقــدم اعتراضــه علــى‬\n‫وختمــت‬  ‫احلكــم خاللهــا ويبــدأ حســابها مــن التاريــخ املشــار إليــه آنف ـ ًا ُ‬\n‫هــذه اجللســة الســاعة العاشــرة والنصــف ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ،‬ففــي يــوم اخلميــس املوافــق‪ 1435/01/04‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثامنــة ‪ ،‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف بتبــوك ‪ ،‬بخطــاب فضيلــة رئيســها رقــم ‪ 331797051‬يف‬\n‫‪1434/12/16‬ه ـ وبرفقــه القــرار رقــم ‪ 34373352‬يف ‪1434/11/27‬هـ‬\n‫‪ ،‬املتضمــن املصادقــة علــى احلكــم مــع التنبيــه إلــى إفهــام املدعــى عليــه‬\n‫ـأن لــه حــق إقامــة الدعــوى يف املطالبــة بقيمــة إصــاح البيــت إنْ رغِ ـ َـب‬‫بـ ّ‬\n‫يف ذلــك ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1435/01/04‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل أمــا بعــد‪ :‬فقــد اطلعن ــا‬\n‫نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف محكمــة االســتئناف مبنطقــة‬\n‫تبــوك علــى املعاملــة الــواردة مــن احملكمــة العامــة بتبــوك برقــم‬\n‫‪ 331797051‬وتاريــخ ‪1434/9/23‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة الشــيخ وفقــه اهلل برقــم ‪ 34304769‬وتاريــخ ‪1434/8/24‬ه ـ‬\n‫اخلــاص بدعوى‪...........‬ضــد‪ ...........‬وبدراســة الصــك وصــورة ضبطــه‬\n‫واملذكــرة االعتراضيــة املقدمــة مــن املدعــى عليــه وأوراق املعاملــة جــرت‬\n‫املصادقــة علــى احلكــم مــع التنبيــه إلــى إفهــام املدعــي عليــه بــأن لــه‬\n‫حــق إقامــة الدعــوى يف املطالبــة بقيمــة إصــاح البيــت إن رغــب يف ذلــك‬\n   ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                        ‫‪330‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":324,"source_page_end":330,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"032274dcc282bd61436277a050c29fff55340e1734079c000a8506e455fbd4da","normalized_text_hash":"1fcf04b1f0e967a00246f3219eb399754351df7fb473242a7936569c5bb68634","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p324-34304769"},{"id":"ed6b662c-54da-5723-83a1-fadf0c9e9f46","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -فسخ عقد اإليجار للغياب وعدم سداد األجرة - البينة عقد اإليجار و املغادرة النهائية -احلكم بفسخ عقد اإليجار وفتح العن -حفظ محتويات العن يف بيت املال -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال .","document_number":"34340276","case_number":"34371709","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/26","year":"1434","subject":"عقد -إجارة -فسخ عقد اإليجار للغياب وعدم سداد األجرة - البينة عقد اإليجار و املغادرة النهائية -احلكم بفسخ عقد اإليجار وفتح العن -حفظ محتويات العن يف بيت املال -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/10/26 :‬هـ‬\n                  ‫ُ‬                 ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪34340276 :‬‬\n                     ‫َر ْق ُم الدعوى‪34371709 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34360441‬تاريخه‪1434/11/13:‬هـ‬\n\n\n  ‫عقــد ‪ -‬إجــارة ‪ -‬فســخ عقــد اإليجــار للغيــاب وعــدم ســداد األجــرة ‪-‬‬\n  ‫البينــة عقــد اإليجــار و املغــادرة النهائيــة ‪ -‬احلكــم بفســخ عقــد اإليجــار‬\n  ‫وفتــح العــن ‪ -‬حفــظ محتويــات العــن يف بيــت املــال ‪ -‬بيــع مــا يخشــى‬\n                                            ‫تلفــه وإيــداع ثمنــه يف بيــت املــال ‪.‬‬\n\n\n\n\n             ‫‪ .1‬قاعدة فقهية‪ :‬األصل يف األمور احلادثة (العارضة) العدم‪.‬‬\n                               ‫‪ .2‬املادة ‪ 138‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه األجنبــي الغائــب عــن مجلــس‬\n  ‫احلكــم بأنــه اســتأجر مــن موكلتــه الشــقة رقــم ‪ ...‬مــن عمارتهــا‬\n  ‫الواقعــة بحــي ‪ ...‬بأجــرة ســنوية قدرهــا عشــرون ألــف ريــال علــى دفعتــن‬\n  ‫اعتبــارا مــن ‪1433/3/1‬ه ـ وقــد ســافر خــارج اململكــة خروجــا نهائيــا‬\n  ‫يف ‪1433/8/29‬ه ـ ولــم يســدد أي شــيء مــن اإليجــارات املســتحقة منــذ‬\n  ‫ســفره بعــد ذلــك بقيــت الشــقة مغلقــة ويطلــب احلكــم بفســخ عقــد إيجــار‬\n  ‫الشــقة وتســليمها ملوكلتــه مــع احتفــاظ موكلتــه باملطالبــة بأجــرة‬\n  ‫الشــقة حتــى تاريــخ فســخها هكــذا ادعــى ‪ ،‬املدعــى عليــه أجنبــي غــادر‬\n  ‫اململكــة مغــادرة نهائيــة وذلــك حســب إفــادة مركــز الشــرطة فجــرى‬\n\n                                                                                        ‫‪344‬‬\n\f      ‫ســماع الدعــوى غيابي ـ ًا ‪ ،‬بينــة املدعــي صــك العقــار وعقــد اإليجــار‬\n      ‫وخطــاب مديــر مركــز الشــرطة املرفــق باملعاملــة املتضمــن أن املســتأجر‬\n      ‫خــارج اململكــة مبوجــب البرنــت املرفــق ‪ ،‬فبنــاء علــى املــادة ‪ 138‬مــن‬\n      ‫نظــام املرافعــات الشــرعية وحيــث ثبــت مغــادرة املدعــى عليــه اململكــة‬\n      ‫مغــادرة نهائيــة مبوجــب خطــاب الشــرطة وبرنــت وزارة الداخليــة وحيــث‬\n      ‫إن األصــل يف األمــور احلادثــة العــدم وبالتالــي عــدم ســداد األجــرة وألن‬\n      ‫ممــا يســوغ فيــه فســخ عقــد اإليجــار عــدم ســداد املســتأجر لألجــرة‪،‬‬\n      ‫ملــا تقــدم صــدر احلكــم بفســخ عقــد اإليجــار بــن الطرفــن وفتــح‬\n      ‫الشــقة املذكــورة مــن قبــل اجلهــات املختصــة وحفــظ مــا ميكــن حفظــه‬\n      ‫وبيــع مــا يخشــى عليــه التلــف وإيــداع ثمنــه ببيــت املــال لصالــح املدعــى‬\n      ‫عليــه وتســلم لصاحبتهــا‪ ،‬قنــع املدعــي وكالــة باحلكــم ورفــع احلكــم‬\n      ‫حملكمــة االســتئناف لتدقيقــه ‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n                                        ‫الثالثــة مبحكمــة االســتئناف بالريــاض‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 34371709‬وتاريــخ ‪ 1434/08/08‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341850308‬وتاريــخ ‪ 1434/08/01‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/10/21‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n      ‫ال عن‬‫وفيهــا حضــر ‪.......‬ســعودي بالســجل املدنــي رقــم ‪.......‬بصفتــه وكي ً‬\n      ‫‪ .......‬ســعودية بالســجل املدنــي رقــم ‪.......‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم ‪ 20623‬يف ‪1431/3/8‬ه ـ‬\n‫‪345‬‬\n\f‫جلــد ‪ 3719‬وكالــة تخولــه باملطالبــة واملداعــاة واملخاصمــة وســماع‬\n‫الدعــاوي والــرد عليهــا وقبــول احلكــم واالعتــراض عليــه وادعــى بقولــه‬\n‫أدعــي ضــد الغائــب ‪.......‬اجلنســية مبوجــب االقامــة رقــم ‪.......‬حيــث‬\n‫اســتأجر مــن موكلتــي الشــقة رقــم ‪ ...‬مــن عمارتهــا الواقعــة بحــي ‪...‬‬\n‫اململوكــة لهــا مبوجــب الصــك الصــادر مــن كتابــة العــدل األولــى‬\n‫برقــم ‪310107016656‬بتاريــخ ‪1431/5/19‬ه ـ وذلــك بأجــرة ســنوية‬\n‫قدرهــا عشــرين ألــف ريــال علــى دفعتــن اعتبــارا مــن ‪1433/3/1‬ه ـ‬\n‫وقــد ســافر خــارج اململكــة خروجــا نهائيــا يف ‪1433/8/29‬ه ـ ولــم‬\n‫يســدد أي شــيء مــن اإليجــارات املســتحقة منــذ ســفره بعــد ذلــك بقيــت‬\n‫الشــقة مغلقــة لــذا نطلــب احلكــم بفســخ عقــد إيجــار الشــقة املذكــورة‬\n‫بعاليــه وتســليمها ملوكلتــي مــع احتفــاظ موكلتــي باملطالبــة باجــرة‬\n‫الشــقة حتــى تاريــخ فســخها هــذه دعــواي ثــم أبــرز صــك العقــار وعقــد‬\n‫إيجــار الشــقة فوجدتهمــا كمــا ذكــر وقــال املدعــي بيناتــي يف املعاملــة‬\n‫فوجــدت خطــاب مديــر شــرطة مركــز العريجــا املوجــه لهــذه احملكمــة‬\n‫برقــم ‪ 4/6/9205/19‬يف ‪1434/7/26‬ه ـ وقــد جــاء فيــه أن املســتأجر‬\n‫خــارج اململكــة مبوجــب البرنــت املرفــق ووجــدت البرنــت كمــا ذكــروا‬\n‫وذكــر املدعــي لذلــك كلــه وبنــاء علــى املــادة ‪ 138‬مــن نظــام املرافعــات‬\n‫الشــرعية املثبــت ملغــادرة املدعــى عليــه اململكــة مغــادرة نهائيــة مبوجــب‬\n‫خطــاب الشــرطة وبرنــت وزارة الداخليــة وحيــث األصــل يف األمــور‬\n‫احلادثــة العــدم وبالتالــي عــدم ســداد االجــرة وألن ممــا يســوغ فيــه فســخ‬\n‫عقــد اإليجــاره عنــد عــدم ســداد املســتأجر لألجــرة لذلــك كلــه فقــد‬\n‫حكمــت بفســخ عقــد اإليجــارة بــن الطرفــن وفتــح الشــقة املذكــورة‬\n‫مــن قبــل اجلهــات املختصــة وحفــظ مــا يكــون فيهــا مــن أثــاث معتــاد أن‬\n\n\n                                                                                   ‫‪346‬‬\n\f      ‫يكــون للمســتأجر يف بيــت مــال احملكمــة لصالــح املدعــى عليــه ومــا‬\n      ‫يخشــى عليــه مــن التلــف يبــاع ثــم حتفــظ قيمتــه لصالــح املدعــى عليــه‬\n      ‫وتســلم الشــقة لصاحبتهــا وبعرضــه علــى املدعــي وكالــة قنــع بــه وأمــرت‬\n      ‫برفــع ذلــك حملكمــة االســتئناف لتدقيقــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/10/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n      ‫لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n      ‫باخلطــاب رقــم ‪ 341850308‬وتاريــخ ‪1434/10/28‬ه املرفــق بهــا‬\n      ‫الصــك رقــم ‪ 34340276‬وتاريــخ ‪1434/10/26‬ه ـ الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة الشــيخ ‪ .......‬املتضمــن احلكــم يف الدعــوى املقامــة‬\n      ‫مــن ‪ .......‬ضــد ‪ ...........‬الغائــب عــن مجلــس احلكــم ‪.......‬أمريكــي‬\n      ‫اجلنســية علــى النحــو املوضــح بالصــك واملتضمــن حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل بــه وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫تقــرر الدائــرة املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                               ‫نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪347‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":344,"source_page_end":347,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bc93a1d40015659dcc7b6983ae4ce81d79afd233748f0cdfdd91d478237b0680","normalized_text_hash":"c3c4c12c7121646a966778f81566697477a36bde67e3e3cfac872693118baf1f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p344-34340276"},{"id":"739f458f-f531-5a4b-ae21-daa46f0fa7d7","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -قيمة باقي أجرة لعن وباقي أجرة لوحدة يف تلك العن -الدفع باالتفاق على حسم األجرة مقابل إصاح العيوب - حلف اليمن مبوافقة املدعى على احلسم للمبلغ مقابل إصاح العيوب -لم يقم املدعى عليه البينة -إلزام املدعى عليه بدفع باقي األجرة احملسومة لعدم ثبوت االتفاق -وصرف النظر عن باقي أجرة الوحدة يف تلك العن .","document_number":"33480606","case_number":"64520215","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/28","year":"1434","subject":"عقد -إجارة -قيمة باقي أجرة لعن وباقي أجرة لوحدة يف تلك العن -الدفع باالتفاق على حسم األجرة مقابل إصاح العيوب - حلف اليمن مبوافقة املدعى على احلسم للمبلغ مقابل إصاح العيوب -لم يقم املدعى عليه البينة -إلزام املدعى عليه بدفع باقي األجرة احملسومة لعدم ثبوت االتفاق -وصرف النظر عن باقي أجرة الوحدة يف تلك العن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/28 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33480606:‬‬\n                    ‫َر ْق ُم الدعوى‪64520215 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 3452991‬تاريخه‪1434/3/2 :‬هـ‬\n\n\n ‫عقــد ‪ -‬إجــارة ‪ -‬قيمــة باقــي أجــرة لعــن وباقــي أجــرة لوحــدة يف تلــك‬\n ‫العــن ‪ -‬الدفــع باالتفــاق علــى حســم األجــرة مقابــل إصــاح العيــوب ‪-‬‬\n ‫حلــف اليمــن مبوافقــة املدعــى علــى احلســم للمبلــغ مقابــل إصــاح‬\n ‫العيــوب ‪ -‬لــم يقــم املدعــى عليــه البينــة ‪ -‬إلــزام املدعــى عليــه بدفــع‬\n ‫باقــي األجــرة احملســومة لعــدم ثبــوت االتفــاق‪ -‬وصــرف النظــر عــن‬\n                                      ‫باقــي أجــرة الوحــدة يف تلــك العــن ‪.‬‬\n\n\n\n\n ‫‪ .1‬قــول ابــن قنــدس يف حاشــيته علــى الفــروع‪« :‬فــإن اختلفــا يف قــدر‬\n ‫مــا أنفــق فالقــول قــول املكــري ألنــه منكــر فــإن لــم يشــرط لكنــه أذن لــه‬\n ‫يف اإلنفــاق ليحتســب لــه يف األجــرة ففعــل ثــم اختلفــا فالقــول قــول‬\n ‫املكــري وإن أنفــق مــن غيــر إذنــه لــم يرجــع بشــيء ألنــه أنفــق علــى مالــه‬\n ‫بغيــر إذنــه نفقــة غيــر واجبــة علــى املالــك فأشــبه مــا لــو عمــر لــه دارا‬\n                                                                   ‫أخــرى»‪.162/7‬‬\n ‫‪ .2‬قــول ابــن رجــب رحمــه اهلل تعالــى يف قواعــده‪« :‬نقــل جماعــة عــن‬\n ‫أحمــد مــا يــدل علــى أن اإلجــارة الصحيحــة ال جتــب منهــا األجــرة إال‬\n  ‫بقــدر االنتفــاع إذا تــرك املســتأجر بقيــة االنتفــاع بعــذر مــن جهتــه»‪.‬‬\n\n\n\n\n                                                                                       ‫‪348‬‬\n\f      ‫ادعــى املدعــي بأنــه أجــر عمارتــه أربــع ســنوات للمدعــى عليــه بأجــرة‬\n      ‫معلومــة إال أنــه لــم يدفــع منهــا ثالثــن ألــف ريــال مــن مجمــوع األجــرة‬\n      ‫املســتحقة لألربــع الســنوات كمــا قــام بتجديــد اســتئجاره للشــقة التــي‬\n      ‫يســكنها ســنة واحــدة مــن تاريــخ انتهــاء مــدة العقــد األول ولــم يدفــع مــن‬\n      ‫أجرتهــا إال أجــرة شــهر واحــد ‪ ،‬طلــب إلــزام املدعــى عليــه بــأن يدفــع‬\n      ‫باقــي أجــرة العمــارة وباقــي أجــرة الشــقة ‪ ،‬أقــر املدعــى عليــه بعقــد‬\n      ‫األربــع الســنوات وأنــه لــم يدفــع ثالثــن ألــف ريــال مــن إجمالــي األجــرة‬\n      ‫ودفــع بــأن املدعــي تنــازل بهــا لــه مقابــل إصالحــه عيــوب العمــارة وأنكــر‬\n      ‫قيامــه بتجديــد عقــد الشــقة وإمنــا عــرض عليــه ذلــك فاختلفــا يف األجــرة‬\n      ‫فبقــي فيهــا شــهرا ثــم خــرج ‪ ،‬بعرضــه علــى املدعــي متســك بأحــد بنــود‬\n      ‫العقــد بــأن كل مــا يضيفــه ويصلحــه املدعــي مــن إصالحــات تكــون‬\n      ‫علــى املســتأجر ‪ ،‬بطلــب البينــة مــن املدعــى عليــه علــى دفعــه قــرر بــأال‬\n      ‫بينــة لديــه وطلــب ميــن املدعــي فحلــف اليمــن املطلوبــة ‪ ،‬عليــه ولطلــب‬\n      ‫املدعــي إلــزام املدعــى عليــه بدفــع ثالثــن ألف ريال نظيــر املبلغ الذي قام‬\n      ‫بحســمه مــن كامــل أجــرة العمــارة ولطلبــه أيضــا إلزامــه بدفــع الباقــي‬\n      ‫مــن األجــرة الســنوية مــن ‪1432/2/1‬ه ـ حتــى ‪1433/3/1‬ه ـ وقدرهــا‬\n      ‫اثنــان وثالثــون ألــف ريــال و إلقــرار املدعــى عليــه بصحــة حســم املبلــغ‬\n      ‫البالــغ ثالثــن ألــف ريــال أو زيــادة ولدفعــه بــأن حســمه كان إلصالحــه‬\n      ‫عيــوب العمــارة مبوافقــة املدعــي وإلنــكار املدعــي ذلــك ولعجــز املدعــى‬\n      ‫عليــه عــن إقامــة البينــة علــى دفعــه ذلــك وطلبــه ميــن املدعــي ولبذلــه لهــا‬\n      ‫علــى النحــو املرصــود وملــا قــرره أهــل العلــم يف هــذا املســألة قــال ابــن‬\n\n‫‪349‬‬\n\f‫قنــدس يف حاشــيته علــى الفــروع‪ »:‬فــإن اختلفــا يف قــدر مــا أنفــق فالقــول‬\n‫قــول املكــري ألنــه منكــر فــإن لــم يشــرط لكنــه أذن لــه يف اإلنفــاق‬\n‫ليحتســب لــه يف األجــرة ففعــل ثــم اختلفــا فالقــول قــول املكــري وإن‬\n‫أنفــق مــن غيــر إذنــه لــم يرجــع بشــيء ألنــه أنفــق علــى مالــه بغيــر إذنــه‬\n‫نفقــة غيــر واجبــة علــى املالــك فأشــبه مــا لــو عمــر لــه دارا أخــرى» ‪162/7‬‬\n‫‪،‬وألن املدعــى عليــه بقــي يف العــن املؤجــرة شــهرا حتــى ‪1432/2/1‬ه ـ‬\n‫ودفــع للمدعــي قســط تلــك املــدة كمــا قــال وصادقــه املدعــي علــى ذلــك‬\n‫ولعــدم ثبــوت جتديــد العقــد وملــا قالــه ابــن رجــب رحمــه اهلل تعالــى يف‬\n‫قواعــده « نقــل جماعــة عــن أحمــد مــا يــدل علــى أن اإلجــارة الصحيحــة‬\n‫ال جتــب منهــا األجــرة إال بقــدر االنتفــاع إذا تــرك املســتأجر بقيــة االنتفــاع‬\n‫بعــذر مــن جهتــه «عليــه فقــد حكمــت احملكمــة علــى املدعــى عليــه بــأن‬\n‫يدفــع للمدعــي ثالثــن ألــف ريــال وصــرف النظــر عــن طلــب املدعــي‬\n‫احلكــم علــى املدعــى عليــه بإلزامــه بدفــع أجــرة باقــي الســنة للشــقه‪،‬‬\n                                    ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....................‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 64520215‬وتاريــخ‬\n‫‪ 1432/03/12‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3227445‬وتاريــخ‬\n‫‪ 1432/03/12‬ه ـ املتعلقــة بدعــوى ‪ ...................‬ضــد ‪ ...................‬ففــي‬\n‫هــذا اليــوم الســبت ‪1433/2/20‬ه ـ افتتحــت اجللســة الســاعة ‪10.45‬‬\n‫وفيها حضر املدعي ‪...........................‬ســعودي اجلنســية مبوجب الســجل‬\n\n                                                                                        ‫‪350‬‬\n\f      ‫املدنــي رقم………………وحضــر حلضــوره املدعــى عليــه ‪...................‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...................‬ثــم ادعــى‬\n      ‫ا لقــد ســبق وان قمــت بتأجيــر‬         ‫املدعــي يف مواجهــة املدعــى عليــه قائ ـ ً‬\n      ‫هــذا املدعــى عليــه كامــل عمارتــي الســكنية الواقعــة ‪ ...‬واململوكــة‬\n      ‫لــي مبوجــب صــك امللكيــة الصــادر مــن كتابــة العــدل األولــى مبكــة‬\n      ‫املكرمــة برقــم ‪ 6/308/615‬يف ‪1421/7/18‬ه ـ وذلــك ملــدة خمــس‬\n      ‫ســنوات اعتبــار ًا مــن ‪1428/2/1‬ه وتنتهــي يف ‪1433/1/30‬ه ـ بأجــرة‬\n      ‫ســنوية قدرهــا تســعون ألــف ريــال ونظــر ًا الن املدعــى عليــه قــد اخــل‬\n      ‫ببنديــن مــن بنــود عقــد اإليجــار املبــرم معــه وهمــا األول الــذي ينــص‬\n      ‫علــى أن يدفــع األجــرة يف أول كل ســنة هجريــة حيــث لــم يلتــزم بذلــك‬\n      ‫وإمنــا كان مياطــل يف بذلهــا كمــا اخــل بالبنــد الســادس والــذي ينــص‬\n      ‫علــى انــه يف حالــة عــدم قيــام املســتأجر بدفــع األجــرة يف املوعــد احملــدد‬\n      ‫فيحــق للطــرف األول والــذي هــو أنــا املؤجــر تأجيــر العــن علــى الغيــر‬\n      ‫وأنــه يجــب علــى املســتأجر اإلخــاء مــن اجــل ذلــك قمــت بإبــرام اتفــاق‬\n      ‫آخــر معــه وذلــك بتاريــخ ‪1430/8/11‬ه ـ يقضــي بتقليــص مــدة اإليجــار‬\n      ‫لتكــون أربــع ســنوات بــدال مــن خمــس ليكــون إخــاؤه للعمــارة بتاريــخ‬\n      ‫‪1432/2/1‬ه ـ وبنــاء علــى ذلــك فقــد بقــي املدعــى عليــه يف العــن‬\n      ‫املؤجــرة إلــى تاريــخ ‪1432/2/1‬ه ـ ثــم أخالهــا ماعــدا الشــقة التــي كان‬\n      ‫يســكنها كمــا أضيــف إلــى انــه حســم مبلغ ـ ًا قــدره ثالثــون ألــف ريــال‬\n      ‫مــن كامــل األجــرة للســنوات األربــع وذلــك مــن غيــر مــا بــأس ثــم طلــب‬\n      ‫منــي أن أجــدد لــه اإليجــار ملــدة ســنة واحــدة اعتبــارا مــن ‪1432/2/1‬ه ـ‬\n      ‫وحتــى ‪1433/3/1‬ه ـ لشــقتني مــن عمارتــي التــي وصفتهــا إحداهمــا لــه‬\n      ‫واألخــرى لعديلــه املدعــو ‪ ................. /‬وبالفعــل جــددت اإليجــار ملــدة‬\n\n\n‫‪351‬‬\n\f‫ســنه مــن ‪1432/2/1‬ه ـ حتــى ‪1433/3/1‬ه ـ ولكــن باجــرة ســنوية‬\n‫قدرهــا خمســة وثالثــون ألــف ريــال لــكل شــقة ومت االتفــاق علــى ذلــك‬\n‫ولكــن بعــد مضــي شــهر فقــط مــن تاريــخ التجديــد األخيــر والــذي كان‬\n‫قبــل نهايــة العقــد األساســي بشــهر قــام املدعــى عليــه بتســليم قســط‬\n‫شــهر واحــد فقــط مــن أجــرة تلــك الســنة وقــام بإخــاء شــقته متناســيا‬\n‫أن عقــد اإليجــار عقــد ملــزم للطرفــن حيــث لــم يســلمني ســوى مبلــغ‬\n‫ثالثــة أالف ريــال مــن كامــل أجــرة تلــك الســنة لــذا فانــي اطلــب احلكــم‬\n‫علــى املدعــى عليــه مبــا يلــي أوال بدفــع املبلــغ املقــدر بثالثــن ألــف ريــال‬\n‫وذلــك نظيــر املبلــغ الــذي قــام بحســمه مــن كامــل أجــرة العمــارة يف‬\n‫الســنوات اإليجاريــة ثانيــا إلزامــه بدفــع الباقــي مــن األجــرة الســنوية مــن‬\n‫‪1432/2/1‬ه ـ حتــى ‪1433/3/1‬ه ـ وقــدره اثنــان وثالثــون ألــف ريــال ‪.‬‬\n‫هــذه دعــواي واســأله اجلــواب وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n‫قائــا إن مــا ورد يف دعــواه مــن كونــي اســتأجرت منــه عمارتــه التــي‬\n‫وصفهــا يف دعــواه للمــدة التــي ذكرهــا باألجــرة التــي بينهــا فصحيــح وال‬\n‫أنكــره ومــا يتعلــق بتقليــص مــدة اإليجــار مــن خمــس ســنوات إلــى أربــع‬\n‫مبوجــب االتفــاق اإلحلاقــي فصحيــح وال أنكــره حيــث بقيــت يف العمــارة‬\n‫يف الســنة األخيــرة أي الســنة الرابعــة حتــى ‪1432/2/1‬ه ـ ومــا ذكــره يف‬\n‫دعــواه مــن كونــي خصمــت مبلــغ ثالثــن ألــف ريــال مــن إجمالــي أجــرة‬\n‫الســنوات األربــع فصحيــح لكنــه ليــس ثالثــن ألــف ريــال بــل قــد تكــون‬\n‫أكثــر مــن ثالثــن ألــف حيــث قمــت بحســمها والســبب يف ذلــك هــو مــا‬\n‫كانــت تعانيــه تلــك العمــارة مــن عيــوب كثيــرة خاصــة يف الصــرف‬\n‫الصحــي فقمــت بإصــاح ذلــك مبوافقــة املدعــي وحســمت مــا كلفتنــي‬\n‫تلــك اإلصالحــات مبوافقــة املدعــي املســبقة علــى ذلــك ومــا يتعلــق بطلبــه‬\n\n\n                                                                                        ‫‪352‬‬\n\f      ‫باقــي أجــرة الشــقة التــي ذكــر بأنــه جــدد لــي إجارهــا فالصحيــح أنــي‬\n      ‫لــم أقــم بتجديــد إجــار تلــك الشــقة مــع املدعــي وإمنــا بقيــت فيهــا شــهر ًا‬\n      ‫واحــدا فقــط كــون أوالدي يقومــون حينهــا بإكمــال اختباراتهــم وقــد‬\n      ‫اخبرنــي بالفعــل إن كنــت أرغــب يف جتديــد إيجارهــا فســألته عــن‬\n      ‫مقــدار أجرتهــا فأخبرنــي بــان أجرتهــا تبلــغ خمســة وثالثــن ألــف ريــال‬\n      ‫فأخبرتــه بــأن هــذه األجــرة كبيــرة جــدا فــان كان ســيخفضها لــي‬\n      ‫فســوف أبقــى وإال فســوف اخــرج منهــا فأصــر علــى أن تكــون األجــرة‬\n      ‫بخمســة وثالثــن ألــف ريــال وأعطيتــه قســط الشــهر الــذي مكثتــه فيهــا‬\n      ‫البالــغ ثــاث آالف ريــال أعطيتــه إيــاه بتاريــخ ‪1432/2/5‬ه ـ وبالتالــي لــم‬\n      ‫أجــدد معــه بخصــوص تلــك الشــقة أيعقــد هكــذا قــال ثــم عرضــت علــى‬\n      ‫املدعــي مــا دفــع بــه املدعــى عليــه مــن كــون الثالثــن ألــف ريــال التــي‬\n      ‫حســمها كان نظيــر إصالحــات لعيــوب يف صــرف العمــارة الصحــي و‬\n      ‫كانــت إصالحاتــه تلــك مبوافقتــه فأجــاب بقولــه إن مــا ذكــره املدعــى‬\n      ‫عليــه غيــر صحيــح فلــم أوافــق علــى مســألة اإلصالحــات إضافــة إلــى‬\n      ‫أن البنــد الرابــع مــن عقــد اإلجــار ينــص علــى أنــه إن حصــل تلــف يف‬\n      ‫املوقــع املؤجــر فــإن علــى املدعــى عليــه القيــام بإصــاح جميــع مــا تلــف‬\n      ‫و شــراء ذلــك وتركيبــه يف محلــه بــدون مماطلــة و ليــس لــه احلــق يف‬\n      ‫املطالبــة بالتعويــض عنهــا يف حالــة اإلخــاء و كذلــك البنــد اخلامــس‬\n      ‫مــن عقــد الصلــح الــذي ينــص أن يقــوم املســتأجر بتســليم العــن بــدون أي‬\n      ‫أضــرار أو ســوء اســتخدام هكــذا قــال وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫أجــاب بقولــه إن الصحيــح هــو مــا قلتــه فلقــد كان ذلــك احلســم بنــاء علــى‬\n      ‫موافقتــه هكــذا قــال ثــم ســألته هــل لديــك البينــة علــى ذلــك فأجــاب‬\n      ‫بالنفــي ثــم ســألته هــل ترغــب يف ميــن املدعــي علــى عــدم موافقتــه علــى‬\n\n\n‫‪353‬‬\n\f‫حســم ثالثــن ألــف ريــال مــن أجــرة العمــارة نظيــر إصالح عيوبهــا فأجاب‬\n‫بقولــه نعــم إنــي أرغــب يف ميينــه فعرضــت اليمــن علــى املدعــي فأســتعد‬\n‫ببذلهــا فحلــف قائــا و اهلل العظيــم الــذي ال الــه اال هــو عالــم الغيــب‬\n‫والشــهادة بأنــي لــم أوافــق علــى أن يحســم هــذا املدعــى عليــه ثالثــن‬\n‫ألــف ريــال مــن أجــرة العمــارة نظيــر إصالحــات العيــوب التــي قــام بهــا‬\n‫و اهلل العظيــم هكــذا حلــف عليــه أمــرت برفــع اجللســة الــى يــوم األحــد‬\n‫‪1433/11/21‬ه ـ الســاعة ‪ 12 : 00‬للدراســة والتأمــل تأجلــت ويف يــوم‬\n‫األحــد ‪1433/11/21‬ه افتتحــت اجللســة وفيهــا حضــر املدعــي وحضــر‬\n‫حلضــوره املدعــو ‪.......................‬بالســجل املدنــي رقــم ‪ ...................‬وأبــرز‬\n‫صــورة وكالتــه عــن املدعــى عليــه‪ ..................‬بالوكالــة الصــادرة مــن‬\n‫كتابــة العــدل الثانيــة مبكــة املكرمــة رقــم ‪ 30034‬يف ‪1430/8/10‬هـ‬\n‫املخــول لــه فيهــا املرافعــة و املدافعــة و حضــور اجللســات الــخ ومذيــل بختــم‬\n‫اعتمــاد وجــرى ربــط صــوره منهــا يف املعاملــة ثــم ســألته عــن أصلهــا فقــال‬\n‫أن أصلهــا مــع املدعــى عليــه و بعــد دراســة مــا تقــدم مــن الدعــوى واإلجابة‬\n‫و لطلــب املدعــي الــزام املدعــى عليــه بدفــع املبلــغ املقــدر بثالثــن ألــف‬\n‫ريــال وذلــك نظيــر املبلــغ الــذي قــام بحســمه مــن كامــل أجــرة العمــارة‬\n‫يف الســنوات اإلجاريــه ولطلبــه أيضــا الزامــه بدفــع الباقــي مــن األجــرة‬\n‫الســنوية مــن ‪1432/2/1‬ه ـ حتــى ‪1433/3/1‬ه ـ وقدرهــا اثنــان وثالثــون‬\n‫ألــف ريــال و إلقــرار املدعــى عليــه بصحــة حســم املبلــغ البالــغ ثالثــن‬\n‫ألــف ريــال أو زيــادة كمــا قــال و دفعــه بــأن حســمه كان الصالحاتــه‬\n‫لعيــوب يف تلــك العمــارة وأن حســمه ذلــك كان مبوافقــة املدعــي و ال‬\n‫أنــكار املدعــي لذلــك ولعجــز املدعــى عليــه عــن إقامــة البينــة علــى دفعــه‬\n‫ذلــك وطلبــه ميــن املدعــي وبذلــه لهــا علــى النحــو املرصــود وملــا قــرره أهــل‬\n\n\n                                                                                               ‫‪354‬‬\n\f      ‫العلــم يف هــذا اجلانــب حيــث قــال ابــن قنــدس يف حاشــيته علــى الفــروع‬\n      ‫((فــإن اختلفــا فيقــدر مــا أنفــق فالقــول قــول املكــري ألنــه منكــر فــإن‬\n      ‫لــم يشــرط لكنــه أذن لــه يف اإلنفــاق ليحتســب لــه يف األجــرة ففعــل‬\n      ‫ثــم أختلفــا فالقــول قــول املكــري وإن أنفــق مــن غيــر إذنــه لــم يرجــع‬\n      ‫بشــيء ألنــه أنفــق علــى مالــه بغيــر إذنــه نفقــة غيــر واجبــة علــى املالــك‬\n      ‫فأشــبه مــا لــو عمــر لــه دارا أخــرى )) ‪ 162/7‬وألن املدعــى عليــه بقــي‬\n      ‫يف العــن املؤجــرة شــهرا حتــى ‪1432/2/1‬ه ـ ودفــع للمدعــي قســط تلــك‬\n      ‫املــدة كمــا قــال وصادقــه املدعــي علــى ذلــك مبطالبتــه بباقــي األجــرة‬\n      ‫وملــا قالــه ابــن رجــب رحمــه اهلل تعالــى يف قواعــده ( نقــل جماعــة عــن‬\n      ‫أحمــد مــا يــدل علــى أن اإلجــارة الصحيحــة ال جتــب منهــا األجــرة اال‬\n      ‫بقــدر االنتفــاع إذا تــرك املســتأجر بقيــة االنتفــاع بعــذر مــن جهتــه ) بنــاء‬\n      ‫علــى ذلــك فقــد حكمــت علــى املدعــى عليــه ‪ ...........................‬بــأن‬\n      ‫يدفــع للمدعــي ‪ ................‬ثالثــن ألــف ريــال نظيــر املبالــغ التــي قــام‬\n      ‫بحســمها مــن أجــرة العمــارة يف الســنوات اإلجاريــة وصرفــت النظــر عــن‬\n      ‫طلــب املدعــي املذكــور احلكــم علــى املدعــى عليــه بدفــع الباقــي مــن‬\n      ‫األجــرة عــن املــدة التــي حددهــا يف دعــواه و بذلــك حكمــت وبعرضــه‬\n      ‫علــى املدعــي قــرر قناعتــه بــه بينمــا قــرر املدعــى عليــه وكالــة اعتراضــه‬\n      ‫عليــه فجــرى إفهامــه مبراجعــة احملكمــة خــال عشــرة أيــام مــن تاريخــه‬\n      ‫الســتالم نســخة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومـ ًا‬\n      ‫فــإن لــم يفعــل خاللهــا فــإن حقــه يف االعتــراض يســقط ويكتســب‬\n      ‫احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                        ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم عــادت أوراق املعاملــة من محكمة االســتئناف‬\n\n\n‫‪355‬‬\n\f‫باخلطاب رقم ‪ 34512510‬يف ‪1434/3/4‬هـ رفقها الصك الشرعي رقم‬\n‫‪33480606‬يف ‪1433/12/28‬ه ـ مظهــر ًا عليــه بقــرار الدائــرة احلقوقيــة‬\n‫الســابعة مبحكمــة االســتئناف رقــم ‪ 3452991‬يف ‪1434/3/2‬ه ـ‬\n‫املتضمــن أنــه بدراســة احلكــم وصــورة ضبطــه والئحتيــه االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم‪ .‬قاضــي اســتئناف‪ ...........‬ختــم وتوقيــع‬\n‫قاضــي اســتئناف‪ ...........‬ختــم وتوقيــع رئيــس الدائــرة‪ ...........‬ختــم‬\n‫وتوقيــع ‪ .‬حــرر يف ‪1434/4/17‬ه ــوصل اهلل علــى نبينــا محمــد وعلــى‬\n                                                               ‫آلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ....................‬القاضــي باحملكمــة‬\n‫العامــة مبكــة املكرمــة خلــف فضيلــة الشــيخ ‪ .......................‬ففــي هــذا‬\n‫اليــوم األحــد ‪1434/5/19‬ه ــحضر املدعــي ‪ ...........................‬ســجل‬\n‫مدنــي رقــم ‪ ......................‬وقــرر بقولــه إننــي اســتلمت مــن املدعــى عليــه‬\n‫‪ ..................‬كامــل املبلــغ احملكــوم لــي بــه عليــه مبوجــب الصــك رقــم‬\n‫‪ 33480606‬يف ‪1433/12/28‬ه ـ وقــدره ثالثــون ألــف ريــال ولــم يبقــى‬\n‫لــي شــيء بذمتــه بخصــوص هــذه الدعــوى وأطلــب التهميــش بذلــك علــى‬\n‫صــك احلكــم هكــذا قــرر ‪ .‬عليــه أمــرت بالتهميــش بذلــك علــى صــك‬\n‫احلكــم وســجله وبــاهلل التوفيــق وصــل اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم حــرر يف ‪1434/5/19‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ فقــد‬\n‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪32/27445‬‬\n‫وتاريــخ ‪1434/02/25‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n\n\n                                                                                          ‫‪356‬‬\n\f      ‫الشــيخ ‪ ........................‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n      ‫املســجل برقــم ‪ 33480606‬وتاريــخ ‪1433/12/28‬ه ـ املتضمــن دعــوى‬\n      ‫‪ ......................‬ضــد ‪ ،....................‬وبدراســة الصــك وص ــورة ضبط ــه‬\n      ‫والئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‪ .‬واهلل املوفــق‪.‬‬\n                    ‫وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪357‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":348,"source_page_end":357,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"611a00b0a1b1a5fc638338314ca3a01524c67e988b775723ee013cab95ae6358","normalized_text_hash":"2b0d129f0fac94ce5e4ddf0ee9ad5d91eeb7cf40beb18779842c92ed8c12fe47","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p348-33480606"},{"id":"7e2049c1-eb95-512e-8a6e-e0bcf9fb717a","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -إخاء عقار من غائب -اإلعان يف صحيفة محلية لتبليغ املدعى عليه -البينة للمدعى شهادة الشهود العدول واليمن -وجوب الوفاء بالعقود -حفظ محتويات العن يف بيت املال وبيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -احلكم بفتح العن وإخالءها -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه به -الغائب على حجته متى حضر.","document_number":"34185350","case_number":"83530306","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/10","year":"1434","subject":"عقد -إجارة -إخاء عقار من غائب -اإلعان يف صحيفة محلية لتبليغ املدعى عليه -البينة للمدعى شهادة الشهود العدول واليمن -وجوب الوفاء بالعقود -حفظ محتويات العن يف بيت املال وبيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -احلكم بفتح العن وإخالءها -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه به -الغائب على حجته متى حضر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34185350 :‬‬\n                   ‫َر ْق ُم الدعوى‪83530306 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34312393‬تاريخه‪1434/9/3:‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬إخــاء عقــار مــن غائــب ‪ -‬اإلعــان يف صحيفــة محليــة‬\n‫لتبليــغ املدعــى عليــه ‪ -‬البينــة للمدعــى شــهادة الشــهود العــدول‬\n‫واليمــن ‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬حفــظ محتويــات العــن يف بيــت‬\n‫املــال وبيــع مــا يخشــى تلفــه وإيــداع ثمنــه يف بيــت املــال ‪ -‬احلكــم بفتــح‬\n‫العــن وإخالءهــا ‪ -‬رفــع احلكــم حملكمــة االســتئناف لتعــذر تبليــغ‬\n                 ‫املدعــى عليــه بــه‪ -‬الغائــب علــى حجتــه متــى حضــر‪.‬‬\n\n\n\n\n                     ‫‪ .1‬قوله تعالى (يا أيها الذين آمنوا أوفوا بالعقود)‪.‬‬\n‫‪ .2‬قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى‬\n                                         ‫املدعــى عليــه) رواه الترمــذي‪.‬‬\n‫‪ .3‬قولــه صلــى اهلل عليــه وســلم (ال ضــرر وال ضــرار) رواه أبــو داوود‬\n                                                    ‫وصححــه احلاكــم‪.‬‬\n                          ‫‪ .4‬املادة ‪ 55‬و‪ 176‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه‬\n‫اســتأجر ملحق شــقة رقم ‪ ...‬من العمارة مبدينة ‪ ...‬بحي ‪ ...‬بأجرة ســنوية‬\n‫قدرهــا اثنــا عشــر ألفـ ًا وخمســمائة ريــال اعتبارا مــن ‪1429/1/1‬هـ وقد‬\n\n                                                                                      ‫‪358‬‬\n\f      ‫تخلــف عــن ســداد األجــرة فتــرة طويلــة وهــو غيــر موجــود بالشــقة منــذ‬\n      ‫شــهر رمضــان لعــام ‪1431‬ه ـ وقــد غــادر اململكــة مغــادرة نهائيــة خــروج‬\n      ‫نهائــي ويطلــب فتــح الشــقة هكــذا ادعــى ‪ ،‬املدعــى عليــه أجنبــي غــادر‬\n      ‫اململكــة مغــادرة نهائيــة حســب إفــادة وحــدة األمــن بالدوائــر الشــرعية‬\n      ‫املرفــق باملعاملــة فجــرى ســماع الدعــوى غيابيــا بنــاء علــى املــادة ‪ 55‬مــن‬\n      ‫نظــام املرافعــات الشــرعية ‪ ،‬جــرى اإلعــان يف الصحيفــة عــن موعــد‬\n      ‫اجللســة ‪ ،‬بينــة املدعــي شــاهدان شــهدا طبــق دعــواه ‪ ،‬حلــف املدعــي‬\n      ‫اليمــن علــى صحــة دعــواه بعــد طلبهــا منــه ‪ ،‬أبــرز املدعــي صــك ملكيــة‬\n      ‫العقــار وعقــد اإليجــار ‪ ،‬فبنــاء علــى البينــة املتمثلــة يف الصــك ملكيــة‬\n      ‫العقــار ‪ ،‬وعقــد اإليجــار ‪ ،‬وشــهادة الشــاهدين املعدلــة شــرعا ‪ ،‬وبنــاء‬\n      ‫علــى ميــن املدعــي أصالــة ووكالــة بصفتــه مباشــر عقــد اإليجــار وأحــد‬\n      ‫مــاك العقــار ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود) ‪،‬‬\n      ‫وحلديــث (البينــة علــى املدعــي واليمني على املدعى عليه) رواه الترمذي‪،‬‬\n      ‫وحلديــث ( ال ضــرر و ال ضــرار ) رواه أبــو داوود وصححــه احلاكــم ‪،‬‬\n      ‫وألن الضــرر يف الشــريعة مرفــوع ‪ ،‬وبنــاء علــى املــادة ‪ 55‬و ‪ 176‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ‪ ،‬ملــا تقــدم صــدر احلكم بفتــح العقار محل الدعوى‬\n      ‫وإخــاءه عــن طريــق اجلهــات املختصــة ‪ ،‬واالحتفــاظ مبوجــودات العقــار‬\n      ‫مــا يخــص املدعــى عليــه منــه لــدى اجلهــة املعنيــة ‪ ،‬وبيــع مــا يخشــى تلفــه ‪،‬‬\n      ‫وإيــداع ثمنــه لــدى بيــت مــال احملكمــة وإفهــام املدعــي بــأن املدعــى عليــه‬\n      ‫علــى حجتــه متــى حضــر‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة الرابعــة‬\n                                 ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n‫‪359‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 83530306‬وتاريــخ‬\n‫‪ 1432/04/01‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3227852‬وتاريــخ‬\n‫‪ 1432/04/01‬ه ـ ففــي يــوم االربعــاء املوافق‪ 1432/07/06‬هـ أفتتحت‬\n‫اجللســة الســاعة ‪ 09 : 23‬وفيهــا حضــر املدعــى ‪.....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪.....‬ولــم يحضــر املدعــى عليــه وال وكيــل‬\n‫عنــه وكنــا قــد كتبنــا الــى وحــدة الدوائــر الشــرعية فوردنــا خطابهــم‬\n‫برقــم ‪ 14713‬وتاريــخ ‪1432/07/03‬ه ـ وفيــه عليــه نفيــد فضيلتكــم‬\n‫بانــه بالرجــوع للحاســب االلــى طرفنــا اتضــح بانــه مســافر الــى مصــر‬\n‫العربيــة بتاريــخ ‪1431/9/16‬ه ـ ولــم تثبــت عودتــه حتــى تاريخــه كمــا‬\n‫يتضــح لكــم مــن البرنــت املرفــق أ‪.‬ه ـ لــذا فقــد جــرى اثبــات ذلــك‪ .‬ثــم‬\n‫انــه يف يــوم االحــد املوافــق ‪1433/03/13‬ه ـ أفتتحــت اجللســة الســاعة‬\n‫‪ 11 : 53‬وفيهــا حضــر املدعــى ولــم يحضــر املدعــى عليــه ‪..........‬وال‬\n‫وكيــل عنــه وقــد طلــب املدعــى االعــان يف احــد الصحــف احملليــة عــن‬\n‫موعــد اجللســة القادمــة فاجبتــه الــى طلبــه لــذا رفعــت اجللســة ‪ .‬ثــم انــه يف‬\n‫يــوم األحــد املوافــق‪ 1433/06/08‬ه ـ افتتحــت اجللســة الســاعة ‪01 : 44‬‬\n‫وفيهــا حضــر املدعــى ‪.....‬ولــم يحضــر املدعــى عليــه ‪ .....‬وال وكيــل عنــه‬\n‫ومت االعــان عــن موعــد هــذه اجللســة يف صحيفــة (‪)000‬يــوم الســبت ‪24‬‬\n‫ربيــع االخــر ‪1433‬ه ـ عــدد رقــم ‪ 17860‬وقــد طلــب املدعــى الســير يف‬\n‫القضيــة غيابيــا حســب املــاده اخلامســة واخلمســون مــن نظــام املرافعــات‬\n\n                                                                                        ‫‪360‬‬\n\f      ‫فاجبتــه الــى طلبــه وبســؤاله عــن دعــواه قــال ان املدعــى عليــه ‪.....‬مصــري‬\n      ‫اجلنســية مبوجــب االقامــة رقــم ‪.....‬مســتأجر لدينــا ملحــق شــقة رقــم ‪ ...‬من‬\n      ‫العمــارة مبدينــة ‪ ...‬بحــى ‪.....‬وعليــه متأخــرات ايجاريــه ولــه فتــرة طويلــة‬\n      ‫غيــر موجــود بالشــقة منــذ شــهر رمضــان لعــام ‪1431‬ه ـ وســألنا عنــه‬\n      ‫بعملــه قالــوا اخــذ خــروج نهائــي لــذا اطلــب فتــح الشــقه واحتســاب احلقوق‬\n      ‫املاليــة حتــى تاريــخ فتــح الشــقة هــذه دعــواى هــذا وبســؤاله عــن بينتــه قــال‬\n      ‫اطلــب امهالــي الحضارهــا لــذا رفعــت اجللســة واختتمــت اجللســة الســاعة‬\n      ‫الثانيــة ‪ .‬فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة‬\n      ‫والقائــم بعمــل الشــيخ ‪.....‬ففــي يــوم الســبت املوافــق‪1434/04/06‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة ‪ 08.30‬وفيهــا حضــر املدعــي ‪.....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬ولــم يحضــر املدعــى عليــه ‪.....‬‬\n      ‫وال وكيــل عنــه وكانــت اجللســة املاضيــة قــد رفعــت إلحضــار البينــة مــن‬\n      ‫قبــل املدعــي وبســؤاله قــال ‪ :‬لقــد احضــرت الشــهود وهــم ‪ .....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬وعمــره ‪ 35‬ومقــر اقامتــه جــده‬\n      ‫ويعمــل لــدى محافظــه جــده وال توجــد صلــه قرابــه بينــه وبــن احــد‬\n      ‫املدعــن وحضــر الشــاهد الثانــي ‪.....‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪.....‬ومقــر اقامتــه جــده وعمــره ‪ 43‬ويعمــل لــدى شــركة‬\n      ‫‪.....‬الغذائيــة وال توجــد قرابــه بينــه وبــن املدعــن وشــهد كال منهمــا‬\n      ‫مبفــرده بقولــه ‪ :‬اشــهد بــاهلل العظيــم ان املســتأجر ‪.....‬مصــري اجلنســية‬\n      ‫مســتأجر امللحــق يف العمــارة التــي نســكن بهــا يف جــده حــي ‪...‬وهــي‬\n      ‫ملــك ‪.....‬وقــد تــرك املســتأجر الشــقة وال نعلــم عنــه شــيء منــذ فتــرة‬\n      ‫طويلــة ولــم نشــاهده والشــقة محــل الدعــوى مقفلــة منــذ عــام ‪1431‬ه ـ‬\n      ‫‪ .‬هكــذا شــهدا ‪ .‬وعــدال مــن قبــل ‪.....‬مينــي اجلنســية مبوجــب االقامــة‬\n\n\n‫‪361‬‬\n\f‫رقــم ‪.....‬و‪.....‬مينــي اجلنســية مبوجــب االقامــة رقــم ‪ ،.....‬وبســؤال املدعــي‬\n‫أصالــة عــن صــك امللكيــة للعقــار محــل الدعــوى قــال ‪ :‬اطلــب امهالــي‬\n‫إلحضارهــا غــدا فأجبتــه لطلبــة والزمتــه بإحضارهــا يــوم غــدا االحــد‬\n‫املوافق ‪1434/4/07‬هـ لذا رفعت اجللســة الســاعة ‪ 08.45‬فلدي أنا ‪.....‬‬\n‫القاضــي يف احملكمــة العامــة مبحافظــة جــدة والقائــم بعمــل الشــيخ ‪.....‬‬\n‫ففــي يــوم االثنــن املوافق‪1434/04/08‬ه ـ افتتحــت اجللســة الســاعة ‪00‬‬\n‫‪ 01 :‬وفيهــا حضــر املدعــي ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪.....‬ولــم يحضــر املدعــى عليــه ‪.....‬وال وكيــل عنــه وكانــت اجللســة‬\n‫املاضيــة قــد رفعــت إلمهــال املدعــي إلحضــار صــك امللكيــة للعقــار ‪،‬‬\n‫وقــرر املدعــي قائــا ‪ :‬إن العقــار ملــك للورثــة وأنــا مــن قــام مبباشــرة‬\n‫العقــد ‪ ،‬وأطلــب تصحيــح الدعــوى ليكــون املدعــي فيهــا هــم ورثــة ‪.....‬‬\n‫عــدا ‪ ، ...‬وأطلــب حصــر دعــواي يف هــذه الدعــوى علــى إخــاء العقــار‬\n‫‪ ،‬واحتفاظــي وموكلــي بحــق إقامــة دعــوى مســتقلة بخصــوص األجــرة‬\n‫املتأخــرة ‪ .‬وبســؤاله عــن دعــواه ليتــم حتريرهــا أكثــر قــال ‪ :‬إن املدعــى‬\n‫عليه ‪ .....‬مصري اجلنســية مبوجب اإلقامة رقم ‪.....‬مســتأجر لدينا ملحق‬\n‫شــقة رقــم ‪ ...‬مــن العمــارة مبدينــة جــدة بحــي ‪...‬واململوكــة لنــا بالصــك‬\n‫رقــم ‪ 1040‬يف ‪1421/1/27‬هــ‪ ،‬مبوجــب عقــد إيجــار رقــم ‪ 14‬وتاريــخ‬\n‫(بــدون) بأجــرة ســنوية قدرهــا اثنــا عشــر ألفــا وخمســمائة ريــال اعتبــارا‬\n‫مــن تاريــخ ‪1429/1/1‬هــ‪ ،‬وقــد تخلــف عــن ســداد األجــرة لفتــرة طويلــة‬\n‫‪ ،‬وبالســؤال عنــه لــم جنــده منــذ شــهر رمضــان لعــام ‪1431‬ه ـ وســألنا‬\n‫عنــه بعملــه فأفادونــا بــأن املدعــى عليــه أخــذ خــروج نهائــي ‪ ،‬لــذا أطلــب‬\n‫احلكــم بفتــح الشــقة محــل الدعــوى وإخــاء العقــار ‪ .‬هــذه دعــواي ‪ .‬ثــم‬\n‫أبــرز املدعــي أصالــة ووكالــة عقــد اإليجــار ‪ ،‬ومت تزويــد أوراق املعاملــة‬\n\n\n                                                                                     ‫‪362‬‬\n\f      ‫بنســخة منــه ‪ ،‬كمــا أبــرز أصــل الصــك الصــادر مــن كتابــة العــدل‬\n      ‫األولــى بجــدة برقــم ‪ 1040‬يف ‪1421/1/27‬ه ـ واملهمــش عليــه بعبــارة‬\n      ‫(فقــد اصطلــح وتخــارج ورثــة املرأة‪.....‬عــن نصيبهــم يف هــذا العقــار لبقيــة‬\n      ‫ورثــة ‪.....‬وذلــك مبوجــب صــك املخارجــة الصــادر منــا برقــم ‪ 25/35‬يف‬\n      ‫‪1428/2/2‬ه ـ قالــه القاضــي باحملكمــة العامــة بالريــاض ‪..........‬جــرى‬\n      ‫إحلاقــة وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــة أجمعــن) أه ـ‬\n      ‫كمــا أبــرز صــورة صــك حصــر الورثــة الصــادر مــن محكمــة الريــاض‬\n      ‫برقــم ‪ 26/48‬وتاريــخ ‪1423/6/17‬ه ـ ونصــه (ثبــت بالبينــة املعدلــة‬\n      ‫وفــاة ‪.....‬بتاريــخ ‪1423/6/8‬ه ـ وانحصــار إرثــة يف والدتــة ‪.....‬املولــوده‬\n      ‫عــام ‪1343‬ه ـ ويف زوجتــة ‪.....‬املولــودة عــام ‪1360‬ه ـ ويف أوالدة البالغــن‬\n      ‫جميعــا وهــم ‪.....‬املولــود يف ‪1389‬ه ـ ‪.....‬املولــود عــام ‪1385‬ه ـ ‪.....‬املولــوده‬\n      ‫عــام ‪1386‬ه ـ ‪.....‬املولــوده عــام ‪1387‬ه ـ ‪.....‬املولــود عــام ‪1392‬ه ـ ‪.....‬‬\n      ‫املولــود عــام ‪1394‬ه ـ ‪.....‬املولــوده عــام ‪1398‬ه ـ ‪.....‬املولــود عــام ‪1403‬ه ـ‬\n      ‫وكانــت وفاتــة يف مدينــة جــده الســاعة الواحــدة ظهــرا) أه ـ كمــا أبــرز‬\n      ‫صــورة الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالريــاض برقــم‬\n      ‫‪ 56514‬وتاريخ‪1424/4/7‬ه ـ واملــوكل فيهــا مــن قبــل ‪.....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪..........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪.....‬باألصالــة عــن نفســيهما وبالوكالــة عــن ورثــة‬\n      ‫‪ .....‬بالوكالــة رقــم‪ 56505‬يف ‪1424 /4 /7‬ه ـ جلــد ‪ 9973‬الصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة ‪ ،‬كمــا أبــرز صــورة الوكالــة الصــادرة‬\n      ‫مــن كتابــة عــدل الريــاض الثانيــة برقــم ‪ 56505‬وتاريــخ ‪1424/4/7‬ه ـ‬\n      ‫والتــي تضمنــت مــا يلــي (حضــر كل مــن ‪ .....‬ســعودي مبوجــب ســجل‬\n      ‫مدنــي رقــم ‪ ...........‬و‪ .....‬ســعودي مبوجــب ســجل مدنــي رقــم ‪ .....‬و‪.....‬‬\n\n\n‫‪363‬‬\n\f‫ســعودي مبوجــب ســجل مدنــي رقــم ‪ .....‬و‪ .....‬ســعودية مبوجــب ســجل‬\n‫مدنــي رقــم ‪.....‬و‪ .....‬ســعودية مبوجــب ســجل مدنــي رقــم ‪.....‬و‪.....‬ســعودية‬\n‫مبوجــب ســجل مدنــي رقــم ‪ ..........‬ســعودية مبوجــب ســجل مدنــي رقــم‬\n‫‪ ........‬قرروا بقولهم أننا أقمنا ‪ .....‬و‪ .....‬ســعوديا اجلنســية) ‪ ،‬ومت إرفاقها‬\n‫باملعاملــة ‪،‬وبســؤال املدعــي أصالــة ووكالــة اليمــن علــى صحــة دعــواه‬\n‫اســتعد لذلــك ‪ ،‬ثــم حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو‬\n‫أن املدعــى عليــه ‪.....‬مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪.....‬مســتأجر‬\n‫لدينــا ملحــق شــقة رقــم ‪ 7‬مــن العمــارة مبدينــة جــدة بحــى ‪ ...‬واململوكــة‬\n‫لنــا بالصــك رقــم ‪ 1040‬يف ‪1421/1/27‬ه ـ ‪ ،‬مبوجــب عقــد إيجــار رقــم‬\n‫‪ 14‬وتاريــخ (بــدون) بأجــرة ســنوية قدرهــا اثنــا عشــر ألفــا وخمســمائة‬\n‫ريــال اعتبــارا مــن تاريــخ ‪1429/1/1‬ه ـ ‪ ،‬وقــد تخلــف عــن ســداد األجــرة‬\n‫لفتــرة طويلــة ‪ ،‬وبالســؤال عنــه لــم جنــده منذ شــهر رمضان لعــام ‪1431‬هـ‬\n‫وســألنا عنــه بعملــه فأفادونــا بــأن املدعــى عليــه أخــذ خــروج نهائــي ‪.‬‬\n‫هكــذا حلــف ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى والبينــة املتمثلــة يف‬\n‫الصــك رقــم ‪ 1040‬يف ‪1421/1/27‬ه ـ ‪ ،‬وعقــد إيجــار رقــم ‪ 14‬وتاريــخ‬\n‫(بــدون) ‪ ،‬وشــهادة الشــاهدين ‪ ...‬و‪ ...‬املعدلــة شــرعا ‪ ،‬وبنــاء علــى صــك‬\n‫حصــر الورثــة رقــم ‪ 26/48‬وتاريــخ ‪1423/6/17‬ه ـ ‪ ،‬وبنــاء علــى ميــن‬\n‫املدعــي أصالــة ووكالــة بصفتــه مباشــر عقــد اإليجــار وأحــد مــاك‬\n‫العقــار ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود)‪ ،‬وحلديــث‬\n‫(البينــة علــى املدعــي واليمــن علــى املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال‬\n‫أبــو عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب النبــي صلــى اهلل عليــه‬\n‫وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ‪،‬‬\n‫وحلديــث ( ال ضــرر و ال ضــرار ) رواه أبــو داوود وصححــه احلاكــم ‪،‬‬\n\n\n                                                                                        ‫‪364‬‬\n\f      ‫وألن الضــرر يف الشــريعة مرفــوع ‪ ،‬وبنــاء علــى املــادة ‪ 55‬و ‪ 176‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت بفتــح العقــار محــل‬\n      ‫الدعــوى وإخــاؤه عــن طريــق اجلهــات املختصة ‪ ،‬واالحتفــاظ مبوجودات‬\n      ‫العقــار مــا يخــص املدعــى عليــه منــه لــدى اجلهــة املعنيــة ‪ ،‬وأمــرت ببيــع مــا‬\n      ‫يخشــى تلفــه ‪ ،‬وإيــداع ثمنــه لــدى بيــت مــال احملكمــة ‪ .‬وبــه حكمــت ‪.‬‬\n      ‫وأفهمــت املدعــي بــأن املدعــى عليــه علــى حجتــه متــى حضــر ‪ ،‬وقــررت‬\n      ‫بعــث املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم ‪ .‬وأقفلــت اجللســة‬\n      ‫الســاعة ‪ . 02 : 00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/04/08‬ه ـ‬\n      ‫احلمد هلل والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪.:‬فقد جرى اطالعنا‬\n      ‫نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة الشــيخ ‪.....‬‬\n      ‫القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد ‪ 34185350‬وتاريــخ‬\n      ‫‪1434/4/10‬ه ـ املتضمــن دعــوى ‪.....‬ضــد ‪.....‬واحملكــوم فيــه مبــادون‬\n      ‫باطنــه ‪.‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم‬\n      ‫واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪365‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":358,"source_page_end":365,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b3f2ecb1246eb33f22893c5e31a2713f1b71e3b90fd8e313eaac853e6afe2277","normalized_text_hash":"313d531853d82f81a27d73f5988e66e7facaeb7969d4eb892bf86b3e5f07aa20","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p358-34185350"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"842c6dba-8818-5910-9e4e-a46c53cca036","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار لعدم سداد األجرة -وجوب الوفاء بالعقود - دفع املدعى عليه بإقراض املدعي ولم يثبت ذلك -حلف اليمن على نفي الدفع -احلكم بإخاء العقار -إقرار املدعي باستالم العقار خالي ا من الشواغل .","document_number":"34285050","case_number":"33550457","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/1","year":"1434","subject":"إجارة -إخاء عقار لعدم سداد األجرة -وجوب الوفاء بالعقود - دفع املدعى عليه بإقراض املدعي ولم يثبت ذلك -حلف اليمن على نفي الدفع -احلكم بإخاء العقار -إقرار املدعي باستالم العقار خالي ا من الشواغل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/1 :‬هـ‬\n                      ‫ُ‬                 ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34285050 :‬‬\n                         ‫َر ْق ُم الدعوى‪33550457 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34336864‬تاريخه‪1434/10/21 :‬هـ‬\n\n\n      ‫إجــارة ‪ -‬إخــاء عقــار لعــدم ســداد األجــرة ‪ -‬وجــوب الوفــاء بالعقــود ‪-‬‬\n      ‫دفــع املدعــى عليــه بإقــراض املدعــي ولــم يثبــت ذلــك ‪ -‬حلــف اليمــن‬\n      ‫علــى نفــي الدفــع ‪ -‬احلكــم بإخــاء العقــار ‪ -‬إقــرار املدعــي باســتالم‬\n                                                  ‫العقــار خالي ـ ًا مــن الشــواغل ‪.‬‬\n\n\n\n\n                          ‫‪ -1‬قوله تعالى «يا أيها الذين آمنوا أوفوا بالعقود»‬\n                     ‫‪ -2‬قوله صلى اهلل علية وسلم «املسلمون على شروطهم»‬\n      ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم «البينــة علــى املدعــى واليمــن علــى مــن‬\n                                                                                ‫أنكر»‬\n\n\n\n\n      ‫دعــوى املدعــى وكالــة ضــد املدعــى عليــه ومضمــون الدعــوى أن املدعــى‬\n      ‫عليــه قــد اســتأجر مــن املدعــى أصالــة عقــار ًا ملدة تبدأ مــن ‪1427/8/1‬هـ‬\n      ‫إلــى ‪1434/8/1‬ه ـ بأجــرة ســنوية قدرهــا عشــرة اآلف ريــال وان املدعــى‬\n      ‫عليــه قــد خالــف العقــد بتخلفــه عــن ســداد اإليجــار مــن ‪1431/8/28‬ه ـ‬\n      ‫وطلــب املدعــى وكالــة إلــزام املدعــى عليــه بإخــاء العقــار‪ ،‬أجــاب‬\n      ‫املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر أن املدعــى أصالــة قــد أخــذ‬\n      ‫منــه قرضــا قــدرة خمســون ألــف ريــال بعــد اســتالم األجــرة عــام ‪1430‬ه ـ‬\n\n‫‪313‬‬\n\f‫وعندمــا طالبــه بالقــرض ســلمه عشــرة اآلف ريــال والباقــي ذكــر انــه‬\n‫ســوف يحســمها مــن األجــرة ولــذا فقــد طلــب املدعــى عليــه صــرف النظــر‬\n‫عــن الدعــوى‪ ،‬أجــاب املدعــى وكالــة عــن دعــوى القــرض باإلنــكار‪،‬‬\n‫قــرر املدعــى عليــه عــدم وجــود بينــة علــى دعــوى القــرض وطلــب ميــن‬\n‫املدعــى أصالــة‪ ،‬حضــر املدعــى أصالــة وحلــف اليمــن علــى عــدم‬\n‫اســتالم األجــرة األعــوام ‪ 1432‬و ‪ 1433‬و ‪ 1434‬ه ـ وان دعــوى القــرض‬\n‫غيــر صحيحــة‪ ،‬جــرى االطــاع علــى العقــد بــن الطرفــن ‪ -‬ولألســباب‬\n‫املرصــودة يف نــص القضيــة ولقولــه تعالــى ((يــا أيهــا الذيــن امنــوا أوفــوا‬\n‫بالعقــود)) صــدر احلكــم علــى املدعــى عليــه بإخــاء العقــار وتســليمه‬\n‫للمدعــى خاليــا مــن الشــواغل‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪،‬‬\n‫صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة باملصادقــة علــى‬\n             ‫احلكم‪،‬قــرر املدعــى اســتالمه للعقــار خاليــا مــن الشــواغل ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33550457‬وتاريــخ‬\n‫‪1433/08/27‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331614840‬وتاريــخ‬\n‫‪1433/08/27‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/01/20‬ه ـ افتتحت‬\n‫اجللســة الســاعة الثامنــة والنصــف لســماع دعــوى ضــد ســجل مدنــي رقــم‬\n‫بخصــوص دعــوى إخــاء عقــار مــن مســتأجر حاضــر ‪ ،‬وفيهــا حضــر‬\n‫املدعــى عليــه ولــم يحضــر املدعــي وال مــن ينــوب عنــه ولــم يتقــدم بعــذر‬\n‫تقبلــه احملكمــة وقــد انتهــى الوقــت احملــدد لنظــر الدعــوى واملقــرر‬\n                                                                                     ‫‪314‬‬\n\f      ‫الســاعة الثامنــة وعليــه مت شــطب الدعــوى للمــرة األولــى حســب‬\n      ‫التعليمــات وللبيــان جــرى حتريــره‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/20‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة مبكــة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 33550457‬وتاريــخ ‪1433/08/27‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331614840‬وتاريــخ ‪1433/08/27‬ه ـ‬\n      ‫حضــر ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪.........‬‬\n      ‫بصفتــه وكيــا عــن مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة مبكــة رقــم ‪ 33347178‬واملخولــة لــه حــق املرافعــة واملدافعــة‪..‬‬\n      ‫الــخ وحضــر حلضــوره ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫وبســؤال املدعــي وكالــة عــن دعــواه قــال إن املدعــى عليــه اســتأجر مــن‬\n      ‫موكلــي العقــار الواقــع يف وادي‪ ......‬ملــدة تبــدأ مــن ‪1427/8/1‬ه ـ إلــى‬\n      ‫‪1434/8/1‬ه ـ بأجــرة ســنوية مقدارهــا (‪ )10000‬عشــرة أالف ريــال‬\n      ‫مبوجــب العقــد الصــادر مــن مكتــب ‪ ...‬برقــم وتاريــخ ‪1427/4/15‬ه ـ‬\n      ‫وقــد تخلــف املدعــى عليــه عــن ســداد األجــرة مــن تاريــخ ‪1431/8/28‬ه ـ‬\n      ‫حتــى اآلن وملخالفتــه للعقــد أطلــب احلكــم علــى املدعــى عليــه بإخــاء‬\n      ‫العقــار هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكــره‬\n      ‫املدعــي وكالــة مــن أننــي اســتأجرت العقــار املذكــور املــدة املذكــورة‬\n      ‫باألجــرة كذلــك املذكــورة فصحيــح وقــد أقتــرض منــي مبلغــا ومقــداره‬\n      ‫(‪ )50000‬خمســون ألــف ريــال بعــد اســتالمه ألجــرة عــام ‪1430‬ه ـ‬\n      ‫وعندمــا طالبتــه بــه أعطانــي (‪)10000‬عشــرة أالف ريــال والباقــي‬\n      ‫ذكــر أنــه ســوف يحســمها مــن األجــرة أطلــب صــرف النظــر عــن دعــواه‬\n\n\n‫‪315‬‬\n\f‫وبعــرض ذلــك علــى املدعــي وكالــة قــال الصحيــح مــا ذكــرت وبســؤال‬\n‫املدعــى عليــه البينــة علــى مــا ذكــر قــال أطلــب مهلــة إلحضارهــا عليــه‬\n‫رفعــت اجللســة ويف جلســة أخــرى حضــر الطرفــان وبســؤال املدعــى عليــه‬\n‫عــن بينتــه التــي طلــب مهلــة إلحضارهــا قــال إن املدعــي هــو مــن الشــهود‬\n‫كمــا أنــه منــع بقيــة الشــهود مــن احلضــور ولكــن لــدي شــاهد يدعــى ‪...‬‬\n‫وهــو ال يســتطيع احلضــور اليــوم واطلــب مهلــة إلحضــاره هكــذا أجــاب‬\n‫فقــال املدعــي إننــي تضــررت كثيــرا مــن بقائــه يف ملكــي واطلــب‬\n‫احلكــم عليــه بإخــاء العقــار وعنــد وصــول القضيــة لهــذا احلــد رفعــت‬\n‫اجللســة مــع إعالمهمــا احلضــور يــوم غــد الســاعة الواحــد ظهــرا إجابــة‬\n‫لطلــب املدعــى عليــه إلحضــار بينتــه التــي ذكــر مــع إفهامــه بــأن هــذه‬\n                                      ‫هــي املهلــة األخيــرة ويف املوعــد احملــدد‬\n‫احلمــد هلل وحــده وبعــد فبعــد طباعــة الضبــط رفــض املدعــى عليــه‬\n‫التوقيــع عليــه فقــد جــرى إعــداد هــذه احملضــر بشــهادة كاتبــه وللبيــان‬\n‫جــرى حتريــره وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم حــرر يف ‪1434/5/21‬ه ـ‬\n‫حضــر الطرفــان فســألت املدعــى عليــه عــن بينتــه فقــال بعــد أن خرجــت‬\n‫مــن اجللســة اتصلــت بالشــاهد فــإذا بــه قــد انقلــب علــي فبينتــي قــد حــال‬\n‫خصمــي بينــي وبينهــا فأفهمتــه بــأن لــه ميــن املدعــي علــى نفــي دعــواه‬\n‫فقــال اطلــب ميينــه فجــرى عــرض ذلــك علــى املدعــي وكالــة فقــال أطلــب‬\n‫مهلــة لعــرض ذلــك علــى موكلــي وإحضــاره ألداء اليمــن ففهــم فأجبتــه‬\n‫لطلبــه وعليــه رفعــت اجللســة ويف جلســة أخــرى حضــر ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم وحضــر حلضــوره املدعــى عليــه وقــال‬\n‫املدعــي أصالــة ال مانــع لــدي مــن أداء اليمــن علــى نفــي دعــوى املدعــى‬\n\n\n                                                                                      ‫‪316‬‬\n\f      ‫عليــه فجــرى بيــان عاقبــة اليمــن الكاذبــة فحلــف بعــد إذنــي لــه قائــا‬\n      ‫واهلل العظيــم إننــي لــم أســتلم مــن املدعــى عليــه أجــرة عــام ‪1432‬ه ـ وعــام‬\n      ‫‪1433‬ه ـ وعــام ‪1434‬ه ـ ولــم أقتــرض منــه شــيئا واهلل العظيــم هكــذا‬\n      ‫حلــف فبذلــك جــرى اإلطــاع علــى العقــد الصــادر مــن مكتــب ‪ ...‬برقــم‬\n      ‫‪ 59‬وتاريــخ ‪1427/4/15‬ه ـ واملتضمــن املســتأجر املؤجــر العقــار الواقــع‬\n      ‫يف حــي ‪ ...‬شــارع ‪ ...‬الشــقة الواقعــة بالــدور األرضــي األجــرة عشــرة‬\n      ‫أالف كمــا تضمــن البنــد اخلامــس منــه « علــى املســتأجر دفــع األجــرة‬\n      ‫واســتهالك املــاء والكهربــاء يف أول كل شــهر أو يف أول كل ســنة إذا‬\n      ‫كان اإليجــار ســنويا « وبعرضــه علــى الطرفــن صادقــا عليــه فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وميــن املدعــي ومــا جــرى اإلطــاع عليــه‬\n      ‫ولقولــه تعالــي «يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود» ولقولــه صلــى اهلل‬\n      ‫عليــه وســلم « املســلمون علــى شــروطهم « ولقولــه صلــى اهلل عليــه وســلم‬\n      ‫«البينــة علــى املدعــي واليمــن علــى مــن أنكــر» وجلميــع مــا ذكــر بعاليــة‬\n      ‫فقــد حكمــت علــى املدعــى عليــه بإخــاء العقــار املوصــوف يف الدعــوى‬\n      ‫وتســليمه للمدعــي خاليــا مــن الشــواغل وبعرضــه علــى الطرفــن قــرر‬\n      ‫املدعــى عليــه عــدم القناعــة واســتعد بتقــدمي الئحــة إعتراضيــة فأفهمتــه‬\n      ‫بتعليمــات االســتئناف وأن عليــه تقــدمي الالئحــة االعتراضيــة خــال مــدة‬\n      ‫أقصاهــا ثالثــون يومــا مــن تاريــخ صــدور احلكــم فــإذا انتهــت املــدة ولــم‬\n      ‫يتقــدم بالئحتــه االعتراضيــة يســقط حقــه يف االســتئناف و يكــون‬\n      ‫احلكــم قــد اكتســب الصفــة القطعيــة ففهــم ذلــك وبــاهلل التوفيــق‬\n                                      ‫وصلــى اهلل عليــه وســلم حــرر يف‪1434/8/1‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد جــرى تســليم املدعــى عليــه نســخة احلكــم‬\n      ‫وأفهمتــه بــأن املــدة االعتراضيــة تبــدأ من ‪1434/8/1‬ه ـ وإذا انتهت املدة‬\n\n\n‫‪317‬‬\n\f‫االعتراضيــة مبــرور ثالثــن يومــا فيســط حقــه يف االعتــراض ويكتســب‬\n‫احلكــم الصفــة القطعيــة ففهــم ذلــك وللبيــان جــرى حتريــره وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                        ‫حــرر يف ‪ 1434/8/1‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1435/1/10‬ه ـ حضــر‬\n‫املدعــي ‪...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪...........‬‬\n‫وقــرر وهــو بكامــل أهليتــه املعتبــرة شــرعا اســتالمه للعقــار محــل النــزاع‬\n‫خاليــا مــن الشــواغل عليــه فقــد ثبــت لــدي هــذا اإلقــرار وبــه تكــون‬\n‫القضيــة منتهيــة وللبيــان جــرى حتريــره وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى الــه وصحبــه وســلم حــرر يف ‪1435/1/10‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‬\n‫‪ 331614840‬وتاريــخ ‪1434/9/15‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة الشــيخ القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل‬\n‫بعــدد ‪ 34285050‬وتاريــخ ‪1434/8/1‬هـ ـ واملتضمــن دعــوى‪ .....‬ضــد‪......‬‬\n                                          ‫واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                            ‫وصحبــه وســلم ‪،،،‬‬\n\n\n\n\n                                                                                    ‫‪318‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":313,"source_page_end":318,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a225adf97bc72d28e7d6448c7a6134de1f64cd3b5752850a2e0e66ee22797751","normalized_text_hash":"47a0a84a5284682240c8af9683a6e6d4ab211c5396dbe561c1cf8f52d1b32dbf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p313-34285050"},{"id":"723c338a-aeca-5d32-bbcd-0f22863f44c1","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -امتناع املدعى عليه عن دفع األجرة وجتديد العقد -طلب إخاء العقار -شهادة شاهدين عدل -وجوب الوفاء بالعقود -تغيب املدعى عليه واستتاره عن األنظار يضعف جانبه -حكم بإخاء العقار -الغائب على حجته متى حضر .","document_number":"34301207","case_number":"34224794","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/21","year":"1434","subject":"إجارة -امتناع املدعى عليه عن دفع األجرة وجتديد العقد -طلب إخاء العقار -شهادة شاهدين عدل -وجوب الوفاء بالعقود -تغيب املدعى عليه واستتاره عن األنظار يضعف جانبه -حكم بإخاء العقار -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/21 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34301207 :‬‬\n                         ‫َر ْق ُم الدعوى‪34224794 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34351258‬تاريخه‪1434/11/5 :‬هـ‬\n\n\n      ‫إجــارة‪ -‬امتنــاع املدعــى عليــه عــن دفــع األجــرة وجتديــد العقــد‪ -‬طلــب‬\n      ‫إخــاء العقــار‪ -‬شــهادة شــاهدين عــدل‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬تغيــب‬\n      ‫املدعــى عليــه واســتتاره عــن األنظــار يضعــف جانبــه ‪ -‬حكــم بإخــاء‬\n                                   ‫العقــار ‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n                            ‫آم ُنوا َأوْفُ وا ِبا ْل ُع ُقودِ}‬ ‫‪ .1‬قوله تعالى { َيا َأ ُّي َها ا َّلذِ َ‬\n                                                            ‫ين َ‬\n                          ‫‪ .2‬قوله صلى اهلل عليه وسلم (( ال ضرر وال ضرار ))‬\n      ‫‪ .3‬مــا قــرره جمــع مــن أهــل العلــم مــن جــواز احلكــم علــى الغائب املســتتر‬\n                                                                                            ‫عــن األنظار‬\n\n\n\n\n      ‫ادعــى املدعــي بالوكالــة ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم‬\n      ‫والــذي تعــذر إبالغــه بالطــرق الرســمية ولــذا تقــرر ســماع الدعــوى غيابي ًا‬\n      ‫ـاء‬\n        ‫ومضمــون الدعــوى أن املدعــى عليــه اســتأجر كامــل الــدار أرضـ ًا وبنـ ً‬\n      ‫املوصوفــة يف ضبــط القضيــة مــن موكلــه املدعــي مــن قرابــة العشــرين‬\n      ‫عامـ ًا و لكنــه يف اخلمــس الســنوات األخيــرة لــم يســلم شــيئ ًا مــن األجــرة‬\n      ‫ويرفــض جتديــد العقــد وطلــب املدعــي وكالــة احلكــم علــى املدعــى‬\n      ‫عليــه بإخــاء العقــار‪ ،‬احضــر املدعــي وكالــة بينــة موصلــة وهمــا‬\n\n‫‪319‬‬\n\f‫شــاهدان مت تعديلهمــا شــرع ًا شــهدا بصحــة الدعــوى‪ ،‬مت االطــاع علــى‬\n‫صــك ملكيــة العقــار فوجــده ناظــر القضيــة يتضمــن مــا ذكــره املدعــي‬\n‫آم ُنــوا َأ ْو ُفــوا‬\n                    ‫{يــا َأ ُّي َهــا ا َلّذِ يـ َـن َ‬\n                                                     ‫ـاء علــى مــا تقــدم ولقولــه تعالــى َ‬\n                                                                                          ‫يف دعــواه‪ ،‬بنـ ً‬\n‫ِبا ْل ُع ُقــو ِد } و قولــه صلــى اهلل عليــه وســلم (( ال ضــرر وال ضــرار)) ولقــول‬\n‫جمــع مــن أهــل العلــم مــن جــواز احلكــم علــى الغائب املســتتر عــن األنظار‬\n‫ولكــون تغيــب املدعــى عليــه واســتتاره عــن األنظــار يضعــف جانبــه فقــد‬\n‫صــدر احلكــم علــى املدعــى عليــه بإخــاء العقــار محــل الدعــوى والغائــب‬\n‫علــى حجتــه إذا حضــر‪ ،‬مت إرســال نســخة مــن الصــك للمدعــى عليــه‪،‬‬\n‫صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة باملوافقــة علــى‬\n                                                           ‫احلكــم والغائــب علــى حجتــه إذا حضــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 34224794‬وتاريــخ‬\n‫‪1434/05/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341192381‬وتاريــخ‬\n‫‪1434/05/15‬ه ـ ففــي يــوم األحــد املوافق‪1434/08/07‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 09 : 30‬وفيها حضر ‪ ...........‬ســعودي اجلنســية مبوجب‬\n‫الســجل املدنــي رقــم‪ ...........‬بصفتــه وكيــا عــن ‪...........‬ســعودية اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم‪ ...........‬مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة العــدل الثانيــة مبكــة برقــم ‪ .........‬يف ‪1432/04/08‬ه ـ املخولــة‬\n‫لــه فيهــا حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار ولــم يحضــر‬\n‫املدعــى عليــه وقــد وردتنــا إفــادة محضــر اخلصــوم رقــم ‪331676976‬‬\n                                                                                                              ‫‪320‬‬\n\f      ‫يف ‪1433/09/10‬ه ـ للجلســة املؤرخــة يف ‪1433/10/25‬ه ـ املتضمنــة (‬\n      ‫مت الوصــول إلــى العنــوان ولــم جنــد مــن يــرد علينــا ألكثــر مــن مــرة )‬\n      ‫كمــا ســبق وأن جــرت الكتابــة لســعادة مديــر شــعبة أمــن احملاكــم‬\n      ‫الشــرعية برقــم ‪ 34542207‬يف ‪1434/03/02‬ه ـ للبحــث عــن املدعــى‬\n      ‫عليــه وإحضــاره بالقــوة اجلبريــة مخفــورا يف أقــرب وقــت فوردنــا خطابهــم‬\n      ‫رقــم ‪.........‬يف ‪1434/05/13‬ه ـ املتضمــن مانصــه ( مت البحــث والتحــري‬\n      ‫عــن املذكــور مــن قبــل أفــراد وحــدة البحــث واتضــح أنــه غيــر متواجــد‬\n      ‫مبنزلــه ومت وضــع اخلفــارة الســرية علــى منزلــه طيلــة الفتــرة املاضيــة‬\n      ‫ولــم يشــاهد املذكــور ) عليــه فقــد قــررت الســير يف نظــر الدعــوى‬\n      ‫غيابيــا وبســؤال املدعــي وكالــة عــن دعــواه ادعــى قائــا إن املدعــى‬\n      ‫عليــه اســتأجر كامــل الــدار أرضــا وبنــاء الكائنــة ب‪ .........‬بحــارة‬\n      ‫‪.........‬املشــتملة علــى ثالثــة أدوار كل دور غرفتــن اململــوك ملوكلتــي‬\n      ‫مبوجــب الصــك الصــادر مــن كتابــة العــدل األولــى مبكــة رقــم ‪.........‬‬\n      ‫يف ‪1394/02/03‬ه ـ حيــث إن املدعــى عليــه مســتأجر لهــذا العقــار مــن‬\n      ‫قرابــة عشــرين عامــا إال أنــه يف اخلمــس ســنوات األخيــرة لــم يدفــع شــيئا‬\n      ‫مــن األجــرة ويرفــض جتديــد العقــد أطلــب احلكــم عليــه بإخــاء العقــار‬\n      ‫املذكــور وبســؤاله عــن بينتــه أحضــر للشــهادة كل مــن ‪...........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...........‬و‪ ...........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم‪ ...........‬وبطلــب الشــهادة منهمــا شــهد كل‬\n      ‫واحــد مبفــرده قائــا أشــهد بــاهلل العظيــم أن املدعــى عليــه الغائــب‬\n      ‫مســتأجر للعقــار اململــوك للمدعيــة أصالــة املذكــور يف الدعــوى وذلــك‬\n      ‫طيلــة عشــرين عامــا ولــم يدفــع أجــرة اخلمــس الســنوات األخيــرة ويرفــض‬\n      ‫املواجهــة أو جتديــد عقــد اإليجــار هكــذا شــهدا ثــم جــرى تزكيــة‬\n\n\n‫‪321‬‬\n\f‫الشــاهدين املذكوريــن مــن قبــل كل مــن ‪...........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم‪ ...........‬و‪ ...........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم‪ ...........‬وبســؤال املدعــي هــل لديــه مزيــد بينــة قــال ال‬\n‫وبطلــب صــك امللكيــة منــه أبــرز الصــك رقــم ‪.........‬يف ‪1394/02/03‬ه ـ‬\n‫الصــادر مــن كتابــة العــدل األولــى مبكــة وباالطــاع عليــه وجدتــه‬\n‫يتضمــن مــا ذكــره املدعــي وكالــة يف دعــواه فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة والبينــة ولقولــه تعالــى ( يــا أيهــا الذيــن آمنــوا أوفــوا‬\n‫بالعقــود ) وقولــه صلــى اهلل عليــه وســلم ( ال ضــرر وال ضــرار) وملــا‬\n‫ذكــره جمــع مــن احملققــن مــن جــواز احلكــم علــى الغائــب املســتتر عــن‬\n‫األنظــار ولكــون تغيــب املدعــى عليــه واســتتاره عــن األنظــار يضعــف‬\n‫جانبــه جلميــع مــا ســبق حكمــت علــى املدعــى عليــه بإخــاء العقــار‬\n‫محــل الدعــوى والغائــب علــى حجتــه متــى مــا حضــر وبعــرض احلكــم‬\n‫علــى املدعــي وكالــة قنــع بــه فأمــرت بإخــراج صــك باحلكــم وإرســال‬\n‫نســخة منــه للمدعــى عليــه لتبليغــه بــه وإفهامــه بــأن عليــه تقــدمي الئحتــه‬\n‫االعتراضيــة خــال ثالثــن يومــا تبــدأ مــن تاريــخ االســتالم وإال فــإن‬\n‫حقــه يف طلــب االســتئناف يســقط ويكتســب احلكــم القطعيــة وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                      ‫حــرر يف ‪1434/08/07‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/11/23‬ه ـ‬\n‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف برقــم‬\n‫‪ 341192381‬يف ‪1434/11/18‬ه ـ مرفقــا بهــا القــرار رقــم ‪34351258‬‬\n‫يف ‪1434/11/5‬ه ـ ونــص احلاجــة منــه (وبدراســة احلكــم وصورة ضبطه‬\n‫تقــرر املوافقــة علــى احلكــم والغائــب علــى حجتــه متــى حضــر واهلل‬\n\n\n                                                                                         ‫‪322‬‬\n\f      ‫املوفــق قاضــي اســتئناف توقيعــه وختمــه قاضــي اســتئناف توقيعه وختمه‬\n      ‫رئيــس الدائــرة توقيعــه وختمــه ) لــذا جــرى حتريــره حتــى ال يخفــى وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                ‫يف ‪1434/11/23‬ه ـ‬\n      ‫احلمد هلل وحده ‪ ،‬والصالة والســام على رســول اهلل وبعد ‪ :‬ـ فقد جرى‬\n      ‫م ّنــا نحــن قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــا ُع علــى هــذا احلكــم‬\n      ‫الصــادر مــن فضيلــة الشــيخ‪ ...........‬القاضــي يف احملكمــة العامــة مبكة‬\n      ‫املكرمــة املســجل بعــدد ‪ 34301207‬وتاريــخ ‪1434/8/21‬ه ـ املتضمــن‬\n      ‫دعــوى‪ ...........‬ضــد احملكــوم في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة‬\n      ‫احلكــم وص ــورة ضبط ــه تقــرر املوافقــة علــى احلكــم و الغائــب علــى‬\n      ‫حجتــه متــى حضــر ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصل ــى اهلل عل ــى نبينــا محمــد‬\n                                                          ‫وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪323‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":319,"source_page_end":323,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ab7e0bc8cd315e9cba9c8ad43275cb42295198fa18b9b7a35d46b1ff3a5fae74","normalized_text_hash":"c49ba1ad92e5ddd390312c4816f85292ded3b09f4a3cb8fc5ef9855f9bd941ae","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p319-34301207"},{"id":"a2207105-7583-5828-b18b-ad070f4f9f33","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار لتغير املالك -أسبقية شراء عقار -قرر املدعى عليه عدم وجود بينه -طلب إدخال من يصح اختصامه «بائع العقار» -عدم قبول مين املتداخل -احلكم بإخاء العقار قوله صلى اهلل عليه وسلم « البينة على املدعى واليمن على من","document_number":"34304769","case_number":"33599008","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/24","year":"1434","subject":"إجارة -إخاء عقار لتغير املالك -أسبقية شراء عقار -قرر املدعى عليه عدم وجود بينه -طلب إدخال من يصح اختصامه «بائع العقار» -عدم قبول مين املتداخل -احلكم بإخاء العقار قوله صلى اهلل عليه وسلم « البينة على املدعى واليمن على من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/24 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34304769 :‬‬\n                    ‫َر ْق ُم الدعوى‪33599008 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34373352‬تاريخه‪1434/11/27 :‬هـ‬\n\n\n‫إجــارة ‪ -‬إخــاء عقــار لتغيــر املالــك ‪ -‬أســبقية شــراء عقــار ‪ -‬قــرر املدعى‬\n‫عليــه عــدم وجــود بينــه ‪ -‬طلــب إدخــال مــن يصــح اختصامــه «بائــع‬\n         ‫العقــار» ‪ -‬عــدم قبــول ميــن املتداخــل ‪ -‬احلكــم بإخــاء العقــار‬\n\n\n\n\n‫قولــه صلــى اهلل عليــه وســلم « البينــة علــى املدعــى واليمــن علــى مــن‬\n                                                                      ‫انكــر»‬\n\n\n\n\n‫دعــوى املدعــى ضــد املدعــى عليــه ومضمــون الدعــوى انــه اشــتري بيتــا‬\n‫شــعبي ًا مت وصفــه مــن مالكــه الســابق واملدعــى عليــة مســتأجر لهــذا‬\n‫البيــت مــن مالكــه الســابق وانــه طلــب مــن املدعــى عليــة إخــاء العقــار‬\n‫فرفــض وطلــب املدعــى إلــزام املدعــى عليــه بإخــاء العقــار فــور ًا ‪ ،‬أجــاب‬\n‫املدعــى عليــه باملصادقــة علــى الدعــوى ودفــع بأنــه اشــتري املنــزل محــل‬\n‫النــزاع مــن مالكــه الســابق قبــل شــراء املدعــى لــه‪ ،‬طلــب املدعــى عليــة‬\n‫إدخــال املالــك الســابق ‪ ،‬طلــب ناظــر القضيــة مــن املدعــى عليــه البينــة‬\n‫علــى أســبقية الشــراء ‪ ،‬حضــر املالــك الســابق وجــري إفهــام املدعى عليه‬\n‫بــأن لــه ميــن املالــك الســابق فرفــض‪ ،‬اســتعد املتداخــل بــأداء اليمــن‪،‬‬\n‫ثبــت لــدى ناظــر القضيــة صحــة الدعــوى وحكــم علــى املدعــى عليــه‬\n                                                                                    ‫‪324‬‬\n\f      ‫إخــاء العقــار ‪ ،‬وافهمــه بــأن لــه ميــن املتداخــل متــى أراد ‪ ،‬قــرر املدعــى‬\n      ‫عليــه عــدم القناعــة ‪ ،‬صــدر قــرار محكمــة االســتئناف مبنطقــة تبــوك‬\n                                                           ‫باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بتبــوك‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بتبــوك برقــم ‪ 33599008‬وتاريــخ ‪ 1433/10/14‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 331797051‬وتاريــخ ‪ 1433/10/14‬ه ـ ففــي يــوم الســبت‬\n      ‫املوافق‪1433/12/25‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا‬\n      ‫حضــر ‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪،..........‬‬\n      ‫وادعــى علــى احلاضــر معــه ‪........... ،‬ســوري اجلنســية مبوجــب رخصــة‬\n      ‫ـتأجر‬\n      ‫إن هــذا احلاضــر معــي مسـ ٌ‬      ‫ا يف دعــواه ‪َّ :‬‬ ‫اإلقامــة رقــم‪ ، ...........‬قائـ ً‬\n      ‫للبيــت الشــعبي الواقــع يف حــي الفيصليــة بتبــوك مــن مالكــه الســابق ‪،‬‬\n      ‫وسـ ِّـجلَ صكــه رقــم‬  ‫ـتريت أنــا هــذا العقــار يف شــهر ربيــع األول ‪ُ ،‬‬\n                                                                                ‫ثــم اشـ ُ‬\n      ‫‪ 3/72‬يف ‪1433/7/21‬ه ـ الصــادر مــن كتابــة العــدل األولــى بتبــوك‬\n      ‫باســمي بتاريــخ ‪1433/9/9‬ه ـ وطلبـ ُـت مــن املدعــى عليــه أن ُيخلــي العقار‬\n      ‫فرفــض ؛ لــذا أطلــب إلزامــه باإلخــاء فــور ًا ‪ ،‬هــذه دعــواي ‪ .‬وبعرضهــا‬\n      ‫ـتأجر‬\n       ‫ا ‪ :‬مــا ذكــره املدعــي مــن أ َّننــي مسـ ٌ‬  ‫علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫لهــذا البيــت مــن مالكــه الســابق فهــذا صحيــح ‪ ،‬واحلاصــل أ ِّنــي طلبـ ُـت‬\n      ‫مــن املالــك الســابق أن يبيعنــي هــذا البيــت محــل النــزاع فوعدنــي بذلــك‪،‬‬\n      ‫ـرت ‪ ،‬وعندمــا علمـ ُـت أ ّنــه عــرض‬ ‫ا فانتظـ ُ‬  ‫ولكــن قــال لــي انتظــر قلي ـ ً‬\n      ‫ـرت عنــده فطلبـ ُـت منــه أن يبيعنــي إيــاه فوعدنــي بذلــك‬ ‫البيــت للبيــع حضـ ُ‬\n‫‪325‬‬\n\f‫وقــال اصبــر‪ ،‬ثــم بعدهــا بفتــرة علمـ ُـت أ ّنــه باعــه فكلمـ ُـت وطلبـ ُـت منــه‬\n‫ـأن‬\n  ‫أن يبيعنــي هــذا البيــت فاســتعد بذلــك ‪ ،‬ثــم بعدهــا بفتــرة تفاجــأت بـ َّ‬\n‫املدعــي قــد اشــتراه وســجل صكــه باســمه وأنــا أولــى مــن املدعــي بهــذا‬\n‫البيــت ألنــي مســتأجر قــدمي وقمـ ُـت بإصالحــات كثيــرة يف هــذا البيــت‬\n‫ـلمت للمكتــب‬        ‫وأفهمـ ُـت املالكــن الســابقني باالســتعداد للشــراء وسـ ُ‬\n‫قيمــة البيــت وطلبــوا م ِّنــي أن أحضــر عندهــم مــن الغــد مــن أجــل كتابــة‬\n‫العقــد ؛ علمــا أنــي أريــد شــراء البيــت وتســجيله باســم ابنتــي التــي حتمــل‬\n‫اجلنســية الســعودية لــذا لــن ُأخلــي هــذا البيــت ‪ .‬هكــذا قــرر‪ .‬وبعــرض‬\n‫ـرت ‪ ،‬واملدعــى عليــه َي ِعـ ُـد‬  ‫ذلــك علــى املدعــي قــال ‪ :‬الصحيــح مــا ذكـ ُ‬\n‫ـألت‬‫املالــك بالشــراء لكــن لــم يحصــل بينهمــا بيــع ‪ ،‬هــذه إجابتــي ‪ .‬فسـ ُ‬\n‫املدعــى عليــه هــل حصــل بينــك وبــن املالــك بيــع ؟ فقــال ‪ :‬نعــم حصــل‬\n‫بينــي وبينــه بيــع واتفقنــا شــفوي ًا مببلــغ قــدره مائتــان وثالثــون ألــف ريــال‬\n‫البينــة علــى ذلــك فوعــد بهــا ‪ .‬ويف جلسـ ٍة أخــرى‬     ‫‪ .‬هكــذا قــرر‪ .‬فســأل ُته َّ‬\n‫البينــة التــي وعــد بهــا ؟ قــال‬  ‫حضــر الطرفــان ‪ ،‬وبســؤال املدعــى عليــه ِّ‬\n‫ـدي ِّبينــة ‪ ،‬وأنــا طلبـ ُـت املالــك الســابق للحضــور هــذه اجللســة‬    ‫‪ :‬ليــس لـ َّ‬\n‫أن وعدنــي‬      ‫فرفــض ‪ ،‬وأطلـ ُـب حضــوره وإن أنكــر فأطلـ ُـب ميينــه ‪ ،‬علمـ ًا َّ‬\n‫ببيــع هــذا البيــت لــي لكــن باعــه‪ .‬هكــذا قــرر ‪ .‬ويف جلســة أخــرى حضر‬\n‫البينــة التــي وعــد بهــا قــال ‪ :‬إن‬     ‫الطرفــان ‪ ،‬وبســؤال املدعــى عليــه عــن ِّ‬\n‫بينتــي هــو إن حضــر صاحــب البيــت وأنكــر فيحلــف وإن حلــف ‪ ،‬فلــن‬\n‫أخــرج ‪ ،‬ألنــي صــادق يف كالمــي ‪ ،‬وأنــا لــم أبحــث عــن ألنــي اكتفيــت‬\n‫بطلــب احملكمــة لــه وليــس بينــي وبينــه أي تواصل و ُأقــدم لكم مذكر ًة‬\n‫ـدت‬  ‫فيهــا إضافــة إلجابتــي الســابقة ‪ .‬هكــذا قــرر‪ .‬وباإلطــاع عليهــا وجـ ُ‬\n‫أن بعضهــا قــد ذكــره يف إجابتــه ســابق ًا والبعــض اآلخــر ليــس لــه عالقــة‬       ‫َّ‬\n\n                                                                                            ‫‪326‬‬\n\f      ‫ـاء علــى املــادة‬\n                      ‫بهــذا القضيــة ؛ وعليــه ُرفعــت اجللســة إلدخــال البائــع بنـ ً‬\n      ‫(‪ )76‬مــن نظــام املرافعــات ‪ .‬ويف جلســة أخــرى حضــر الطرفــان ‪ ،‬وللعلــم‬\n      ‫فإننــا لــم نتمكــن مــن فتــح اجللســة يف موعدهــا احملــدد ســلف ًا لكونــي‬\n      ‫يف إجــازة اضطراريــة ‪ .‬وحضــر يف هــذه اجللســة مــن بــاع علــى املدعــي‬\n      ‫وأشــار املدعــى عليــه أنــه حصــل تفــاوض بينهمــا علــى البيــع وهــو ســعودي‬\n      ‫ـدت هــذا‬‫بالهويــة الوطنيــة رقــم ‪ ،...‬وبســؤاله عمــا لديــه ؟ قــال‪ :‬إنــي وجـ ُ‬\n      ‫البيــت محــل النــزاع معروضـ ًا للبيــع يف أحــد املكاتب العقارية فاشــتري ُته‬\n      ‫مــن مالكــه وأخبرنــي أن الــذي يســكن يف هــذا البيــت لــه رغبــة بــه‬\n      ‫ـتريت هــذا البيــت منــه‬\n                             ‫وهــو املدعــى عليــه فقلـ ُـت خيــر إن شــاء اهلل فاشـ ُ‬\n      ‫بأربعمائــة ألــف ريــال ثــم بعدهــا ذهبـ ُـت بنفســي للمدعــى عليــه يف هــذا‬\n      ‫البيــت وعرضـ ُـت عليــه البيــت وكان هــذا البيــت مقــام علــى أرض قــد‬\n      ‫قســمت إلــى جزئــن جــزء أقيــم عليــه هــذا البيــت محــل النــزاع واجلــزء‬\n      ‫اآلخــر أقيــم عليــه بيــت آخــر ‪ ،‬واحلاصــل أنــي عرضـ ُـت علــى املدعــى عليــه‬\n      ‫هــذا البيــت محــل النــزاع وقلــت لــه إن رأس مالــي فيــه مائتــي ألــف ريــال‬\n      ‫فبكــم تريــد أن تشــتريه فقــال إنــه ال يســاوي هــذه القيمــة ووضــح لــي أنه‬\n      ‫ليــس لــه رغبــة يف شــرائه ثــم عرض ُتــه يف مكتــب العقــاري وبعدها حضر‬\n      ‫فذهبت‬\n       ‫ُ‬         ‫املدعــي ورغــب يف شــراء البيــت مببلــغ مائتــن وأربعــن ألف ريــال‬\n      ‫ـتر مبائتــن وأربعــن ألــف‬   ‫للمدعــى عليــه وأخبرتــه بأنــه تقــدم للبيــت مشـ ٍ‬\n      ‫ريــال فقــال إن هــذا البيــت ال يســاوي هــذه القيمــة وأعــرض عنــه فطلبـ ُـت‬\n      ‫ـرت أنــا‬\n             ‫منــه أن يســمح للمشــتري مبعاينــة البيــت فوافــق علــى ذلــك وحضـ ُ‬\n      ‫واملدعــي ودخلنــا عنــده يف هــذا البيــت وقــام املدعــى عليــه بإطالعنــا علــى‬\n      ‫بعــض أجــزاء البيــت وتفاصيلــه ثــم بعدهــا كتبـ ُـت عقــد ًا مــع املدعــي يف‬\n      ‫مكتــب ‪ ...‬وشــهدنا علــى ذلــك وكان ذلــك بعــد املغــرب وال أذكــر أي‬\n\n\n‫‪327‬‬\n\f‫ـتلمت مــن املدعــي العربــون وقــدره‬ ‫يــوم وال التاريــخ ثــم بعــد العشــاء اسـ ُ‬\n‫ثمانــون ألــف ريــال تقريب ـ ًا ثــم بعدهــا بيــوم أو يومــن اتصــل بــي موظــف‬\n‫يف مكتــب وكنـ ُـت قــد عرضــت البيــت قبــل البيــع عنــد عــدة مكاتــب‬\n‫وقــال لــي املوظــف بــأن املدعــى عليــه يرغــب يف شــراء البيــت فقلــت إنــي‬\n‫وقعــت عقــد ًا مــع املدعــي وإذا اســتجد أمــر اتصلــت بكــم ثــم أكمــل‬\n‫لــي املدعــي بقيــة املبلــغ وأنهيــت إجــراءات فــرز الصــك باجلزأيــن اللذيــن‬\n‫ذكرتهمــا لــدى كتابــة العــدل ثــم أفرغـ ُـت للمدعــي يف ‪1433/9/9‬ه ـ‬\n‫علم ـ ًا أنــي عندمــا كنـ ُـت أشــاهد البيــت ومعــي املدعــي واملدعــى عليــه‬\n‫كان املدعــى عليــه يبــارك للمدعــي البيــع هــذا مــا لــدي مــن إفــادة ‪.‬‬\n‫ا ‪ :‬مــا ذكــره يف إفادتــه بعضــه‬   ‫وبعرضهــا علــى املدعــى عليــه أجــاب قائـ ً‬\n‫صحيــح وبعضــه غيــر صحيــح والصــواب أن عندمــا أخبرنــي أنــه اشــترى‬\n‫هــذا البيــت والــذي بجــواره مــن مالكــه بأربعمائــة ألــف ريــال تفاوضـ ُـت‬\n‫معــه علــى أن أشــتري هــذا البيــت محــل النــزاع مبائتــن وســبعة وعشــرين‬\n‫ألــف ريــال فوافــق علــى ذلــك ثــم يف صبــاح الغد وكان ذلك يف شــهر ربيع‬\n‫ـرت معــي كامــل املبلــغ ثــم حضــر عنــدي‬    ‫األول مــن عــام ‪1433‬ه ـ أحضـ ُ‬\n‫واملدعــي وملــا ســألته عــن ســبب مجــيء املدعــي معــه قــال إن هــذا يريــد‬\n‫شــراء البيــت فقلــت لــه ألــم نتفــق باألمــس علــى مائتــن وســبعة وعشــرين‬\n‫ألــف ريــال وأنــا مســتعد بتســليمها لــك اآلن فقــال لــي انظــر يف املوضــوع‬\n‫وطلــب مهلــة للتفكيــر فذهبــا ولــم يحصــل أنــي أطلعتهــم علــى املنــزل أو‬\n‫أدخلتهــم فيــه ثــم علمــت فيمــا بعــد أنهمــا تبايعــا علــى هــذا املبلــغ الــذي‬\n‫اشــترى بــه املدعــي ‪ ،‬هــذه إجابتــي‪ .‬وبعرضهــا علــى قــال ‪ :‬الصحيــح مــا‬\n‫ـرت ولــم يحصــل أن اتفقــت مــع املدعــى عليــه علــى أي شــيء يتعلــق‬      ‫ذكـ ُ‬\n‫بالبيــع أو الشــراء بــل إنــي ملــا أخبرتــه بأنــه ِســيم منــي مبائتــن وأربعــن‬\n\n\n                                                                                        ‫‪328‬‬\n\f      ‫ألــف ريــال زهدنــي يف البيــت وقــال إنــه ال يســاوي أي شــيء وأوضــح لــي‬\n      ‫رغبتــه بعــدم الشــراء هــذه إجابتــي ‪ .‬فســألت املدعــى عليــه البينــة علــى‬\n      ‫مــا ذكــر فقــال ‪ :‬ليــس لــدي بينــة ولــم يكــن معنــا أحــد‪ .‬هكــذا قــرر‪.‬‬\n      ‫ـتعد بــأداء اليمــن علــى نفــي مــا ذكــره املدعــى‬    ‫فســألت املتداخــل أمسـ ٌ‬\n      ‫عليــه ؟ فقــال‪ :‬نعــم ‪ ،‬فعرضتهــا علــى املدعــى عليــه فقــال ‪ :‬ال أقبــل‬\n      ‫ـرت عــن ســريان مفعــول‬    ‫بيمينــه ‪ .‬هكــذا قــرر‪ .‬وقــد ســبق ألن استفسـ ُ‬\n      ‫صــك العقــار محــل النــزاع والــذي يحمل الرقــم ‪ 3/72‬يف ‪1433/7/21‬هـ‬\n      ‫بالنمــوذج املعــد لذلــك برقــم ‪ 34790713‬يف ‪1434/4/1‬ه ـ فوردنــي مــن‬\n      ‫فضيلــة رئيــس كتابــة العــدل اجلــواب بــذات الرقــم يف ‪1433/4/17‬ه ـ‬\n      ‫واملتضمــن أن الصــك ســاري املفعــول وليــس علــى ســجله أي شــروحات‬\n      ‫تخــل بصالحيتــه ومســجل باســم ؛ فســألت املدعــي عــن العقــد فقــال‬\n      ‫ليــس معــي اآلن وبنــاء علــى التعاقــد الــذي بينــي وبــن املدعــى عليــه نقــل‬\n      ‫ـاء علــى‬\n              ‫العقــار باســمي هكــذا قــرر ‪ ،‬ومســتعد بإرفاقــه باملعاملــة‪ .‬فبنـ ً‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وملــا جــاء يف إفــادة املتداخــل وألن املدعــى‬\n      ‫عليــه قــرر يف إجابتــه ادعائــه بأنــه اشــترى هــذا البيــت محــل النــزاع مــن‬\n      ‫مالكــه قبــل أن يبيعــه علــى املدعــي مببلــغ مائتــن وســبعة وعشــرين ألــف‬\n      ‫ريــال وأنكــر ذلــك املتداخــل (‪ ).....‬وقــرر املدعــى عليــه عــدم البينــة التــي‬\n      ‫تثبــت صحــة مــا ادعــاه ورفــض ميــن املتداخــل بعــد أن اســتعد بهــا ولقولــه‬\n      ‫عليــه الصــاة والســام ‪ (:‬البينــة علــى املدعــي واليمــن علــى مــن أنكــر)‬\n      ‫حســنه البيهقــي فقــد ثبــت لــدي صحــة دعــوى املدعــي وحكمـ ُـت علــى‬\n      ‫املدعــى عليــه بــأن يخلــي العقــار محــل النــزاع حــا ًال وأفهمتــه بــأن لــه ميــن‬\n      ‫املتداخــل متــى طلبهــا وبعرضــه عليــه لــم يقنــع بــه وطلــب بعــث احلكــم‬\n      ‫إلــى محكمــة االســتئناف لتدقيقــه ووعــد بتقــدمي الئحــة اعتراضيــة‬\n\n\n‫‪329‬‬\n\f‫و ُأفهــم باملراجعــة يف يــوم األربعــاء ‪1434/8/24‬ه ـ ال ســتالم صــورة مــن‬\n‫صــك احلكــم و ُأفهــم بــأن لــه ثالثــن يوم ـ ًا لــه أن يقــدم اعتراضــه علــى‬\n‫وختمــت‬  ‫احلكــم خاللهــا ويبــدأ حســابها مــن التاريــخ املشــار إليــه آنف ـ ًا ُ‬\n‫هــذه اجللســة الســاعة العاشــرة والنصــف ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ،‬ففــي يــوم اخلميــس املوافــق‪ 1435/01/04‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثامنــة ‪ ،‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف بتبــوك ‪ ،‬بخطــاب فضيلــة رئيســها رقــم ‪ 331797051‬يف‬\n‫‪1434/12/16‬ه ـ وبرفقــه القــرار رقــم ‪ 34373352‬يف ‪1434/11/27‬هـ‬\n‫‪ ،‬املتضمــن املصادقــة علــى احلكــم مــع التنبيــه إلــى إفهــام املدعــى عليــه‬\n‫ـأن لــه حــق إقامــة الدعــوى يف املطالبــة بقيمــة إصــاح البيــت إنْ رغِ ـ َـب‬‫بـ ّ‬\n‫يف ذلــك ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1435/01/04‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل أمــا بعــد‪ :‬فقــد اطلعن ــا‬\n‫نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف محكمــة االســتئناف مبنطقــة‬\n‫تبــوك علــى املعاملــة الــواردة مــن احملكمــة العامــة بتبــوك برقــم‬\n‫‪ 331797051‬وتاريــخ ‪1434/9/23‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة الشــيخ وفقــه اهلل برقــم ‪ 34304769‬وتاريــخ ‪1434/8/24‬ه ـ‬\n‫اخلــاص بدعوى‪...........‬ضــد‪ ...........‬وبدراســة الصــك وصــورة ضبطــه‬\n‫واملذكــرة االعتراضيــة املقدمــة مــن املدعــى عليــه وأوراق املعاملــة جــرت‬\n‫املصادقــة علــى احلكــم مــع التنبيــه إلــى إفهــام املدعــي عليــه بــأن لــه‬\n‫حــق إقامــة الدعــوى يف املطالبــة بقيمــة إصــاح البيــت إن رغــب يف ذلــك‬\n   ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                        ‫‪330‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":324,"source_page_end":330,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"032274dcc282bd61436277a050c29fff55340e1734079c000a8506e455fbd4da","normalized_text_hash":"1fcf04b1f0e967a00246f3219eb399754351df7fb473242a7936569c5bb68634","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p324-34304769"},{"id":"ed6b662c-54da-5723-83a1-fadf0c9e9f46","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -فسخ عقد اإليجار للغياب وعدم سداد األجرة - البينة عقد اإليجار و املغادرة النهائية -احلكم بفسخ عقد اإليجار وفتح العن -حفظ محتويات العن يف بيت املال -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال .","document_number":"34340276","case_number":"34371709","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/26","year":"1434","subject":"عقد -إجارة -فسخ عقد اإليجار للغياب وعدم سداد األجرة - البينة عقد اإليجار و املغادرة النهائية -احلكم بفسخ عقد اإليجار وفتح العن -حفظ محتويات العن يف بيت املال -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/10/26 :‬هـ‬\n                  ‫ُ‬                 ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪34340276 :‬‬\n                     ‫َر ْق ُم الدعوى‪34371709 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34360441‬تاريخه‪1434/11/13:‬هـ‬\n\n\n  ‫عقــد ‪ -‬إجــارة ‪ -‬فســخ عقــد اإليجــار للغيــاب وعــدم ســداد األجــرة ‪-‬‬\n  ‫البينــة عقــد اإليجــار و املغــادرة النهائيــة ‪ -‬احلكــم بفســخ عقــد اإليجــار‬\n  ‫وفتــح العــن ‪ -‬حفــظ محتويــات العــن يف بيــت املــال ‪ -‬بيــع مــا يخشــى‬\n                                            ‫تلفــه وإيــداع ثمنــه يف بيــت املــال ‪.‬‬\n\n\n\n\n             ‫‪ .1‬قاعدة فقهية‪ :‬األصل يف األمور احلادثة (العارضة) العدم‪.‬‬\n                               ‫‪ .2‬املادة ‪ 138‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه األجنبــي الغائــب عــن مجلــس‬\n  ‫احلكــم بأنــه اســتأجر مــن موكلتــه الشــقة رقــم ‪ ...‬مــن عمارتهــا‬\n  ‫الواقعــة بحــي ‪ ...‬بأجــرة ســنوية قدرهــا عشــرون ألــف ريــال علــى دفعتــن‬\n  ‫اعتبــارا مــن ‪1433/3/1‬ه ـ وقــد ســافر خــارج اململكــة خروجــا نهائيــا‬\n  ‫يف ‪1433/8/29‬ه ـ ولــم يســدد أي شــيء مــن اإليجــارات املســتحقة منــذ‬\n  ‫ســفره بعــد ذلــك بقيــت الشــقة مغلقــة ويطلــب احلكــم بفســخ عقــد إيجــار‬\n  ‫الشــقة وتســليمها ملوكلتــه مــع احتفــاظ موكلتــه باملطالبــة بأجــرة‬\n  ‫الشــقة حتــى تاريــخ فســخها هكــذا ادعــى ‪ ،‬املدعــى عليــه أجنبــي غــادر‬\n  ‫اململكــة مغــادرة نهائيــة وذلــك حســب إفــادة مركــز الشــرطة فجــرى‬\n\n                                                                                        ‫‪344‬‬\n\f      ‫ســماع الدعــوى غيابي ـ ًا ‪ ،‬بينــة املدعــي صــك العقــار وعقــد اإليجــار‬\n      ‫وخطــاب مديــر مركــز الشــرطة املرفــق باملعاملــة املتضمــن أن املســتأجر‬\n      ‫خــارج اململكــة مبوجــب البرنــت املرفــق ‪ ،‬فبنــاء علــى املــادة ‪ 138‬مــن‬\n      ‫نظــام املرافعــات الشــرعية وحيــث ثبــت مغــادرة املدعــى عليــه اململكــة‬\n      ‫مغــادرة نهائيــة مبوجــب خطــاب الشــرطة وبرنــت وزارة الداخليــة وحيــث‬\n      ‫إن األصــل يف األمــور احلادثــة العــدم وبالتالــي عــدم ســداد األجــرة وألن‬\n      ‫ممــا يســوغ فيــه فســخ عقــد اإليجــار عــدم ســداد املســتأجر لألجــرة‪،‬‬\n      ‫ملــا تقــدم صــدر احلكــم بفســخ عقــد اإليجــار بــن الطرفــن وفتــح‬\n      ‫الشــقة املذكــورة مــن قبــل اجلهــات املختصــة وحفــظ مــا ميكــن حفظــه‬\n      ‫وبيــع مــا يخشــى عليــه التلــف وإيــداع ثمنــه ببيــت املــال لصالــح املدعــى‬\n      ‫عليــه وتســلم لصاحبتهــا‪ ،‬قنــع املدعــي وكالــة باحلكــم ورفــع احلكــم‬\n      ‫حملكمــة االســتئناف لتدقيقــه ‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n                                        ‫الثالثــة مبحكمــة االســتئناف بالريــاض‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 34371709‬وتاريــخ ‪ 1434/08/08‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341850308‬وتاريــخ ‪ 1434/08/01‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/10/21‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n      ‫ال عن‬‫وفيهــا حضــر ‪.......‬ســعودي بالســجل املدنــي رقــم ‪.......‬بصفتــه وكي ً‬\n      ‫‪ .......‬ســعودية بالســجل املدنــي رقــم ‪.......‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم ‪ 20623‬يف ‪1431/3/8‬ه ـ‬\n‫‪345‬‬\n\f‫جلــد ‪ 3719‬وكالــة تخولــه باملطالبــة واملداعــاة واملخاصمــة وســماع‬\n‫الدعــاوي والــرد عليهــا وقبــول احلكــم واالعتــراض عليــه وادعــى بقولــه‬\n‫أدعــي ضــد الغائــب ‪.......‬اجلنســية مبوجــب االقامــة رقــم ‪.......‬حيــث‬\n‫اســتأجر مــن موكلتــي الشــقة رقــم ‪ ...‬مــن عمارتهــا الواقعــة بحــي ‪...‬‬\n‫اململوكــة لهــا مبوجــب الصــك الصــادر مــن كتابــة العــدل األولــى‬\n‫برقــم ‪310107016656‬بتاريــخ ‪1431/5/19‬ه ـ وذلــك بأجــرة ســنوية‬\n‫قدرهــا عشــرين ألــف ريــال علــى دفعتــن اعتبــارا مــن ‪1433/3/1‬ه ـ‬\n‫وقــد ســافر خــارج اململكــة خروجــا نهائيــا يف ‪1433/8/29‬ه ـ ولــم‬\n‫يســدد أي شــيء مــن اإليجــارات املســتحقة منــذ ســفره بعــد ذلــك بقيــت‬\n‫الشــقة مغلقــة لــذا نطلــب احلكــم بفســخ عقــد إيجــار الشــقة املذكــورة‬\n‫بعاليــه وتســليمها ملوكلتــي مــع احتفــاظ موكلتــي باملطالبــة باجــرة‬\n‫الشــقة حتــى تاريــخ فســخها هــذه دعــواي ثــم أبــرز صــك العقــار وعقــد‬\n‫إيجــار الشــقة فوجدتهمــا كمــا ذكــر وقــال املدعــي بيناتــي يف املعاملــة‬\n‫فوجــدت خطــاب مديــر شــرطة مركــز العريجــا املوجــه لهــذه احملكمــة‬\n‫برقــم ‪ 4/6/9205/19‬يف ‪1434/7/26‬ه ـ وقــد جــاء فيــه أن املســتأجر‬\n‫خــارج اململكــة مبوجــب البرنــت املرفــق ووجــدت البرنــت كمــا ذكــروا‬\n‫وذكــر املدعــي لذلــك كلــه وبنــاء علــى املــادة ‪ 138‬مــن نظــام املرافعــات‬\n‫الشــرعية املثبــت ملغــادرة املدعــى عليــه اململكــة مغــادرة نهائيــة مبوجــب‬\n‫خطــاب الشــرطة وبرنــت وزارة الداخليــة وحيــث األصــل يف األمــور‬\n‫احلادثــة العــدم وبالتالــي عــدم ســداد االجــرة وألن ممــا يســوغ فيــه فســخ‬\n‫عقــد اإليجــاره عنــد عــدم ســداد املســتأجر لألجــرة لذلــك كلــه فقــد‬\n‫حكمــت بفســخ عقــد اإليجــارة بــن الطرفــن وفتــح الشــقة املذكــورة‬\n‫مــن قبــل اجلهــات املختصــة وحفــظ مــا يكــون فيهــا مــن أثــاث معتــاد أن‬\n\n\n                                                                                   ‫‪346‬‬\n\f      ‫يكــون للمســتأجر يف بيــت مــال احملكمــة لصالــح املدعــى عليــه ومــا‬\n      ‫يخشــى عليــه مــن التلــف يبــاع ثــم حتفــظ قيمتــه لصالــح املدعــى عليــه‬\n      ‫وتســلم الشــقة لصاحبتهــا وبعرضــه علــى املدعــي وكالــة قنــع بــه وأمــرت‬\n      ‫برفــع ذلــك حملكمــة االســتئناف لتدقيقــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/10/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n      ‫لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n      ‫باخلطــاب رقــم ‪ 341850308‬وتاريــخ ‪1434/10/28‬ه املرفــق بهــا‬\n      ‫الصــك رقــم ‪ 34340276‬وتاريــخ ‪1434/10/26‬ه ـ الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة الشــيخ ‪ .......‬املتضمــن احلكــم يف الدعــوى املقامــة‬\n      ‫مــن ‪ .......‬ضــد ‪ ...........‬الغائــب عــن مجلــس احلكــم ‪.......‬أمريكــي‬\n      ‫اجلنســية علــى النحــو املوضــح بالصــك واملتضمــن حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل بــه وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫تقــرر الدائــرة املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                               ‫نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪347‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":344,"source_page_end":347,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bc93a1d40015659dcc7b6983ae4ce81d79afd233748f0cdfdd91d478237b0680","normalized_text_hash":"c3c4c12c7121646a966778f81566697477a36bde67e3e3cfac872693118baf1f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p344-34340276"},{"id":"739f458f-f531-5a4b-ae21-daa46f0fa7d7","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -قيمة باقي أجرة لعن وباقي أجرة لوحدة يف تلك العن -الدفع باالتفاق على حسم األجرة مقابل إصاح العيوب - حلف اليمن مبوافقة املدعى على احلسم للمبلغ مقابل إصاح العيوب -لم يقم املدعى عليه البينة -إلزام املدعى عليه بدفع باقي األجرة احملسومة لعدم ثبوت االتفاق -وصرف النظر عن باقي أجرة الوحدة يف تلك العن .","document_number":"33480606","case_number":"64520215","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/28","year":"1434","subject":"عقد -إجارة -قيمة باقي أجرة لعن وباقي أجرة لوحدة يف تلك العن -الدفع باالتفاق على حسم األجرة مقابل إصاح العيوب - حلف اليمن مبوافقة املدعى على احلسم للمبلغ مقابل إصاح العيوب -لم يقم املدعى عليه البينة -إلزام املدعى عليه بدفع باقي األجرة احملسومة لعدم ثبوت االتفاق -وصرف النظر عن باقي أجرة الوحدة يف تلك العن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/28 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33480606:‬‬\n                    ‫َر ْق ُم الدعوى‪64520215 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 3452991‬تاريخه‪1434/3/2 :‬هـ‬\n\n\n ‫عقــد ‪ -‬إجــارة ‪ -‬قيمــة باقــي أجــرة لعــن وباقــي أجــرة لوحــدة يف تلــك‬\n ‫العــن ‪ -‬الدفــع باالتفــاق علــى حســم األجــرة مقابــل إصــاح العيــوب ‪-‬‬\n ‫حلــف اليمــن مبوافقــة املدعــى علــى احلســم للمبلــغ مقابــل إصــاح‬\n ‫العيــوب ‪ -‬لــم يقــم املدعــى عليــه البينــة ‪ -‬إلــزام املدعــى عليــه بدفــع‬\n ‫باقــي األجــرة احملســومة لعــدم ثبــوت االتفــاق‪ -‬وصــرف النظــر عــن‬\n                                      ‫باقــي أجــرة الوحــدة يف تلــك العــن ‪.‬‬\n\n\n\n\n ‫‪ .1‬قــول ابــن قنــدس يف حاشــيته علــى الفــروع‪« :‬فــإن اختلفــا يف قــدر‬\n ‫مــا أنفــق فالقــول قــول املكــري ألنــه منكــر فــإن لــم يشــرط لكنــه أذن لــه‬\n ‫يف اإلنفــاق ليحتســب لــه يف األجــرة ففعــل ثــم اختلفــا فالقــول قــول‬\n ‫املكــري وإن أنفــق مــن غيــر إذنــه لــم يرجــع بشــيء ألنــه أنفــق علــى مالــه‬\n ‫بغيــر إذنــه نفقــة غيــر واجبــة علــى املالــك فأشــبه مــا لــو عمــر لــه دارا‬\n                                                                   ‫أخــرى»‪.162/7‬‬\n ‫‪ .2‬قــول ابــن رجــب رحمــه اهلل تعالــى يف قواعــده‪« :‬نقــل جماعــة عــن‬\n ‫أحمــد مــا يــدل علــى أن اإلجــارة الصحيحــة ال جتــب منهــا األجــرة إال‬\n  ‫بقــدر االنتفــاع إذا تــرك املســتأجر بقيــة االنتفــاع بعــذر مــن جهتــه»‪.‬‬\n\n\n\n\n                                                                                       ‫‪348‬‬\n\f      ‫ادعــى املدعــي بأنــه أجــر عمارتــه أربــع ســنوات للمدعــى عليــه بأجــرة‬\n      ‫معلومــة إال أنــه لــم يدفــع منهــا ثالثــن ألــف ريــال مــن مجمــوع األجــرة‬\n      ‫املســتحقة لألربــع الســنوات كمــا قــام بتجديــد اســتئجاره للشــقة التــي‬\n      ‫يســكنها ســنة واحــدة مــن تاريــخ انتهــاء مــدة العقــد األول ولــم يدفــع مــن‬\n      ‫أجرتهــا إال أجــرة شــهر واحــد ‪ ،‬طلــب إلــزام املدعــى عليــه بــأن يدفــع‬\n      ‫باقــي أجــرة العمــارة وباقــي أجــرة الشــقة ‪ ،‬أقــر املدعــى عليــه بعقــد‬\n      ‫األربــع الســنوات وأنــه لــم يدفــع ثالثــن ألــف ريــال مــن إجمالــي األجــرة‬\n      ‫ودفــع بــأن املدعــي تنــازل بهــا لــه مقابــل إصالحــه عيــوب العمــارة وأنكــر‬\n      ‫قيامــه بتجديــد عقــد الشــقة وإمنــا عــرض عليــه ذلــك فاختلفــا يف األجــرة‬\n      ‫فبقــي فيهــا شــهرا ثــم خــرج ‪ ،‬بعرضــه علــى املدعــي متســك بأحــد بنــود‬\n      ‫العقــد بــأن كل مــا يضيفــه ويصلحــه املدعــي مــن إصالحــات تكــون‬\n      ‫علــى املســتأجر ‪ ،‬بطلــب البينــة مــن املدعــى عليــه علــى دفعــه قــرر بــأال‬\n      ‫بينــة لديــه وطلــب ميــن املدعــي فحلــف اليمــن املطلوبــة ‪ ،‬عليــه ولطلــب‬\n      ‫املدعــي إلــزام املدعــى عليــه بدفــع ثالثــن ألف ريال نظيــر املبلغ الذي قام‬\n      ‫بحســمه مــن كامــل أجــرة العمــارة ولطلبــه أيضــا إلزامــه بدفــع الباقــي‬\n      ‫مــن األجــرة الســنوية مــن ‪1432/2/1‬ه ـ حتــى ‪1433/3/1‬ه ـ وقدرهــا‬\n      ‫اثنــان وثالثــون ألــف ريــال و إلقــرار املدعــى عليــه بصحــة حســم املبلــغ‬\n      ‫البالــغ ثالثــن ألــف ريــال أو زيــادة ولدفعــه بــأن حســمه كان إلصالحــه‬\n      ‫عيــوب العمــارة مبوافقــة املدعــي وإلنــكار املدعــي ذلــك ولعجــز املدعــى‬\n      ‫عليــه عــن إقامــة البينــة علــى دفعــه ذلــك وطلبــه ميــن املدعــي ولبذلــه لهــا‬\n      ‫علــى النحــو املرصــود وملــا قــرره أهــل العلــم يف هــذا املســألة قــال ابــن‬\n\n‫‪349‬‬\n\f‫قنــدس يف حاشــيته علــى الفــروع‪ »:‬فــإن اختلفــا يف قــدر مــا أنفــق فالقــول‬\n‫قــول املكــري ألنــه منكــر فــإن لــم يشــرط لكنــه أذن لــه يف اإلنفــاق‬\n‫ليحتســب لــه يف األجــرة ففعــل ثــم اختلفــا فالقــول قــول املكــري وإن‬\n‫أنفــق مــن غيــر إذنــه لــم يرجــع بشــيء ألنــه أنفــق علــى مالــه بغيــر إذنــه‬\n‫نفقــة غيــر واجبــة علــى املالــك فأشــبه مــا لــو عمــر لــه دارا أخــرى» ‪162/7‬‬\n‫‪،‬وألن املدعــى عليــه بقــي يف العــن املؤجــرة شــهرا حتــى ‪1432/2/1‬ه ـ‬\n‫ودفــع للمدعــي قســط تلــك املــدة كمــا قــال وصادقــه املدعــي علــى ذلــك‬\n‫ولعــدم ثبــوت جتديــد العقــد وملــا قالــه ابــن رجــب رحمــه اهلل تعالــى يف‬\n‫قواعــده « نقــل جماعــة عــن أحمــد مــا يــدل علــى أن اإلجــارة الصحيحــة‬\n‫ال جتــب منهــا األجــرة إال بقــدر االنتفــاع إذا تــرك املســتأجر بقيــة االنتفــاع‬\n‫بعــذر مــن جهتــه «عليــه فقــد حكمــت احملكمــة علــى املدعــى عليــه بــأن‬\n‫يدفــع للمدعــي ثالثــن ألــف ريــال وصــرف النظــر عــن طلــب املدعــي‬\n‫احلكــم علــى املدعــى عليــه بإلزامــه بدفــع أجــرة باقــي الســنة للشــقه‪،‬‬\n                                    ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....................‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 64520215‬وتاريــخ‬\n‫‪ 1432/03/12‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3227445‬وتاريــخ‬\n‫‪ 1432/03/12‬ه ـ املتعلقــة بدعــوى ‪ ...................‬ضــد ‪ ...................‬ففــي‬\n‫هــذا اليــوم الســبت ‪1433/2/20‬ه ـ افتتحــت اجللســة الســاعة ‪10.45‬‬\n‫وفيها حضر املدعي ‪...........................‬ســعودي اجلنســية مبوجب الســجل‬\n\n                                                                                        ‫‪350‬‬\n\f      ‫املدنــي رقم………………وحضــر حلضــوره املدعــى عليــه ‪...................‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...................‬ثــم ادعــى‬\n      ‫ا لقــد ســبق وان قمــت بتأجيــر‬         ‫املدعــي يف مواجهــة املدعــى عليــه قائ ـ ً‬\n      ‫هــذا املدعــى عليــه كامــل عمارتــي الســكنية الواقعــة ‪ ...‬واململوكــة‬\n      ‫لــي مبوجــب صــك امللكيــة الصــادر مــن كتابــة العــدل األولــى مبكــة‬\n      ‫املكرمــة برقــم ‪ 6/308/615‬يف ‪1421/7/18‬ه ـ وذلــك ملــدة خمــس‬\n      ‫ســنوات اعتبــار ًا مــن ‪1428/2/1‬ه وتنتهــي يف ‪1433/1/30‬ه ـ بأجــرة‬\n      ‫ســنوية قدرهــا تســعون ألــف ريــال ونظــر ًا الن املدعــى عليــه قــد اخــل‬\n      ‫ببنديــن مــن بنــود عقــد اإليجــار املبــرم معــه وهمــا األول الــذي ينــص‬\n      ‫علــى أن يدفــع األجــرة يف أول كل ســنة هجريــة حيــث لــم يلتــزم بذلــك‬\n      ‫وإمنــا كان مياطــل يف بذلهــا كمــا اخــل بالبنــد الســادس والــذي ينــص‬\n      ‫علــى انــه يف حالــة عــدم قيــام املســتأجر بدفــع األجــرة يف املوعــد احملــدد‬\n      ‫فيحــق للطــرف األول والــذي هــو أنــا املؤجــر تأجيــر العــن علــى الغيــر‬\n      ‫وأنــه يجــب علــى املســتأجر اإلخــاء مــن اجــل ذلــك قمــت بإبــرام اتفــاق‬\n      ‫آخــر معــه وذلــك بتاريــخ ‪1430/8/11‬ه ـ يقضــي بتقليــص مــدة اإليجــار‬\n      ‫لتكــون أربــع ســنوات بــدال مــن خمــس ليكــون إخــاؤه للعمــارة بتاريــخ‬\n      ‫‪1432/2/1‬ه ـ وبنــاء علــى ذلــك فقــد بقــي املدعــى عليــه يف العــن‬\n      ‫املؤجــرة إلــى تاريــخ ‪1432/2/1‬ه ـ ثــم أخالهــا ماعــدا الشــقة التــي كان‬\n      ‫يســكنها كمــا أضيــف إلــى انــه حســم مبلغ ـ ًا قــدره ثالثــون ألــف ريــال‬\n      ‫مــن كامــل األجــرة للســنوات األربــع وذلــك مــن غيــر مــا بــأس ثــم طلــب‬\n      ‫منــي أن أجــدد لــه اإليجــار ملــدة ســنة واحــدة اعتبــارا مــن ‪1432/2/1‬ه ـ‬\n      ‫وحتــى ‪1433/3/1‬ه ـ لشــقتني مــن عمارتــي التــي وصفتهــا إحداهمــا لــه‬\n      ‫واألخــرى لعديلــه املدعــو ‪ ................. /‬وبالفعــل جــددت اإليجــار ملــدة‬\n\n\n‫‪351‬‬\n\f‫ســنه مــن ‪1432/2/1‬ه ـ حتــى ‪1433/3/1‬ه ـ ولكــن باجــرة ســنوية‬\n‫قدرهــا خمســة وثالثــون ألــف ريــال لــكل شــقة ومت االتفــاق علــى ذلــك‬\n‫ولكــن بعــد مضــي شــهر فقــط مــن تاريــخ التجديــد األخيــر والــذي كان‬\n‫قبــل نهايــة العقــد األساســي بشــهر قــام املدعــى عليــه بتســليم قســط‬\n‫شــهر واحــد فقــط مــن أجــرة تلــك الســنة وقــام بإخــاء شــقته متناســيا‬\n‫أن عقــد اإليجــار عقــد ملــزم للطرفــن حيــث لــم يســلمني ســوى مبلــغ‬\n‫ثالثــة أالف ريــال مــن كامــل أجــرة تلــك الســنة لــذا فانــي اطلــب احلكــم‬\n‫علــى املدعــى عليــه مبــا يلــي أوال بدفــع املبلــغ املقــدر بثالثــن ألــف ريــال‬\n‫وذلــك نظيــر املبلــغ الــذي قــام بحســمه مــن كامــل أجــرة العمــارة يف‬\n‫الســنوات اإليجاريــة ثانيــا إلزامــه بدفــع الباقــي مــن األجــرة الســنوية مــن‬\n‫‪1432/2/1‬ه ـ حتــى ‪1433/3/1‬ه ـ وقــدره اثنــان وثالثــون ألــف ريــال ‪.‬‬\n‫هــذه دعــواي واســأله اجلــواب وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n‫قائــا إن مــا ورد يف دعــواه مــن كونــي اســتأجرت منــه عمارتــه التــي‬\n‫وصفهــا يف دعــواه للمــدة التــي ذكرهــا باألجــرة التــي بينهــا فصحيــح وال‬\n‫أنكــره ومــا يتعلــق بتقليــص مــدة اإليجــار مــن خمــس ســنوات إلــى أربــع‬\n‫مبوجــب االتفــاق اإلحلاقــي فصحيــح وال أنكــره حيــث بقيــت يف العمــارة‬\n‫يف الســنة األخيــرة أي الســنة الرابعــة حتــى ‪1432/2/1‬ه ـ ومــا ذكــره يف‬\n‫دعــواه مــن كونــي خصمــت مبلــغ ثالثــن ألــف ريــال مــن إجمالــي أجــرة‬\n‫الســنوات األربــع فصحيــح لكنــه ليــس ثالثــن ألــف ريــال بــل قــد تكــون‬\n‫أكثــر مــن ثالثــن ألــف حيــث قمــت بحســمها والســبب يف ذلــك هــو مــا‬\n‫كانــت تعانيــه تلــك العمــارة مــن عيــوب كثيــرة خاصــة يف الصــرف‬\n‫الصحــي فقمــت بإصــاح ذلــك مبوافقــة املدعــي وحســمت مــا كلفتنــي‬\n‫تلــك اإلصالحــات مبوافقــة املدعــي املســبقة علــى ذلــك ومــا يتعلــق بطلبــه‬\n\n\n                                                                                        ‫‪352‬‬\n\f      ‫باقــي أجــرة الشــقة التــي ذكــر بأنــه جــدد لــي إجارهــا فالصحيــح أنــي‬\n      ‫لــم أقــم بتجديــد إجــار تلــك الشــقة مــع املدعــي وإمنــا بقيــت فيهــا شــهر ًا‬\n      ‫واحــدا فقــط كــون أوالدي يقومــون حينهــا بإكمــال اختباراتهــم وقــد‬\n      ‫اخبرنــي بالفعــل إن كنــت أرغــب يف جتديــد إيجارهــا فســألته عــن‬\n      ‫مقــدار أجرتهــا فأخبرنــي بــان أجرتهــا تبلــغ خمســة وثالثــن ألــف ريــال‬\n      ‫فأخبرتــه بــأن هــذه األجــرة كبيــرة جــدا فــان كان ســيخفضها لــي‬\n      ‫فســوف أبقــى وإال فســوف اخــرج منهــا فأصــر علــى أن تكــون األجــرة‬\n      ‫بخمســة وثالثــن ألــف ريــال وأعطيتــه قســط الشــهر الــذي مكثتــه فيهــا‬\n      ‫البالــغ ثــاث آالف ريــال أعطيتــه إيــاه بتاريــخ ‪1432/2/5‬ه ـ وبالتالــي لــم‬\n      ‫أجــدد معــه بخصــوص تلــك الشــقة أيعقــد هكــذا قــال ثــم عرضــت علــى‬\n      ‫املدعــي مــا دفــع بــه املدعــى عليــه مــن كــون الثالثــن ألــف ريــال التــي‬\n      ‫حســمها كان نظيــر إصالحــات لعيــوب يف صــرف العمــارة الصحــي و‬\n      ‫كانــت إصالحاتــه تلــك مبوافقتــه فأجــاب بقولــه إن مــا ذكــره املدعــى‬\n      ‫عليــه غيــر صحيــح فلــم أوافــق علــى مســألة اإلصالحــات إضافــة إلــى‬\n      ‫أن البنــد الرابــع مــن عقــد اإلجــار ينــص علــى أنــه إن حصــل تلــف يف‬\n      ‫املوقــع املؤجــر فــإن علــى املدعــى عليــه القيــام بإصــاح جميــع مــا تلــف‬\n      ‫و شــراء ذلــك وتركيبــه يف محلــه بــدون مماطلــة و ليــس لــه احلــق يف‬\n      ‫املطالبــة بالتعويــض عنهــا يف حالــة اإلخــاء و كذلــك البنــد اخلامــس‬\n      ‫مــن عقــد الصلــح الــذي ينــص أن يقــوم املســتأجر بتســليم العــن بــدون أي‬\n      ‫أضــرار أو ســوء اســتخدام هكــذا قــال وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫أجــاب بقولــه إن الصحيــح هــو مــا قلتــه فلقــد كان ذلــك احلســم بنــاء علــى‬\n      ‫موافقتــه هكــذا قــال ثــم ســألته هــل لديــك البينــة علــى ذلــك فأجــاب‬\n      ‫بالنفــي ثــم ســألته هــل ترغــب يف ميــن املدعــي علــى عــدم موافقتــه علــى‬\n\n\n‫‪353‬‬\n\f‫حســم ثالثــن ألــف ريــال مــن أجــرة العمــارة نظيــر إصالح عيوبهــا فأجاب‬\n‫بقولــه نعــم إنــي أرغــب يف ميينــه فعرضــت اليمــن علــى املدعــي فأســتعد‬\n‫ببذلهــا فحلــف قائــا و اهلل العظيــم الــذي ال الــه اال هــو عالــم الغيــب‬\n‫والشــهادة بأنــي لــم أوافــق علــى أن يحســم هــذا املدعــى عليــه ثالثــن‬\n‫ألــف ريــال مــن أجــرة العمــارة نظيــر إصالحــات العيــوب التــي قــام بهــا‬\n‫و اهلل العظيــم هكــذا حلــف عليــه أمــرت برفــع اجللســة الــى يــوم األحــد‬\n‫‪1433/11/21‬ه ـ الســاعة ‪ 12 : 00‬للدراســة والتأمــل تأجلــت ويف يــوم‬\n‫األحــد ‪1433/11/21‬ه افتتحــت اجللســة وفيهــا حضــر املدعــي وحضــر‬\n‫حلضــوره املدعــو ‪.......................‬بالســجل املدنــي رقــم ‪ ...................‬وأبــرز‬\n‫صــورة وكالتــه عــن املدعــى عليــه‪ ..................‬بالوكالــة الصــادرة مــن‬\n‫كتابــة العــدل الثانيــة مبكــة املكرمــة رقــم ‪ 30034‬يف ‪1430/8/10‬هـ‬\n‫املخــول لــه فيهــا املرافعــة و املدافعــة و حضــور اجللســات الــخ ومذيــل بختــم‬\n‫اعتمــاد وجــرى ربــط صــوره منهــا يف املعاملــة ثــم ســألته عــن أصلهــا فقــال‬\n‫أن أصلهــا مــع املدعــى عليــه و بعــد دراســة مــا تقــدم مــن الدعــوى واإلجابة‬\n‫و لطلــب املدعــي الــزام املدعــى عليــه بدفــع املبلــغ املقــدر بثالثــن ألــف‬\n‫ريــال وذلــك نظيــر املبلــغ الــذي قــام بحســمه مــن كامــل أجــرة العمــارة‬\n‫يف الســنوات اإلجاريــه ولطلبــه أيضــا الزامــه بدفــع الباقــي مــن األجــرة‬\n‫الســنوية مــن ‪1432/2/1‬ه ـ حتــى ‪1433/3/1‬ه ـ وقدرهــا اثنــان وثالثــون‬\n‫ألــف ريــال و إلقــرار املدعــى عليــه بصحــة حســم املبلــغ البالــغ ثالثــن‬\n‫ألــف ريــال أو زيــادة كمــا قــال و دفعــه بــأن حســمه كان الصالحاتــه‬\n‫لعيــوب يف تلــك العمــارة وأن حســمه ذلــك كان مبوافقــة املدعــي و ال‬\n‫أنــكار املدعــي لذلــك ولعجــز املدعــى عليــه عــن إقامــة البينــة علــى دفعــه‬\n‫ذلــك وطلبــه ميــن املدعــي وبذلــه لهــا علــى النحــو املرصــود وملــا قــرره أهــل‬\n\n\n                                                                                               ‫‪354‬‬\n\f      ‫العلــم يف هــذا اجلانــب حيــث قــال ابــن قنــدس يف حاشــيته علــى الفــروع‬\n      ‫((فــإن اختلفــا فيقــدر مــا أنفــق فالقــول قــول املكــري ألنــه منكــر فــإن‬\n      ‫لــم يشــرط لكنــه أذن لــه يف اإلنفــاق ليحتســب لــه يف األجــرة ففعــل‬\n      ‫ثــم أختلفــا فالقــول قــول املكــري وإن أنفــق مــن غيــر إذنــه لــم يرجــع‬\n      ‫بشــيء ألنــه أنفــق علــى مالــه بغيــر إذنــه نفقــة غيــر واجبــة علــى املالــك‬\n      ‫فأشــبه مــا لــو عمــر لــه دارا أخــرى )) ‪ 162/7‬وألن املدعــى عليــه بقــي‬\n      ‫يف العــن املؤجــرة شــهرا حتــى ‪1432/2/1‬ه ـ ودفــع للمدعــي قســط تلــك‬\n      ‫املــدة كمــا قــال وصادقــه املدعــي علــى ذلــك مبطالبتــه بباقــي األجــرة‬\n      ‫وملــا قالــه ابــن رجــب رحمــه اهلل تعالــى يف قواعــده ( نقــل جماعــة عــن‬\n      ‫أحمــد مــا يــدل علــى أن اإلجــارة الصحيحــة ال جتــب منهــا األجــرة اال‬\n      ‫بقــدر االنتفــاع إذا تــرك املســتأجر بقيــة االنتفــاع بعــذر مــن جهتــه ) بنــاء‬\n      ‫علــى ذلــك فقــد حكمــت علــى املدعــى عليــه ‪ ...........................‬بــأن‬\n      ‫يدفــع للمدعــي ‪ ................‬ثالثــن ألــف ريــال نظيــر املبالــغ التــي قــام‬\n      ‫بحســمها مــن أجــرة العمــارة يف الســنوات اإلجاريــة وصرفــت النظــر عــن‬\n      ‫طلــب املدعــي املذكــور احلكــم علــى املدعــى عليــه بدفــع الباقــي مــن‬\n      ‫األجــرة عــن املــدة التــي حددهــا يف دعــواه و بذلــك حكمــت وبعرضــه‬\n      ‫علــى املدعــي قــرر قناعتــه بــه بينمــا قــرر املدعــى عليــه وكالــة اعتراضــه‬\n      ‫عليــه فجــرى إفهامــه مبراجعــة احملكمــة خــال عشــرة أيــام مــن تاريخــه‬\n      ‫الســتالم نســخة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومـ ًا‬\n      ‫فــإن لــم يفعــل خاللهــا فــإن حقــه يف االعتــراض يســقط ويكتســب‬\n      ‫احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                        ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم عــادت أوراق املعاملــة من محكمة االســتئناف‬\n\n\n‫‪355‬‬\n\f‫باخلطاب رقم ‪ 34512510‬يف ‪1434/3/4‬هـ رفقها الصك الشرعي رقم‬\n‫‪33480606‬يف ‪1433/12/28‬ه ـ مظهــر ًا عليــه بقــرار الدائــرة احلقوقيــة‬\n‫الســابعة مبحكمــة االســتئناف رقــم ‪ 3452991‬يف ‪1434/3/2‬ه ـ‬\n‫املتضمــن أنــه بدراســة احلكــم وصــورة ضبطــه والئحتيــه االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم‪ .‬قاضــي اســتئناف‪ ...........‬ختــم وتوقيــع‬\n‫قاضــي اســتئناف‪ ...........‬ختــم وتوقيــع رئيــس الدائــرة‪ ...........‬ختــم‬\n‫وتوقيــع ‪ .‬حــرر يف ‪1434/4/17‬ه ــوصل اهلل علــى نبينــا محمــد وعلــى‬\n                                                               ‫آلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ....................‬القاضــي باحملكمــة‬\n‫العامــة مبكــة املكرمــة خلــف فضيلــة الشــيخ ‪ .......................‬ففــي هــذا‬\n‫اليــوم األحــد ‪1434/5/19‬ه ــحضر املدعــي ‪ ...........................‬ســجل‬\n‫مدنــي رقــم ‪ ......................‬وقــرر بقولــه إننــي اســتلمت مــن املدعــى عليــه‬\n‫‪ ..................‬كامــل املبلــغ احملكــوم لــي بــه عليــه مبوجــب الصــك رقــم‬\n‫‪ 33480606‬يف ‪1433/12/28‬ه ـ وقــدره ثالثــون ألــف ريــال ولــم يبقــى‬\n‫لــي شــيء بذمتــه بخصــوص هــذه الدعــوى وأطلــب التهميــش بذلــك علــى‬\n‫صــك احلكــم هكــذا قــرر ‪ .‬عليــه أمــرت بالتهميــش بذلــك علــى صــك‬\n‫احلكــم وســجله وبــاهلل التوفيــق وصــل اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم حــرر يف ‪1434/5/19‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ فقــد‬\n‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪32/27445‬‬\n‫وتاريــخ ‪1434/02/25‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n\n\n                                                                                          ‫‪356‬‬\n\f      ‫الشــيخ ‪ ........................‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n      ‫املســجل برقــم ‪ 33480606‬وتاريــخ ‪1433/12/28‬ه ـ املتضمــن دعــوى‬\n      ‫‪ ......................‬ضــد ‪ ،....................‬وبدراســة الصــك وص ــورة ضبط ــه‬\n      ‫والئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‪ .‬واهلل املوفــق‪.‬‬\n                    ‫وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪357‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":348,"source_page_end":357,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"611a00b0a1b1a5fc638338314ca3a01524c67e988b775723ee013cab95ae6358","normalized_text_hash":"2b0d129f0fac94ce5e4ddf0ee9ad5d91eeb7cf40beb18779842c92ed8c12fe47","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p348-33480606"},{"id":"7e2049c1-eb95-512e-8a6e-e0bcf9fb717a","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -إخاء عقار من غائب -اإلعان يف صحيفة محلية لتبليغ املدعى عليه -البينة للمدعى شهادة الشهود العدول واليمن -وجوب الوفاء بالعقود -حفظ محتويات العن يف بيت املال وبيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -احلكم بفتح العن وإخالءها -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه به -الغائب على حجته متى حضر.","document_number":"34185350","case_number":"83530306","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/10","year":"1434","subject":"عقد -إجارة -إخاء عقار من غائب -اإلعان يف صحيفة محلية لتبليغ املدعى عليه -البينة للمدعى شهادة الشهود العدول واليمن -وجوب الوفاء بالعقود -حفظ محتويات العن يف بيت املال وبيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -احلكم بفتح العن وإخالءها -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه به -الغائب على حجته متى حضر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34185350 :‬‬\n                   ‫َر ْق ُم الدعوى‪83530306 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34312393‬تاريخه‪1434/9/3:‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬إخــاء عقــار مــن غائــب ‪ -‬اإلعــان يف صحيفــة محليــة‬\n‫لتبليــغ املدعــى عليــه ‪ -‬البينــة للمدعــى شــهادة الشــهود العــدول‬\n‫واليمــن ‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬حفــظ محتويــات العــن يف بيــت‬\n‫املــال وبيــع مــا يخشــى تلفــه وإيــداع ثمنــه يف بيــت املــال ‪ -‬احلكــم بفتــح‬\n‫العــن وإخالءهــا ‪ -‬رفــع احلكــم حملكمــة االســتئناف لتعــذر تبليــغ‬\n                 ‫املدعــى عليــه بــه‪ -‬الغائــب علــى حجتــه متــى حضــر‪.‬‬\n\n\n\n\n                     ‫‪ .1‬قوله تعالى (يا أيها الذين آمنوا أوفوا بالعقود)‪.‬‬\n‫‪ .2‬قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى‬\n                                         ‫املدعــى عليــه) رواه الترمــذي‪.‬‬\n‫‪ .3‬قولــه صلــى اهلل عليــه وســلم (ال ضــرر وال ضــرار) رواه أبــو داوود‬\n                                                    ‫وصححــه احلاكــم‪.‬‬\n                          ‫‪ .4‬املادة ‪ 55‬و‪ 176‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه‬\n‫اســتأجر ملحق شــقة رقم ‪ ...‬من العمارة مبدينة ‪ ...‬بحي ‪ ...‬بأجرة ســنوية‬\n‫قدرهــا اثنــا عشــر ألفـ ًا وخمســمائة ريــال اعتبارا مــن ‪1429/1/1‬هـ وقد‬\n\n                                                                                      ‫‪358‬‬\n\f      ‫تخلــف عــن ســداد األجــرة فتــرة طويلــة وهــو غيــر موجــود بالشــقة منــذ‬\n      ‫شــهر رمضــان لعــام ‪1431‬ه ـ وقــد غــادر اململكــة مغــادرة نهائيــة خــروج‬\n      ‫نهائــي ويطلــب فتــح الشــقة هكــذا ادعــى ‪ ،‬املدعــى عليــه أجنبــي غــادر‬\n      ‫اململكــة مغــادرة نهائيــة حســب إفــادة وحــدة األمــن بالدوائــر الشــرعية‬\n      ‫املرفــق باملعاملــة فجــرى ســماع الدعــوى غيابيــا بنــاء علــى املــادة ‪ 55‬مــن‬\n      ‫نظــام املرافعــات الشــرعية ‪ ،‬جــرى اإلعــان يف الصحيفــة عــن موعــد‬\n      ‫اجللســة ‪ ،‬بينــة املدعــي شــاهدان شــهدا طبــق دعــواه ‪ ،‬حلــف املدعــي‬\n      ‫اليمــن علــى صحــة دعــواه بعــد طلبهــا منــه ‪ ،‬أبــرز املدعــي صــك ملكيــة‬\n      ‫العقــار وعقــد اإليجــار ‪ ،‬فبنــاء علــى البينــة املتمثلــة يف الصــك ملكيــة‬\n      ‫العقــار ‪ ،‬وعقــد اإليجــار ‪ ،‬وشــهادة الشــاهدين املعدلــة شــرعا ‪ ،‬وبنــاء‬\n      ‫علــى ميــن املدعــي أصالــة ووكالــة بصفتــه مباشــر عقــد اإليجــار وأحــد‬\n      ‫مــاك العقــار ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود) ‪،‬‬\n      ‫وحلديــث (البينــة علــى املدعــي واليمني على املدعى عليه) رواه الترمذي‪،‬‬\n      ‫وحلديــث ( ال ضــرر و ال ضــرار ) رواه أبــو داوود وصححــه احلاكــم ‪،‬‬\n      ‫وألن الضــرر يف الشــريعة مرفــوع ‪ ،‬وبنــاء علــى املــادة ‪ 55‬و ‪ 176‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ‪ ،‬ملــا تقــدم صــدر احلكم بفتــح العقار محل الدعوى‬\n      ‫وإخــاءه عــن طريــق اجلهــات املختصــة ‪ ،‬واالحتفــاظ مبوجــودات العقــار‬\n      ‫مــا يخــص املدعــى عليــه منــه لــدى اجلهــة املعنيــة ‪ ،‬وبيــع مــا يخشــى تلفــه ‪،‬‬\n      ‫وإيــداع ثمنــه لــدى بيــت مــال احملكمــة وإفهــام املدعــي بــأن املدعــى عليــه‬\n      ‫علــى حجتــه متــى حضــر‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة الرابعــة‬\n                                 ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n‫‪359‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 83530306‬وتاريــخ‬\n‫‪ 1432/04/01‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3227852‬وتاريــخ‬\n‫‪ 1432/04/01‬ه ـ ففــي يــوم االربعــاء املوافق‪ 1432/07/06‬هـ أفتتحت‬\n‫اجللســة الســاعة ‪ 09 : 23‬وفيهــا حضــر املدعــى ‪.....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪.....‬ولــم يحضــر املدعــى عليــه وال وكيــل‬\n‫عنــه وكنــا قــد كتبنــا الــى وحــدة الدوائــر الشــرعية فوردنــا خطابهــم‬\n‫برقــم ‪ 14713‬وتاريــخ ‪1432/07/03‬ه ـ وفيــه عليــه نفيــد فضيلتكــم‬\n‫بانــه بالرجــوع للحاســب االلــى طرفنــا اتضــح بانــه مســافر الــى مصــر‬\n‫العربيــة بتاريــخ ‪1431/9/16‬ه ـ ولــم تثبــت عودتــه حتــى تاريخــه كمــا‬\n‫يتضــح لكــم مــن البرنــت املرفــق أ‪.‬ه ـ لــذا فقــد جــرى اثبــات ذلــك‪ .‬ثــم‬\n‫انــه يف يــوم االحــد املوافــق ‪1433/03/13‬ه ـ أفتتحــت اجللســة الســاعة‬\n‫‪ 11 : 53‬وفيهــا حضــر املدعــى ولــم يحضــر املدعــى عليــه ‪..........‬وال‬\n‫وكيــل عنــه وقــد طلــب املدعــى االعــان يف احــد الصحــف احملليــة عــن‬\n‫موعــد اجللســة القادمــة فاجبتــه الــى طلبــه لــذا رفعــت اجللســة ‪ .‬ثــم انــه يف‬\n‫يــوم األحــد املوافــق‪ 1433/06/08‬ه ـ افتتحــت اجللســة الســاعة ‪01 : 44‬‬\n‫وفيهــا حضــر املدعــى ‪.....‬ولــم يحضــر املدعــى عليــه ‪ .....‬وال وكيــل عنــه‬\n‫ومت االعــان عــن موعــد هــذه اجللســة يف صحيفــة (‪)000‬يــوم الســبت ‪24‬‬\n‫ربيــع االخــر ‪1433‬ه ـ عــدد رقــم ‪ 17860‬وقــد طلــب املدعــى الســير يف‬\n‫القضيــة غيابيــا حســب املــاده اخلامســة واخلمســون مــن نظــام املرافعــات‬\n\n                                                                                        ‫‪360‬‬\n\f      ‫فاجبتــه الــى طلبــه وبســؤاله عــن دعــواه قــال ان املدعــى عليــه ‪.....‬مصــري‬\n      ‫اجلنســية مبوجــب االقامــة رقــم ‪.....‬مســتأجر لدينــا ملحــق شــقة رقــم ‪ ...‬من‬\n      ‫العمــارة مبدينــة ‪ ...‬بحــى ‪.....‬وعليــه متأخــرات ايجاريــه ولــه فتــرة طويلــة‬\n      ‫غيــر موجــود بالشــقة منــذ شــهر رمضــان لعــام ‪1431‬ه ـ وســألنا عنــه‬\n      ‫بعملــه قالــوا اخــذ خــروج نهائــي لــذا اطلــب فتــح الشــقه واحتســاب احلقوق‬\n      ‫املاليــة حتــى تاريــخ فتــح الشــقة هــذه دعــواى هــذا وبســؤاله عــن بينتــه قــال‬\n      ‫اطلــب امهالــي الحضارهــا لــذا رفعــت اجللســة واختتمــت اجللســة الســاعة‬\n      ‫الثانيــة ‪ .‬فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة‬\n      ‫والقائــم بعمــل الشــيخ ‪.....‬ففــي يــوم الســبت املوافــق‪1434/04/06‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة ‪ 08.30‬وفيهــا حضــر املدعــي ‪.....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬ولــم يحضــر املدعــى عليــه ‪.....‬‬\n      ‫وال وكيــل عنــه وكانــت اجللســة املاضيــة قــد رفعــت إلحضــار البينــة مــن‬\n      ‫قبــل املدعــي وبســؤاله قــال ‪ :‬لقــد احضــرت الشــهود وهــم ‪ .....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬وعمــره ‪ 35‬ومقــر اقامتــه جــده‬\n      ‫ويعمــل لــدى محافظــه جــده وال توجــد صلــه قرابــه بينــه وبــن احــد‬\n      ‫املدعــن وحضــر الشــاهد الثانــي ‪.....‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪.....‬ومقــر اقامتــه جــده وعمــره ‪ 43‬ويعمــل لــدى شــركة‬\n      ‫‪.....‬الغذائيــة وال توجــد قرابــه بينــه وبــن املدعــن وشــهد كال منهمــا‬\n      ‫مبفــرده بقولــه ‪ :‬اشــهد بــاهلل العظيــم ان املســتأجر ‪.....‬مصــري اجلنســية‬\n      ‫مســتأجر امللحــق يف العمــارة التــي نســكن بهــا يف جــده حــي ‪...‬وهــي‬\n      ‫ملــك ‪.....‬وقــد تــرك املســتأجر الشــقة وال نعلــم عنــه شــيء منــذ فتــرة‬\n      ‫طويلــة ولــم نشــاهده والشــقة محــل الدعــوى مقفلــة منــذ عــام ‪1431‬ه ـ‬\n      ‫‪ .‬هكــذا شــهدا ‪ .‬وعــدال مــن قبــل ‪.....‬مينــي اجلنســية مبوجــب االقامــة‬\n\n\n‫‪361‬‬\n\f‫رقــم ‪.....‬و‪.....‬مينــي اجلنســية مبوجــب االقامــة رقــم ‪ ،.....‬وبســؤال املدعــي‬\n‫أصالــة عــن صــك امللكيــة للعقــار محــل الدعــوى قــال ‪ :‬اطلــب امهالــي‬\n‫إلحضارهــا غــدا فأجبتــه لطلبــة والزمتــه بإحضارهــا يــوم غــدا االحــد‬\n‫املوافق ‪1434/4/07‬هـ لذا رفعت اجللســة الســاعة ‪ 08.45‬فلدي أنا ‪.....‬‬\n‫القاضــي يف احملكمــة العامــة مبحافظــة جــدة والقائــم بعمــل الشــيخ ‪.....‬‬\n‫ففــي يــوم االثنــن املوافق‪1434/04/08‬ه ـ افتتحــت اجللســة الســاعة ‪00‬‬\n‫‪ 01 :‬وفيهــا حضــر املدعــي ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪.....‬ولــم يحضــر املدعــى عليــه ‪.....‬وال وكيــل عنــه وكانــت اجللســة‬\n‫املاضيــة قــد رفعــت إلمهــال املدعــي إلحضــار صــك امللكيــة للعقــار ‪،‬‬\n‫وقــرر املدعــي قائــا ‪ :‬إن العقــار ملــك للورثــة وأنــا مــن قــام مبباشــرة‬\n‫العقــد ‪ ،‬وأطلــب تصحيــح الدعــوى ليكــون املدعــي فيهــا هــم ورثــة ‪.....‬‬\n‫عــدا ‪ ، ...‬وأطلــب حصــر دعــواي يف هــذه الدعــوى علــى إخــاء العقــار‬\n‫‪ ،‬واحتفاظــي وموكلــي بحــق إقامــة دعــوى مســتقلة بخصــوص األجــرة‬\n‫املتأخــرة ‪ .‬وبســؤاله عــن دعــواه ليتــم حتريرهــا أكثــر قــال ‪ :‬إن املدعــى‬\n‫عليه ‪ .....‬مصري اجلنســية مبوجب اإلقامة رقم ‪.....‬مســتأجر لدينا ملحق‬\n‫شــقة رقــم ‪ ...‬مــن العمــارة مبدينــة جــدة بحــي ‪...‬واململوكــة لنــا بالصــك‬\n‫رقــم ‪ 1040‬يف ‪1421/1/27‬هــ‪ ،‬مبوجــب عقــد إيجــار رقــم ‪ 14‬وتاريــخ‬\n‫(بــدون) بأجــرة ســنوية قدرهــا اثنــا عشــر ألفــا وخمســمائة ريــال اعتبــارا‬\n‫مــن تاريــخ ‪1429/1/1‬هــ‪ ،‬وقــد تخلــف عــن ســداد األجــرة لفتــرة طويلــة‬\n‫‪ ،‬وبالســؤال عنــه لــم جنــده منــذ شــهر رمضــان لعــام ‪1431‬ه ـ وســألنا‬\n‫عنــه بعملــه فأفادونــا بــأن املدعــى عليــه أخــذ خــروج نهائــي ‪ ،‬لــذا أطلــب‬\n‫احلكــم بفتــح الشــقة محــل الدعــوى وإخــاء العقــار ‪ .‬هــذه دعــواي ‪ .‬ثــم‬\n‫أبــرز املدعــي أصالــة ووكالــة عقــد اإليجــار ‪ ،‬ومت تزويــد أوراق املعاملــة‬\n\n\n                                                                                     ‫‪362‬‬\n\f      ‫بنســخة منــه ‪ ،‬كمــا أبــرز أصــل الصــك الصــادر مــن كتابــة العــدل‬\n      ‫األولــى بجــدة برقــم ‪ 1040‬يف ‪1421/1/27‬ه ـ واملهمــش عليــه بعبــارة‬\n      ‫(فقــد اصطلــح وتخــارج ورثــة املرأة‪.....‬عــن نصيبهــم يف هــذا العقــار لبقيــة‬\n      ‫ورثــة ‪.....‬وذلــك مبوجــب صــك املخارجــة الصــادر منــا برقــم ‪ 25/35‬يف‬\n      ‫‪1428/2/2‬ه ـ قالــه القاضــي باحملكمــة العامــة بالريــاض ‪..........‬جــرى‬\n      ‫إحلاقــة وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــة أجمعــن) أه ـ‬\n      ‫كمــا أبــرز صــورة صــك حصــر الورثــة الصــادر مــن محكمــة الريــاض‬\n      ‫برقــم ‪ 26/48‬وتاريــخ ‪1423/6/17‬ه ـ ونصــه (ثبــت بالبينــة املعدلــة‬\n      ‫وفــاة ‪.....‬بتاريــخ ‪1423/6/8‬ه ـ وانحصــار إرثــة يف والدتــة ‪.....‬املولــوده‬\n      ‫عــام ‪1343‬ه ـ ويف زوجتــة ‪.....‬املولــودة عــام ‪1360‬ه ـ ويف أوالدة البالغــن‬\n      ‫جميعــا وهــم ‪.....‬املولــود يف ‪1389‬ه ـ ‪.....‬املولــود عــام ‪1385‬ه ـ ‪.....‬املولــوده‬\n      ‫عــام ‪1386‬ه ـ ‪.....‬املولــوده عــام ‪1387‬ه ـ ‪.....‬املولــود عــام ‪1392‬ه ـ ‪.....‬‬\n      ‫املولــود عــام ‪1394‬ه ـ ‪.....‬املولــوده عــام ‪1398‬ه ـ ‪.....‬املولــود عــام ‪1403‬ه ـ‬\n      ‫وكانــت وفاتــة يف مدينــة جــده الســاعة الواحــدة ظهــرا) أه ـ كمــا أبــرز‬\n      ‫صــورة الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالريــاض برقــم‬\n      ‫‪ 56514‬وتاريخ‪1424/4/7‬ه ـ واملــوكل فيهــا مــن قبــل ‪.....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪..........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪.....‬باألصالــة عــن نفســيهما وبالوكالــة عــن ورثــة‬\n      ‫‪ .....‬بالوكالــة رقــم‪ 56505‬يف ‪1424 /4 /7‬ه ـ جلــد ‪ 9973‬الصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة ‪ ،‬كمــا أبــرز صــورة الوكالــة الصــادرة‬\n      ‫مــن كتابــة عــدل الريــاض الثانيــة برقــم ‪ 56505‬وتاريــخ ‪1424/4/7‬ه ـ‬\n      ‫والتــي تضمنــت مــا يلــي (حضــر كل مــن ‪ .....‬ســعودي مبوجــب ســجل‬\n      ‫مدنــي رقــم ‪ ...........‬و‪ .....‬ســعودي مبوجــب ســجل مدنــي رقــم ‪ .....‬و‪.....‬‬\n\n\n‫‪363‬‬\n\f‫ســعودي مبوجــب ســجل مدنــي رقــم ‪ .....‬و‪ .....‬ســعودية مبوجــب ســجل‬\n‫مدنــي رقــم ‪.....‬و‪ .....‬ســعودية مبوجــب ســجل مدنــي رقــم ‪.....‬و‪.....‬ســعودية‬\n‫مبوجــب ســجل مدنــي رقــم ‪ ..........‬ســعودية مبوجــب ســجل مدنــي رقــم‬\n‫‪ ........‬قرروا بقولهم أننا أقمنا ‪ .....‬و‪ .....‬ســعوديا اجلنســية) ‪ ،‬ومت إرفاقها‬\n‫باملعاملــة ‪،‬وبســؤال املدعــي أصالــة ووكالــة اليمــن علــى صحــة دعــواه‬\n‫اســتعد لذلــك ‪ ،‬ثــم حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو‬\n‫أن املدعــى عليــه ‪.....‬مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪.....‬مســتأجر‬\n‫لدينــا ملحــق شــقة رقــم ‪ 7‬مــن العمــارة مبدينــة جــدة بحــى ‪ ...‬واململوكــة‬\n‫لنــا بالصــك رقــم ‪ 1040‬يف ‪1421/1/27‬ه ـ ‪ ،‬مبوجــب عقــد إيجــار رقــم‬\n‫‪ 14‬وتاريــخ (بــدون) بأجــرة ســنوية قدرهــا اثنــا عشــر ألفــا وخمســمائة‬\n‫ريــال اعتبــارا مــن تاريــخ ‪1429/1/1‬ه ـ ‪ ،‬وقــد تخلــف عــن ســداد األجــرة‬\n‫لفتــرة طويلــة ‪ ،‬وبالســؤال عنــه لــم جنــده منذ شــهر رمضان لعــام ‪1431‬هـ‬\n‫وســألنا عنــه بعملــه فأفادونــا بــأن املدعــى عليــه أخــذ خــروج نهائــي ‪.‬‬\n‫هكــذا حلــف ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى والبينــة املتمثلــة يف‬\n‫الصــك رقــم ‪ 1040‬يف ‪1421/1/27‬ه ـ ‪ ،‬وعقــد إيجــار رقــم ‪ 14‬وتاريــخ‬\n‫(بــدون) ‪ ،‬وشــهادة الشــاهدين ‪ ...‬و‪ ...‬املعدلــة شــرعا ‪ ،‬وبنــاء علــى صــك‬\n‫حصــر الورثــة رقــم ‪ 26/48‬وتاريــخ ‪1423/6/17‬ه ـ ‪ ،‬وبنــاء علــى ميــن‬\n‫املدعــي أصالــة ووكالــة بصفتــه مباشــر عقــد اإليجــار وأحــد مــاك‬\n‫العقــار ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود)‪ ،‬وحلديــث‬\n‫(البينــة علــى املدعــي واليمــن علــى املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال‬\n‫أبــو عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب النبــي صلــى اهلل عليــه‬\n‫وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ‪،‬‬\n‫وحلديــث ( ال ضــرر و ال ضــرار ) رواه أبــو داوود وصححــه احلاكــم ‪،‬‬\n\n\n                                                                                        ‫‪364‬‬\n\f      ‫وألن الضــرر يف الشــريعة مرفــوع ‪ ،‬وبنــاء علــى املــادة ‪ 55‬و ‪ 176‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت بفتــح العقــار محــل‬\n      ‫الدعــوى وإخــاؤه عــن طريــق اجلهــات املختصة ‪ ،‬واالحتفــاظ مبوجودات‬\n      ‫العقــار مــا يخــص املدعــى عليــه منــه لــدى اجلهــة املعنيــة ‪ ،‬وأمــرت ببيــع مــا‬\n      ‫يخشــى تلفــه ‪ ،‬وإيــداع ثمنــه لــدى بيــت مــال احملكمــة ‪ .‬وبــه حكمــت ‪.‬‬\n      ‫وأفهمــت املدعــي بــأن املدعــى عليــه علــى حجتــه متــى حضــر ‪ ،‬وقــررت‬\n      ‫بعــث املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم ‪ .‬وأقفلــت اجللســة‬\n      ‫الســاعة ‪ . 02 : 00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/04/08‬ه ـ‬\n      ‫احلمد هلل والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪.:‬فقد جرى اطالعنا‬\n      ‫نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة الشــيخ ‪.....‬‬\n      ‫القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد ‪ 34185350‬وتاريــخ‬\n      ‫‪1434/4/10‬ه ـ املتضمــن دعــوى ‪.....‬ضــد ‪.....‬واحملكــوم فيــه مبــادون‬\n      ‫باطنــه ‪.‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم‬\n      ‫واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪365‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":358,"source_page_end":365,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b3f2ecb1246eb33f22893c5e31a2713f1b71e3b90fd8e313eaac853e6afe2277","normalized_text_hash":"313d531853d82f81a27d73f5988e66e7facaeb7969d4eb892bf86b3e5f07aa20","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p358-34185350"}]$archive_payload$::jsonb) AS x LIMIT 25
